--
-- Name: hotel_occupancy_report; Type: VIEW; Schema: public; Owner: odoo
--

CREATE VIEW public.hotel_occupancy_report AS
 SELECT b.id,
    COALESCE((b.check_in)::date, b.hour_date, (b.create_date)::date) AS date,
    b.company_id,
    b.room_id,
    b.room_type_id,
    b.rent_type,
    b.state,
    b.partner_id,
    b.nights_count,
    b.hours_duration,
    1 AS booking_count,
    b.amount_room,
    b.amount_services,
    b.amount_total
   FROM public.hotel_booking b
  WHERE ((b.state)::text <> ALL ((ARRAY['draft'::character varying, 'cancel'::character varying])::text[]));


