321	\N	\N	2026-10-30 15:25:53.546262	1	http://biblio.ohada.org/pmb/opac_css/doc_num.php?explnum_id=2063	{"en_US": ""}	l10n_syscohada	Odoo S.A.	/l10n_syscohada/static/description/icon.jpeg	uninstalled	\N	{"en_US": "OHADA - Accounting", "vi_VN": "OHADA - Kế toán"}	37	{"en_US": "\\nThis module implements the accounting chart for OHADA area.\\n===========================================================\\n\\nIt allows any company or association to manage its financial accounting.\\n\\nCountries that use OHADA are the following:\\n-------------------------------------------\\n    Benin, Burkina Faso, Cameroon, Central African Republic, Comoros, Congo,\\n\\n    Ivory Coast, Gabon, Guinea, Guinea Bissau, Equatorial Guinea, Mali, Niger,\\n\\n    Democratic Republic of the Congo, Senegal, Chad, Togo.\\n", "vi_VN": "\\nPhân hệ này triển khai sơ đồ kế toán cho khu vực OHADA.\\n==========================================================================\\n\\nVới phân hệ này, mọi công ty hay hiệp hội đều có khả năng quản lý kế toán tài chính của họ.\\n\\nCác quốc gia OHADA gồm:\\n-------------------------------------------\\n     Benin, Burkina Faso, Cameroon, Cộng hòa Trung Phi, Comoros, Congo,\\n\\n     Bờ Biển Ngà, Gabon, Guinea, Guinea Bissau, Guinea Xích đạo, Mali, Niger,\\n\\n     Cộng hòa Dân chủ Congo, Senegal, Chad, Togo.\\n"}	f	f	f	LGPL-3	100	f	f	\N	\N	\N	\N				official	\N
471	\N	\N	2026-10-30 15:25:53.546262	1		{"en_US": ""}	product_email_template	Odoo S.A.	/base/static/description/icon.png	uninstalled	\N	{"en_US": "Product Email Template", "vi_VN": "Mẫu email sản phẩm"}	2	{"en_US": "\\nAdd email templates to products to be sent on invoice confirmation\\n==================================================================\\n\\nWith this module, link your products to a template to send complete information and tools to your customer.\\nFor instance when invoicing a training, the training agenda and materials will automatically be sent to your customers.'\\n", "vi_VN": "\\nThêm mẫu email cho các sản phẩm để gửi kèm khi xác nhận hoá đơn\\n===================================================================\\n\\nVới phân hệ này, liên kết các sản phẩm với một mẫu để gửi thông tin và công cụ hoàn chỉnh đến khách hàng của bạn.\\nVí dụ khi lập hoá đơn cho một khóa đào tạo, chương trình và công cụ đào tạo sẽ được tự động gửi đến khách hàng.'\\n"}	f	f	f	LGPL-3	100	f	f	\N	\N	\N	\N				official	\N
396	\N	\N	2026-10-30 15:25:53.546262	1		{"en_US": ""}	onboarding	Odoo S.A.	/base/static/description/icon.png	installed	19.0.1.2	{"en_US": "Onboarding Toolbox", "vi_VN": "Hộp công cụ onboarding"}	4	{"en_US": "\\nThis module allows to manage onboardings and their progress\\n================================================================================\\n", "vi_VN": "\\nPhân hệ này cho phép quản lý hoạt động onboarding và tiến độ của hoạt động này\\n================================================================================\\n"}	f	f	f	LGPL-3	9001	f	f	\N	\N	\N	\N	Settings/Technical/User Interface/Onboardings\nSettings/Technical/User Interface/Onboardings Steps		onboarding.onboarding.step.view.form (form)\nonboarding.onboarding.step.view.list (list)\nonboarding.onboarding.view.form (form)\nonboarding.onboarding.view.list (list)\nonboarding_container (qweb)\nonboarding_panel (qweb)\nonboarding_step (qweb)	official	\N
