504	\N	\N	2026-10-30 15:25:53.546262	1		{"en_US": ""}	resource	Odoo S.A.	/base/static/description/icon.png	installed	19.0.1.1	{"en_US": "Resource", "vi_VN": "Tài nguyên"}	4	{"en_US": "\\nModule for resource management.\\n===============================\\n\\nA resource represent something that can be scheduled (a developer on a task or a\\nwork center on manufacturing orders). This module manages a resource calendar\\nassociated to every resource. It also manages the leaves of every resource.\\n", "vi_VN": "\\nPhân hệ để quản lý tài nguyên.\\n===============================\\n\\nMột tài nguyên đại diện cho một yếu tố nào đó có thể được lên lịch (một nhà phát triển của một nhiệm\\nvụ hoặc một khu vực sản xuất của các lệnh sản xuất). Phân hệ này quản lý một lịch tài nguyên \\nđược liên kết với mọi tài nguyên. Nó cũng quản lý nghỉ phép của mọi tài nguyên.\\n"}	f	f	f	LGPL-3	100	f	f	\N	\N	\N	\N	Settings/Technical/Resource\nSettings/Technical/Resource/Resource Time Off\nSettings/Technical/Resource/Resources\nSettings/Technical/Resource/Working Schedules		resource.calendar.attendance.form (form)\nresource.calendar.attendance.list (list)\nresource.calendar.form (form)\nresource.calendar.leaves.calendar (calendar)\nresource.calendar.leaves.form (form)\nresource.calendar.leaves.list (list)\nresource.calendar.leaves.search (search)\nresource.calendar.list (list)\nresource.calendar.search (search)\nresource.resource.form (form)\nresource.resource.list (list)\nresource.resource.search (search)	official	\N
