"many2one_uom"/>\n                <field name="lot_properties" optional="hide"/>\n                <button name="action_view_stock_moves" string="History" type="object" class="btn-link" icon="fa-history"/>\n                <button name="action_view_orderpoints" string="Replenishment" type="object" context="{'default_product_id': product_id, 'search_default_location_id': location_id}" class="btn-link" icon="fa-refresh"/>\n            </list>\n        	f	t	2026-10-13 11:46:51.305968	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
1032	16	\N	1	1	stock.storage.category.list	stock.storage.category	\N	list	stock/views/stock_storage_category_views.xml	primary	{"en_US": "<list string=\\"Storage Categories\\" multi_edit=\\"1\\">\\n                <field name=\\"name\\"/>\\n                <field name=\\"max_weight\\" string=\\"Max Weight\\"/>\\n                <field name=\\"allow_new_product\\"/>\\n                <field name=\\"company_id\\" groups=\\"base.group_multi_company\\"/>\\n            </list>", "vi_VN": "<list string=\\"Danh mục lưu kho\\" multi_edit=\\"1\\">\\n                <field name=\\"name\\"/>\\n                <field name=\\"max_weight\\" string=\\"Khối lượng tối đa\\"/>\\n                <field name=\\"allow_new_product\\"/>\\n                <field name=\\"company_id\\" groups=\\"base.group_multi_company\\"/>\\n            </list>"}	<?xml version="1.0"?>\n<list string="Storage Categories" multi_edit="1">\n                <field name="name"/>\n                <field name="max_weight" string="Max Weight"/>\n                <field name="allow_new_product"/>\n                <field name="company_id" groups="base.group_multi_company"/>\n            </list>\n        	f	t	2026-10-13 11:46:51.305968	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
1926	16	\N	1	1	M-Hotel Home Page	\N	m_hotel_website.hotel_home	qweb	m_hotel_website/views/website_templates.xml	primary	{"en_US": "<t name=\\"M-Hotel Home Page\\" t-name=\\"m_hotel_website.hotel_home\\">\\n            <t t-call=\\"website.layout\\">\\n                <div id=\\"wrap\\" class=\\"oe_structure oe_empty\\">\\n                    \\n                    <!-- Custom Inline CSS for Luxury Styling -->\\n                    <style>\\n                        :root {\\n                            --mhotel-gold: #c5a880;\\n                            --mhotel-gold-dark: #a38257;\\n                            --mhotel-dark: #111827;\\n                            --mhotel-navy: #0f172a;\\n                        }\\n                        .hero-banner {\\n                            background: linear-gradient(rgba(15, 23, 42, 0.75), rgba(15, 23, 42, 0.85)), url('https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&amp;fit=crop&amp;w=1920&amp;q=80') center/cover no-repeat;\\n                            min-height: 85vh;\\n                            display: flex;\\n                            align-items: center;\\n                            color: white;\\n                        }\\n                        .gold-text { color: #d4af37 !important; }\\n                        .gold-btn {\\n                            background: linear-gradient(135deg, #d4af37, #aa820a);\\n                            color: #111827 !important;\\n                            font-weight: 700;\\n                            border: none;\\n                            padding: 12px 28px;\\n                            border-radius: 8px;\\n                            transition: all 0.3s ease;\\n                        }\\n                        .gold-btn:hover {\\n                            background: linear-gradient(135deg, #e6c34e, #c5970c);\\n                            transform: translateY(-2px);\\n                            box-shadow: 0 8px 20px rgba(212, 175, 55, 0.35);\\n                        }\\n                        .booking-search-card {\\n                            background: rgba(255, 255, 255, 0.98);\\n                            backdrop-filter: blur(10px);\\n                            border-radius: 16px;\\n                            box-shadow: 0 20px 40px rgba(0,0,0,0.25);\\n                            margin-top: -60px;\\n                            position: relative;\\n                            z-index: 10;\\n                        }\\n                        .room-card {\\n                            border: 1px solid #e5e7eb;\\n                            border-radius: 14px;\\n                            overflow: hidden;\\n                            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\\n                            background: #ffffff;\\n                        }\\n                        .room-card:hover {\\n                            transform: translateY(-8px);\\n                            box-shadow: 0 16px 32px rgba(0,0,0,0.12);\\n                            border-color: #d4af37;\\n                        }\\n                        .service-icon-box {\\n                            width: 64px;\\n                            height: 64px;\\n                            border-radius: 16px;\\n                            background: #fbf6ec;\\n                            color: #aa820a;\\n                            display: flex;\\n                            align-items: center;\\n                            justify-content: center;\\n                            font-size: 28px;\\n                            margin: 0 auto 16px;\\n                        }\\n                    </style>\\n\\n                    <!-- Hero Section -->\\n                    <section class=\\"hero-banner text-center py-5\\">\\n                        <div class=\\"container py-5\\">\\n                            <div class=\\"row justify-content-center\\">\\n                                <div class=\\"col-lg-10\\">\\n                                    <span class=\\"badge bg-warning text-dark px-3 py-2 text-uppercase fw-bold rounded-pill mb-3\\">\\n                                        ✨ Khách Sạn &amp; Khu Nghỉ Dưỡng Đẳng Cấp 5 Sao\\n                                    </span>\\n                                    <h1 class=\\"display-3 fw-bold mb-3 text-white\\">\\n                                        M-HOTEL LUXURY HOSPITALITY\\n                                    </h1>\\n                                    <p class=\\"lead mb-4 text-light opacity-90 mx-auto\\" style=\\"max-width: 800px; font-size: 1.25rem;\\">\\n                                        Trải nghiệm không gian lưu trú và nghỉ dưỡng chuyên nghiệp tại \\n                                        <strong>Khách Sạn M (Cơ sở 1 - Gia Lai)</strong> &amp; <strong>M-Hotel Vũng Tàu (Cơ sở 2 - Vũng Tàu)</strong>.\\n                                    </p>\\n                                    <div class=\\"d-flex justify-content-center gap-3\\">\\n                                        <a href=\\"/hotel/booking\\" class=\\"gold-btn btn btn-lg\\">\\n                                            <i class=\\"fa fa-calendar-check-o me-2\\"/> Đặt Phòng Ngay\\n                                        </a>\\n                                        <a href=\\"/hotel/rooms\\" class=\\"btn btn-outline-light btn-lg px-4 rounded-3 fw-bold\\">\\n                                            <i class=\\"fa fa-bed me-2\\"/> Xem Các Hạng Phòng\\n                                        </a>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </section>\\n\\n                    <!-- Quick Booking Search Floating Bar -->\\n                    <div class=\\"container mb-5\\">\\n                        <div class=\\"booking-search-card p-4\\">\\n                            <form action=\\"/hotel/booking\\" method=\\"GET\\" class=\\"row g-3 align-items-end\\">\\n                                <div class=\\"col-md-3\\">\\n                                    <label class=\\"form-label fw-bold text-dark mb-1\\">\\n                                        <i class=\\"fa fa-map-marker text-danger me-1\\"/> Chi Nhánh Khách Sạn\\n                                    </label>\\n                                    <select class=\\"form-select form-select-lg border-2\\" name=\\"company_id\\">\\n                                        <t t-foreach=\\"companies\\" t-as=\\"c\\">\\n                                            <option t-att-value=\\"c.id\\" t-esc=\\"c.name\\"/>\\n                                        </t>\\n                                    </select>\\n                                </div>\\n                                <div class=\\"col-md-3\\">\\n                                    <label class=\\"form-label fw-bold text-dark mb-1\\">\\n                                        <i class=\\"fa fa-home gold-text me-1\\"/> Hạng Phòng Ưa Thích\\n                                    </label>\\n                                    <select class=\\"form-select form-select-lg border-2\\" name=\\"type_id\\">\\n                                        <t t-foreach=\\"room_types\\" t-as=\\"rt\\">\\n                                            <option t-att-value=\\"rt.id\\" t-esc=\\"rt.name\\"/>\\n                                        </t>\\n                                    </select>\\n                                </div>\\n                                <div class=\\"col-md-2\\">\\n                                    <label class=\\"form-label fw-bold text-dark mb-1\\">\\n                                        <i class=\\"fa fa-clock-o text-primary me-1\\"/> Hình Thức Thuê\\n                                    </label>\\n                                    <select class=\\"form-select form-select-lg border-2\\" name=\\"rent_type\\">\\n                                        <option value=\\"night\\">Theo đêm</option>\\n                                        <option value=\\"hour\\">Theo giờ</option>\\n                                    </select>\\n                                </div>\\n                                <div class=\\"col-md-4\\">\\n                                    <button type=\\"submit\\" class=\\"gold-btn btn btn-lg w-100 py-3\\">\\n                                        <i class=\\"fa fa-search me-2\\"/> Tìm Phòng &amp; Báo Giá\\n                                    </button>\\n                                </div>\\n                            </form>\\n                        </div>\\n                    </div>\\n\\n                    <!-- Branches Showcase Section -->\\n                    <section class=\\"py-5 bg-light\\">\\n                        <div class=\\"container py-3\\">\\n                            <div class=\\"text-center mb-5\\">\\n                                <span class=\\"text-uppercase fw-bold text-warning small tracking-wide\\">Hệ Thống Lưu Trú Khách Sạn M</span>\\n                                <h2 class=\\"fw-bold text-dark mt-1\\">Hai Cơ Sở Hoạt Động Tại Gia Lai &amp; Vũng Tàu</h2>\\n                                <p class=\\"text-muted mx-auto\\" style=\\"max-width: 650px;\\">\\n                                    Hệ thống cơ sở lưu trú đồng bộ phục vụ khách du lịch, đoàn trải nghiệm và khách công tác tại Trụ sở chính (Gia Lai) cùng Chi nhánh nghỉ dưỡng mở rộng (Vũng Tàu).\\n                                </p>\\n                            </div>\\n                            <div class=\\"row g-4\\">\\n                                <!-- Co so 1 Gia Lai -->\\n                                <div class=\\"col-lg-6\\">\\n                                    <div class=\\"card border-0 shadow-sm rounded-4 overflow-hidden h-100\\">\\n                                        <img src=\\"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&amp;fit=crop&amp;w=800&amp;q=80\\" class=\\"card-img-top\\" style=\\"height: 300px; object-fit: cover;\\" alt=\\"Cơ sở 1 Gia Lai\\"/>\\n                                        <div class=\\"card-body p-4\\">\\n                                            <div class=\\"d-flex justify-content-between align-items-center mb-2\\">\\n                                                <h3 class=\\"card-title fw-bold h4 mb-0 text-dark\\">Khách Sạn M (Cơ sở 1 - Gia Lai)</h3>\\n                                                <span class=\\"badge bg-primary px-3 py-2 rounded-pill\\">13 Phòng Nghỉ</span>\\n                                            </div>\\n                                            <p class=\\"text-muted mb-3\\">\\n                                                <i class=\\"fa fa-map-marker text-danger me-1\\"/> Thôn Dương Liễu Tây, xã Bình Dương, Tỉnh Gia Lai\\n                                            </p>\\n                                            <p class=\\"card-text text-secondary mb-4\\">\\n                                                Trụ sở chính khách sạn với 13 phòng bố trí từ tầng 1 đến tầng 3. Không gian yên tĩnh, tiện nghi với 4 hạng phòng: Phòng đơn, Phòng đôi, Phòng ba giường và Phòng tập thể. Đơn giá chỉ từ 250.000 VNĐ/đêm.\\n                                            </p>\\n                                            <a href=\\"/hotel/booking?company_id=1\\" class=\\"btn btn-outline-dark fw-bold rounded-pill px-4\\">\\n                                                Đặt phòng Cơ sở Gia Lai →\\n                                            </a>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                                <!-- Co so 2 Vung Tau -->\\n                                <div class=\\"col-lg-6\\">\\n                                    <div class=\\"card border-0 shadow-sm rounded-4 overflow-hidden h-100\\">\\n                                        <img src=\\"https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&amp;fit=crop&amp;w=800&amp;q=80\\" class=\\"card-img-top\\" style=\\"height: 300px; object-fit: cover;\\" alt=\\"Cơ sở 2 Vũng Tàu\\"/>\\n                                        <div class=\\"card-body p-4\\">\\n                                            <div class=\\"d-flex justify-content-between align-items-center mb-2\\">\\n                                                <h3 class=\\"card-title fw-bold h4 mb-0 text-dark\\">M-Hotel Vũng Tàu (Cơ sở 2 - Vũng Tàu)</h3>\\n                                                <span class=\\"badge bg-success px-3 py-2 rounded-pill\\">18 Phòng (Tầng 1 - 5)</span>\\n                                            </div>\\n                                            <p class=\\"text-muted mb-3\\">\\n                                                <i class=\\"fa fa-map-marker text-danger me-1\\"/> 125 Thùy Vân, Phường Thắng Tam, TP. Vũng Tàu, Tỉnh Bà Rịa – Vũng Tàu\\n                                            </p>\\n                                            <p class=\\"card-text text-secondary mb-4\\">\\n                                                Chi nhánh nghỉ dưỡng quy mô mở rộng gồm 18 phòng bố trí từ Tầng 1 đến Tầng 5 mặt tiền Bãi Sau Thùy Vân, trang bị bồn sục thư giãn, phòng gia đình và căn hộ áp mái ngắm toàn cảnh biển 180 độ. Đơn giá chỉ từ 500.000 VNĐ/đêm.\\n                                            </p>\\n                                            <a href=\\"/hotel/booking?company_id=2\\" class=\\"btn btn-outline-dark fw-bold rounded-pill px-4\\">\\n                                                Đặt phòng Cơ sở Vũng Tàu →\\n                                            </a>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </section>\\n\\n                    <!-- Featured Room Types Section -->\\n                    <section class=\\"py-5\\">\\n                        <div class=\\"container py-3\\">\\n                            <div class=\\"d-flex justify-content-between align-items-end mb-4\\">\\n                                <div>\\n                                    <span class=\\"text-uppercase fw-bold text-warning small tracking-wide\\">Bộ Sưu Tập Phòng</span>\\n                                    <h2 class=\\"fw-bold text-dark mt-1\\">Các Hạng Phòng Tiêu Chuẩn 5 Sao</h2>\\n                                </div>\\n                                <a href=\\"/hotel/rooms\\" class=\\"btn btn-outline-secondary fw-bold rounded-pill px-4\\">\\n                                    Xem tất cả hạng phòng\\n                                </a>\\n                            </div>\\n                            <div class=\\"row g-4\\">\\n                                <t t-foreach=\\"room_types\\" t-as=\\"rt\\">\\n                                    <div class=\\"col-lg-4 col-md-6\\">\\n                                        <div class=\\"room-card h-100 d-flex flex-column\\">\\n                                            <div class=\\"position-relative\\">\\n                                                <img src=\\"https://images.unsplash.com/photo-1618773928121-c32242e63f39?auto=format&amp;fit=crop&amp;w=600&amp;q=80\\" class=\\"w-100\\" style=\\"height: 220px; object-fit: cover;\\" alt=\\"Room Image\\"/>\\n                                                <div class=\\"position-absolute top-0 end-0 m-3\\">\\n                                                    <span class=\\"badge bg-dark px-3 py-2 rounded-pill fw-bold\\">\\n                                                        <i class=\\"fa fa-users me-1\\"/> <t t-esc=\\"rt.capacity\\"/> Khách\\n                                                    </span>\\n                                                </div>\\n                                            </div>\\n                                            <div class=\\"p-4 d-flex flex-column flex-grow-1\\">\\n                                                <h3 class=\\"h5 fw-bold text-dark mb-2\\" t-esc=\\"rt.name\\"/>\\n                                                <p class=\\"text-muted small mb-3 flex-grow-1\\" t-esc=\\"rt.description or 'Trang thiết bị hiện đại, nệm cao cấp, minibar, bồn tắm nằm và view thoáng đãng.'\\"/>\\n                                                <div class=\\"d-flex justify-content-between align-items-baseline pt-3 border-top mb-3\\">\\n                                                    <div>\\n                                                        <small class=\\"text-muted d-block\\">Giá theo đêm</small>\\n                                                        <span class=\\"h4 fw-bold text-danger mb-0\\">\\n                                                            <t t-esc=\\"'{:,.0f}'.format(rt.base_price_night)\\"/> đ\\n                                                        </span>\\n                                                        <small class=\\"text-muted\\">/đêm</small>\\n                                                    </div>\\n                                                    <div class=\\"text-end\\">\\n                                                        <small class=\\"text-muted d-block\\">Giá theo giờ</small>\\n                                                        <span class=\\"fw-bold text-dark\\">\\n                                                            <t t-esc=\\"'{:,.0f}'.format(rt.base_price_hour)\\"/> đ\\n                                                        </span>\\n                                                        <small class=\\"text-muted\\">/giờ đầu</small>\\n                                                    </div>\\n                                                </div>\\n                                                <a t-att-href=\\"'/hotel/booking?type_id=%s' % rt.id\\" class=\\"gold-btn btn text-center w-100\\">\\n                                                    <i class=\\"fa fa-check-circle me-1\\"/> Đặt Phòng Này\\n                                                </a>\\n                                            </div>\\n                                        </div>\\n                                    </div>\\n                                </t>\\n                            </div>\\n                        </div>\\n                    </section>\\n\\n                    <!-- Hotel Amenities & Services -->\\n                    <section class=\\"py-5 bg-dark text-white\\">\\n                        <div class=\\"container py-4 text-center\\">\\n                            <span class=\\"text-uppercase fw-bold gold-text small tracking-wide\\">Dịch Vụ Đẳng Cấp</span>\\n                            <h2 class=\\"fw-bold text-white mt-1 mb-5\\">Tiện Ích Nghỉ Dưỡng Toàn Diện</h2>\\n                            <div class=\\"row g-4\\">\\n                                <div class=\\"col-md-3 col-6\\">\\n                                    <div class=\\"service-icon-box\\">\\n                                        <i class=\\"fa fa-cutlery\\"/>\\n                                    </div>\\n                                    <h4 class=\\"h5 fw-bold text-white mb-2\\">Ẩm Thực Fine Dining</h4>\\n                                    <p class=\\"text-light opacity-75 small\\">Nhà hàng Á - Âu với đầu bếp 5 sao và Room Service phục vụ tận phòng 24/7.</p>\\n                                </div>\\n                                <div class=\\"col-md-3 col-6\\">\\n                                    <div class=\\"service-icon-box\\">\\n                                        <i class=\\"fa fa-life-ring\\"/>\\n                                    </div>\\n                                    <h4 class=\\"h5 fw-bold text-white mb-2\\">Hồ Bơi Vô Cực</h4>\\n                                    <p class=\\"text-light opacity-75 small\\">Hồ bơi tràn bờ trên cao view triệu đô ngắm trọn hoàng hôn tuyệt mỹ.</p>\\n                                </div>\\n                                <div class=\\"col-md-3 col-6\\">\\n                                    <div class=\\"service-icon-box\\">\\n                                        <i class=\\"fa fa-heartbeat\\"/>\\n                                    </div>\\n                                    <h4 class=\\"h5 fw-bold text-white mb-2\\">Spa &amp; Trị Liệu</h4>\\n                                    <p class=\\"text-light opacity-75 small\\">Liệu pháp massage thảo mộc truyền thống phục hồi năng lượng tinh thần.</p>\\n                                </div>\\n                                <div class=\\"col-md-3 col-6\\">\\n                                    <div class=\\"service-icon-box\\">\\n                                        <i class=\\"fa fa-car\\"/>\\n                                    </div>\\n                                    <h4 class=\\"h5 fw-bold text-white mb-2\\">Đưa Đón VIP</h4>\\n                                    <p class=\\"text-light opacity-75 small\\">Đội xe Limousine và Mercedes đưa đón sân bay Tân Sơn Nhất chu đáo.</p>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </section>\\n\\n                </div>\\n            </t>\\n        </t>"}	<t name="M-Hotel Home Page" t-name="m_hotel_website.hotel_home">\n            <t t-call="website.layout">\n                <div id="wrap" class="oe_structure oe_empty">\n                    \n                    <!-- Custom Inline CSS for Luxury Styling -->\n                    <style>\n                        :root {\n                            --mhotel-gold: #c5a880;\n                            --mhotel-gold-dark: #a38257;\n                            --mhotel-dark: #111827;\n                            --mhotel-navy: #0f172a;\n                        }\n                        .hero-banner {\n                            background: linear-gradient(rgba(15, 23, 42, 0.75), rgba(15, 23, 42, 0.85)), url('https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&amp;fit=crop&amp;w=1920&amp;q=80') center/cover no-repeat;\n                            min-height: 85vh;\n                            display: flex;\n                            align-items: center;\n                            color: white;\n                        }\n                        .gold-text { color: #d4af37 !important; }\n                        .gold-btn {\n                            background: linear-gradient(135deg, #d4af37, #aa820a);\n                            color: #111827 !important;\n                            font-weight: 700;\n                            border: none;\n                            padding: 12px 28px;\n                            border-radius: 8px;\n                            transition: all 0.3s ease;\n                        }\n                        .gold-btn:hover {\n                            background: linear-gradient(135deg, #e6c34e, #c5970c);\n                            transform: translateY(-2px);\n                            box-shadow: 0 8px 20px rgba(212, 175, 55, 0.35);\n                        }\n                        .booking-search-card {\n                            background: rgba(255, 255, 255, 0.98);\n                            backdrop-filter: blur(10px);\n                            border-radius: 16px;\n                            box-shadow: 0 20px 40px rgba(0,0,0,0.25);\n                            margin-top: -60px;\n                            position: relative;\n                            z-index: 10;\n                        }\n                        .room-card {\n                            border: 1px solid #e5e7eb;\n                            border-radius: 14px;\n                            overflow: hidden;\n                            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n                            background: #ffffff;\n                        }\n                        .room-card:hover {\n                            transform: translateY(-8px);\n                            box-shadow: 0 16px 32px rgba(0,0,0,0.12);\n                            border-color: #d4af37;\n                        }\n                        .service-icon-box {\n                            width: 64px;\n                            height: 64px;\n                            border-radius: 16px;\n                            background: #fbf6ec;\n                            color: #aa820a;\n                            display: flex;\n                            align-items: center;\n                            justify-content: center;\n                            font-size: 28px;\n                            margin: 0 auto 16px;\n                        }\n                    </style>\n\n                    <!-- Hero Section -->\n                    <section class="hero-banner text-center py-5">\n                        <div class="container py-5">\n                            <div class="row justify-content-center">\n                                <div class="col-lg-10">\n                                    <span class="badge bg-warning text-dark px-3 py-2 text-uppercase fw-bold rounded-pill mb-3">\n                                        ✨ Khách Sạn &amp; Khu Nghỉ Dưỡng Đẳng Cấp 5 Sao\n                                    </span>\n                                    <h1 class="display-3 fw-bold mb-3 text-white">\n                                        M-HOTEL LUXURY HOSPITALITY\n                                    </h1>\n                                    <p class="lead mb-4 text-light opacity-90 mx-auto" style="max-width: 800px; font-size: 1.25rem;">\n                                        Trải nghiệm không gian lưu trú và nghỉ dưỡng chuyên nghiệp tại \n                                        <strong>Khách Sạn M (Cơ sở 1 - Gia Lai)</strong> &amp; <strong>M-Hotel Vũng Tàu (Cơ sở 2 - Vũng Tàu)</strong>.\n                                    </p>\n                                    <div class="d-flex justify-content-center gap-3">\n                                        <a href="/hotel/booking" class="gold-btn btn btn-lg">\n                                            <i class="fa fa-calendar-check-o me-2"/> Đặt Phòng Ngay\n                                        </a>\n                                        <a href="/hotel/rooms" class="btn btn-outline-light btn-lg px-4 rounded-3 fw-bold">\n                                            <i class="fa fa-bed me-2"/> Xem Các Hạng Phòng\n                                        </a>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </section>\n\n                    <!-- Quick Booking Search Floating Bar -->\n                    <div class="container mb-5">\n                        <div class="booking-search-card p-4">\n                            <form action="/hotel/booking" method="GET" class="row g-3 align-items-end">\n                                <div class="col-md-3">\n                                    <label class="form-label fw-bold text-dark mb-1">\n                                        <i class="fa fa-map-marker text-danger me-1"/> Chi Nhánh Khách Sạn\n                                    </label>\n                                    <select class="form-select form-select-lg border-2" name="company_id">\n                                        <t t-foreach="companies" t-as="c">\n                                            <option t-att-value="c.id" t-esc="c.name"/>\n                                        </t>\n                                    </select>\n                                </div>\n                                <div class="col-md-3">\n                                    <label class="form-label fw-bold text-dark mb-1">\n                                        <i class="fa fa-home gold-text me-1"/> Hạng Phòng Ưa Thích\n                                    </label>\n                                    <select class="form-select form-select-lg border-2" name="type_id">\n                                        <t t-foreach="room_types" t-as="rt">\n                                            <option t-att-value="rt.id" t-esc="rt.name"/>\n                                        </t>\n                                    </select>\n                                </div>\n                                <div class="col-md-2">\n                                    <label class="form-label fw-bold text-dark mb-1">\n                                        <i class="fa fa-clock-o text-primary me-1"/> Hình Thức Thuê\n                                    </label>\n                                    <select class="form-select form-select-lg border-2" name="rent_type">\n                                        <option value="night">Theo đêm</option>\n                                        <option value="hour">Theo giờ</option>\n                                    </select>\n                                </div>\n                                <div class="col-md-4">\n                                    <button type="submit" class="gold-btn btn btn-lg w-100 py-3">\n                                        <i class="fa fa-search me-2"/> Tìm Phòng &amp; Báo Giá\n                                    </button>\n                                </div>\n                            </form>\n                        </div>\n                    </div>\n\n                    <!-- Branches Showcase Section -->\n                    <section class="py-5 bg-light">\n                        <div class="container py-3">\n                            <div class="text-center mb-5">\n                                <span class="text-uppercase fw-bold text-warning small tracking-wide">Hệ Thống Lưu Trú Khách Sạn M</span>\n                                <h2 class="fw-bold text-dark mt-1">Hai Cơ Sở Hoạt Động Tại Gia Lai &amp; Vũng Tàu</h2>\n                                <p class="text-muted mx-auto" style="max-width: 650px;">\n                                    Hệ thống cơ sở lưu trú đồng bộ phục vụ khách du lịch, đoàn trải nghiệm và khách công tác tại Trụ sở chính (Gia Lai) cùng Chi nhánh nghỉ dưỡng mở rộng (Vũng Tàu).\n                                </p>\n                            </div>\n                            <div class="row g-4">\n                                <!-- Co so 1 Gia Lai -->\n                                <div class="col-lg-6">\n                                    <div class="card border-0 shadow-sm rounded-4 overflow-hidden h-100">\n                                        <img src="https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&amp;fit=crop&amp;w=800&amp;q=80" class="card-img-top" style="height: 300px; object-fit: cover;" alt="Cơ sở 1 Gia Lai"/>\n                                        <div class="card-body p-4">\n                                            <div class="d-flex justify-content-between align-items-center mb-2">\n                                                <h3 class="card-title fw-bold h4 mb-0 text-dark">Khách Sạn M (Cơ sở 1 - Gia Lai)</h3>\n                                                <span class="badge bg-primary px-3 py-2 rounded-pill">13 Phòng Nghỉ</span>\n                                            </div>\n                                            <p class="text-muted mb-3">\n                                                <i class="fa fa-map-marker text-danger me-1"/> Thôn Dương Liễu Tây, xã Bình Dương, Tỉnh Gia Lai\n                                            </p>\n                                            <p class="card-text text-secondary mb-4">\n                                                Trụ sở chính khách sạn với 13 phòng bố trí từ tầng 1 đến tầng 3. Không gian yên tĩnh, tiện nghi với 4 hạng phòng: Phòng đơn, Phòng đôi, Phòng ba giường và Phòng tập thể. Đơn giá chỉ từ 250.000 VNĐ/đêm.\n                                            </p>\n                                            <a href="/hotel/booking?company_id=1" class="btn btn-outline-dark fw-bold rounded-pill px-4">\n                                                Đặt phòng Cơ sở Gia Lai →\n                                            </a>\n                                        </div>\n                                    </div>\n                                </div>\n                                <!-- Co so 2 Vung Tau -->\n                                <div class="col-lg-6">\n                                    <div class="card border-0 shadow-sm rounded-4 overflow-hidden h-100">\n                                        <img src="https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&amp;fit=crop&amp;w=800&amp;q=80" class="card-img-top" style="height: 300px; object-fit: cover;" alt="Cơ sở 2 Vũng Tàu"/>\n                                        <div class="card-body p-4">\n                                            <div class="d-flex justify-content-between align-items-center mb-2">\n                                                <h3 class="card-title fw-bold h4 mb-0 text-dark">M-Hotel Vũng Tàu (Cơ sở 2 - Vũng Tàu)</h3>\n                                                <span class="badge bg-success px-3 py-2 rounded-pill">18 Phòng (Tầng 1 - 5)</span>\n                                            </div>\n                                            <p class="text-muted mb-3">\n                                                <i class="fa fa-map-marker text-danger me-1"/> 125 Thùy Vân, Phường Thắng Tam, TP. Vũng Tàu, Tỉnh Bà Rịa – Vũng Tàu\n                                            </p>\n                                            <p class="card-text text-secondary mb-4">\n                                                Chi nhánh nghỉ dưỡng quy mô mở rộng gồm 18 phòng bố trí từ Tầng 1 đến Tầng 5 mặt tiền Bãi Sau Thùy Vân, trang bị bồn sục thư giãn, phòng gia đình và căn hộ áp mái ngắm toàn cảnh biển 180 độ. Đơn giá chỉ từ 500.000 VNĐ/đêm.\n                                            </p>\n                                            <a href="/hotel/booking?company_id=2" class="btn btn-outline-dark fw-bold rounded-pill px-4">\n                                                Đặt phòng Cơ sở Vũng Tàu →\n                                            </a>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </section>\n\n                    <!-- Featured Room Types Section -->\n                    <section class="py-5">\n                        <div class="container py-3">\n                            <div class="d-flex justify-content-between align-items-end mb-4">\n                                <div>\n                                    <span class="text-uppercase fw-bold text-warning small tracking-wide">Bộ Sưu Tập Phòng</span>\n                                    <h2 class="fw-bold text-dark mt-1">Các Hạng Phòng Tiêu Chuẩn 5 Sao</h2>\n                                </div>\n                                <a href="/hotel/rooms" class="btn btn-outline-secondary fw-bold rounded-pill px-4">\n                                    Xem tất cả hạng phòng\n                                </a>\n                            </div>\n                            <div class="row g-4">\n                                <t t-foreach="room_types" t-as="rt">\n                                    <div class="col-lg-4 col-md-6">\n                                        <div class="room-card h-100 d-flex flex-column">\n                                            <div class="position-relative">\n                                                <img src="https://images.unsplash.com/photo-1618773928121-c32242e63f39?auto=format&amp;fit=crop&amp;w=600&amp;q=80" class="w-100" style="height: 220px; object-fit: cover;" alt="Room Image"/>\n                                                <div class="position-absolute top-0 end-0 m-3">\n                                                    <span class="badge bg-dark px-3 py-2 rounded-pill fw-bold">\n                                                        <i class="fa fa-users me-1"/> <t t-esc="rt.capacity"/> Khách\n                                                    </span>\n                                                </div>\n                                            </div>\n                                            <div class="p-4 d-flex flex-column flex-grow-1">\n                                                <h3 class="h5 fw-bold text-dark mb-2" t-esc="rt.name"/>\n                                                <p class="text-muted small mb-3 flex-grow-1" t-esc="rt.description or 'Trang thiết bị hiện đại, nệm cao cấp, minibar, bồn tắm nằm và view thoáng đãng.'"/>\n                                                <div class="d-flex justify-content-between align-items-baseline pt-3 border-top mb-3">\n                                                    <div>\n                                                        <small class="text-muted d-block">Giá theo đêm</small>\n                                                        <span class="h4 fw-bold text-danger mb-0">\n                                                            <t t-esc="'{:,.0f}'.format(rt.base_price_night)"/> đ\n                                                        </span>\n                                                        <small class="text-muted">/đêm</small>\n                                                    </div>\n                                                    <div class="text-end">\n                                                        <small class="text-muted d-block">Giá theo giờ</small>\n                                                        <span class="fw-bold text-dark">\n                                                            <t t-esc="'{:,.0f}'.format(rt.base_price_hour)"/> đ\n                                                        </span>\n                                                        <small class="text-muted">/giờ đầu</small>\n                                                    </div>\n                                                </div>\n                                                <a t-att-href="'/hotel/booking?type_id=%s' % rt.id" class="gold-btn btn text-center w-100">\n                                                    <i class="fa fa-check-circle me-1"/> Đặt Phòng Này\n                                                </a>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </t>\n                            </div>\n                        </div>\n                    </section>\n\n                    <!-- Hotel Amenities & Services -->\n                    <section class="py-5 bg-dark text-white">\n                        <div class="container py-4 text-center">\n                            <span class="text-uppercase fw-bold gold-text small tracking-wide">Dịch Vụ Đẳng Cấp</span>\n                            <h2 class="fw-bold text-white mt-1 mb-5">Tiện Ích Nghỉ Dưỡng Toàn Diện</h2>\n                            <div class="row g-4">\n                                <div class="col-md-3 col-6">\n                                    <div class="service-icon-box">\n                                        <i class="fa fa-cutlery"/>\n                                    </div>\n                                    <h4 class="h5 fw-bold text-white mb-2">Ẩm Thực Fine Dining</h4>\n                                    <p class="text-light opacity-75 small">Nhà hàng Á - Âu với đầu bếp 5 sao và Room Service phục vụ tận phòng 24/7.</p>\n                                </div>\n                                <div class="col-md-3 col-6">\n                                    <div class="service-icon-box">\n                                        <i class="fa fa-life-ring"/>\n                                    </div>\n                                    <h4 class="h5 fw-bold text-white mb-2">Hồ Bơi Vô Cực</h4>\n                                    <p class="text-light opacity-75 small">Hồ bơi tràn bờ trên cao view triệu đô ngắm trọn hoàng hôn tuyệt mỹ.</p>\n                                </div>\n                                <div class="col-md-3 col-6">\n                                    <div class="service-icon-box">\n                                        <i class="fa fa-heartbeat"/>\n                                    </div>\n                                    <h4 class="h5 fw-bold text-white mb-2">Spa &amp; Trị Liệu</h4>\n                                    <p class="text-light opacity-75 small">Liệu pháp massage thảo mộc truyền thống phục hồi năng lượng tinh thần.</p>\n                                </div>\n                                <div class="col-md-3 col-6">\n                                    <div class="service-icon-box">\n                                        <i class="fa fa-car"/>\n                                    </div>\n                                    <h4 class="h5 fw-bold text-white mb-2">Đưa Đón VIP</h4>\n                                    <p class="text-light opacity-75 small">Đội xe Limousine và Mercedes đưa đón sân bay Tân Sơn Nhất chu đáo.</p>\n                                </div>\n                            </div>\n                        </div>\n                    </section>\n\n                </div>\n            </t>\n        </t>	f	t	2026-10-13 14:47:20.18786	2026-10-30 15:25:53.546262	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
