k mb-0\\" t-esc=\\"rt.name\\"/>\\n                                                        <span class=\\"badge bg-warning text-dark px-3 py-2 rounded-pill fw-bold\\">\\n                                                            Mã: <t t-esc=\\"rt.code\\"/>\\n                                                        </span>\\n                                                    </div>\\n                                                    <p class=\\"text-muted mb-3\\" t-esc=\\"rt.description or 'Không gian rộng rãi, ban công view thoáng, trang bị Smart TV, máy lạnh Inverter, két sắt điện tử và minibar cao cấp.'\\"/>\\n                                                    \\n                                                    <div class=\\"row g-2 mb-3\\">\\n                                                        <div class=\\"col-sm-3 col-6\\">\\n                                                            <small class=\\"text-muted d-block\\"><i class=\\"fa fa-users text-primary me-1\\"/> Sức chứa</small>\\n                                                            <span class=\\"fw-bold\\"><t t-esc=\\"rt.capacity\\"/> người lớn</span>\\n                                                        </div>\\n                                                        <div class=\\"col-sm-3 col-6\\">\\n                                                            <small class=\\"text-muted d-block\\"><i class=\\"fa fa-bed text-success me-1\\"/> Loại giường</small>\\n                                                            <span class=\\"fw-bold text-capitalize\\"><t t-esc=\\"rt.bed_type or 'King Size'\\"/></span>\\n                                                        </div>\\n                                                        <div class=\\"col-sm-3 col-6\\">\\n                                                            <small class=\\"text-muted d-block\\"><i class=\\"fa fa-wifi text-info me-1\\"/> Wifi Free</small>\\n                                                       