   <select class=\\"form-select form-select-lg\\" name=\\"company_id\\" id=\\"select_company_id\\" required=\\"required\\">\\n                                            <t t-foreach=\\"companies\\" t-as=\\"c\\">\\n                                                <option t-att-value=\\"c.id\\" t-att-selected=\\"c.id == selected_company_id\\" t-esc=\\"c.name\\"/>\\n                                            </t>\\n                                        </select>\\n                                    </div>\\n                                    <div class=\\"col-md-4\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Hạng Phòng <span class=\\"text-danger\\">*</span></label>\\n                                        <select class=\\"form-select form-select-lg\\" name=\\"room_type_id\\" id=\\"select_room_type_id\\" required=\\"required\\">\\n                                            <t t-foreach=\\"room_types\\" t-as=\\"rt\\">\\n                                                <option t-att-value=\\"rt.id\\" t-att-selected=\\"rt.id == selected_type_id\\" t-esc=\\"'%s (%s đ/đêm)' % (rt.name, '{:,.0f}'.format(rt.base_price_night))\\"/>\\n                                            </t>\\n                                        </select>\\n                                    </div>\\n                                    <div class=\\"col-md-4\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Số Phòng Cụ Thể <span class=\\"badge bg-light text-secondary border\\">Tùy chọn</span></label>\\n                                        <select class=\\"form-select form-select-lg\\" name=\\"room_id\\" id=\\"select_room_id\\">\\n                                            <option value=\\"\\">-- Tự động xếp phòng trống tốt nhất --</option>\\n                                            <t t-foreach=\\"rooms\\" t-as=\\"r\\">\\n                                                <option t-att-value=\\"r.id\\" t-att-data-company=\\"r.company_id.id\\" t-att-data-type=\\"r.room_type_id.id\\" t-esc=\\"'Phòng %s - %s (%s)' % (r.name, r.floor or 'Tầng 1', r.company_id.name)\\"/>\\n                                            </t>\\n                                        </select>\\n                                    </div>\\n                                    <div class=\\"col-md-4\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Hình Thức Thuê <span class=\\"text-danger\\">*</span></label>\\n                                        <select class=\\"form-select form-select-lg\\" name=\\"rent_type\\" required=\\"required\\">\\n                                            <option value=\\"night\\" selected=\\"selected\\">Thuê theo đêm</option>\\n                                            <option value=\\"hour\\">Thuê theo giờ</option>\\n                                        </select>\\n                                    </div>\\n                                    <div class=\\"col-md-4\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Thời Gian Nhận Phòng <span class=\\"text-danger\\">*</span></label>\\n                                        <input type=\\"datetime-local\\" class=\\"form-control form-control-lg\\" name=\\"check_in\\" t-att-value=\\"default_check_in\\" required=\\"required\\"/>\\n                                    </div>\\n                                    <div class=\\"col-md-4\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Thời Gian Trả Phòng <span class=\\"text-danger\\">*</span></label>\\n                                        <input type=\\"datetime-local\\" class=\\"form-control form-control-lg\\" name=\\"check_out\\" t-att-value=\\"default_check_out\\" required=\\"required\\"/>\\n                                    </div>\\n                                </div>\\n\\n                                <!-- Section 2: Thông tin khách hàng -->\\n                                <h2 class=\\"h5 fw-bold text-dark mb-4 pb-2 border-bottom\\">\\n                                    <i class=\\"fa fa-user-circle text-primary me-2\\"/> 2. Thông Tin Khách Hàng\\n                                </h2>\\n                                <div class=\\"row g-3 mb-4\\">\\n                                    <div class=\\"col-md-6\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Họ Và Tên <span class=\\"text-danger\\">*</span></label>\\n                                        <input type=\\"text\\" class=\\"form-control form-control-lg\\" name=\\"customer_name\\" placeholder=\\"Nguyễn Văn A\\" required=\\"required\\"/>\\n                                    </div>\\n                                    <div class=\\"col-md-6\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Số Điện Thoại <span class=\\"text-danger\\">*</span></label>\\n                                        <input type=\\"tel\\" class=\\"form-control form-control-lg\\" name=\\"phone\\" placeholder=\\"0901234567\\" required=\\"required\\"/>\\n                                    </div>\\n                                    <div class=\\"col-md-6\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Email</label>\\n                                        <input type=\\"email\\" class=\\"form-control form-control-lg\\" name=\\"email\\" placeholder=\\"example@gmail.com\\"/>\\n                                    </div>\\n                                    <div class=\\"col-md-6\\">\\n                                        <label class=\\"form-label fw-bold text-secondary\\">Số CCCD / Hộ Chiếu</label>\\n                                        <input type=\\"text\\" class=\\"form-control form-control-lg\\" name=\\"id_number\\" placeholder=\\"07920100xxxx\\"/>\\n                                    </div>\\n                                </div>\\n\\n                                <!-- Section 3: Yêu cầu đặc biệt -->\\n                                <h2 class=\\"h5 fw-bold text-dark mb-3 pb-2 border-bottom\\">\\n                                    <i class=\\"fa fa-pencil-square-o text-success me-2\\"/> 3. Yêu Cầu Đặc Biệt\\n                                </h2>\\n                                <div class=\\"mb-4\\">\\n                                    <textarea class=\\"form-control\\" name=\\"note\\" rows=\\"3\\" placeholder=\\"Ví dụ: Cần phòng tầng cao, giường đôi, nhận phòng sớm, chuẩn bị thêm nôi em bé...\\"/>\\n                                </div>\\n\\n                                <!-- Cam kết và Nút gửi -->\\n                                <div class=\\"alert alert-light border p-3 rounded-3 mb-4\\">\\n                                    <div class=\\"d-flex align-items-center\\">\\n                                        <i class=\\"fa fa-shield fa-2x text-warning me-3\\"/>\\n                                        <small class=\\"text-muted\\">\\n                                            Sau khi nhấn xác nhận, phiếu đặt phòng sẽ được tự động kích hoạt trạng thái <strong>Đã Xác Nhận (Confirmed)</strong> trên phần mềm Odoo của Lễ tân. Quý khách thanh toán tại quầy khi nhận phòng.\\n                                        </small>\\n                                    </div>\\n                                </div>\\n\\n                                <button id=\\"btn_submit_hotel_booking\\" type=\\"submit\\" class=\\"btn btn-warning btn-lg w-100 py-3 fw-bold text-dark fs-5 rounded-3 shadow-sm\\">\\n                                    <i class=\\"fa fa-check-circle me-2\\"/> XÁC NHẬN ĐẶT PHÒNG NGAY\\n                                </button>\\n                            </form>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>"}	<t name="