\"text-secondary fw-semibold\\">\\n                                    <span class=\\"badge bg-primary px-3 py-1 me-2\\"><t t-esc=\\"booking.room_id.floor or 'Tầng 1'\\"/></span>\\n                                    <span><t t-esc=\\"booking.room_type_id.name\\"/></span> • \\n                                    <strong class=\\"text-dark\\"><t t-esc=\\"booking.company_id.name\\"/></strong>\\n                                </div>\\n                            </div>\\n\\n                            <!-- Booking Receipt Card -->\\n                            <div class=\\"card bg-light border text-start p-4 rounded-3 mb-4\\">\\n                                <div class=\\"d-flex justify-content-between align-items-center border-bottom pb-3 mb-3\\">\\n                                    <div>\\n                                        <span class=\\"text-muted small d-block\\">Mã Đặt Phòng ERP:</span>\\n                                        <span class=\\"h4 fw-bold text-primary mb-0\\" t-esc=\\"booking.name\\"/>\\n                                    </div>\\n                                    <span class=\\"badge bg-warning text-dark px-3 py-2 rounded-pill fs-6 fw-bold\\">\\n                                        Trạng thái: Đã Giữ Phòng - Chờ Thanh Toán\\n                                    </span>\\n                                </div>\\n\\n                                <div class=\\"row g-3\\">\\n                                    <div class=\\"col-sm-6\\">\\n                                        <span class=\\"text-muted small d-block\\">Khách hàng:</span>\\n                                        <strong class=\\"text-dark fs-6\\" t-esc=\\"booking.partner_id.name\\"/>\\n                                    </div>\\n                                    <div class=\\"col-sm-6\\">\\n                                        <span class=\\"text-muted small d-block\\">Số điện thoại:</span>\\n                                        <strong class=\\"text-dark fs-6\\" t-esc=\\"booking.partner_id.phone or 'Chưa cập nhật'\\"/>\\n                                    </div>\\n                                    <div class=\\"col-sm-6\\">\\n                                        <span class=\\"text-muted small d-block\\">Chi nhánh khách sạn:</span>\\n                                        <strong class=\\"text-dark fs-6\\" t-esc=\\"booking.company_id.name\\"/>\\n                                    </div>\\n                                    <div class=\\"col-sm-6\\">\\n                                        <span class=\\"text-muted small d-block\\">Phòng &amp; Hạng phòng:</span>\\n                                        <strong class=\\"text-dark fs-6\\" t-esc=\\"'%s (%s)' % (booking.room_id.name, booking.room_type_id.name)\\"/>\\n                                    </div>\\n                                    <div class=\\"col-sm-6\\">\\n                                        <span class=\\"text-muted small d-block\\">Thời gian nhận phòng:</span>\\n                                        <strong class=\\"text-success fs-6\\" t-esc=\\"booking.check_in.strftime('%d/%m/%Y %H:%M') if booking.check_in else ''\\"/>\\n                                    </div>\\n                                    <div class=\\"col-sm-6\\">\\n                                        <span class=\\"text-muted small d-block\\">Thời gian trả phòng:</span>\\n                                        <strong class=\\"text-danger fs-6\\" t-esc=\\"booking.check_out.strftime('%d/%m/%Y %H:%M') if booking.check_out else ''\\"/>\\n                                    </div>\\n                                    <div class=\\"col-12 pt-3 border-top d-flex justify-content-between align-items-baseline\\">\\n                                        <span class=\\"h6 mb-0 text-dark\\">Tổng tiền phòng thanh toán:</span>\\n                                        <span class=\\"h4 fw-bold text-danger mb-0\\">\\n                                            <t t-esc=\\"'{:,.0f}'.format(booking.room_price)\\"/> đ\\n                                        </span>\\n                                    </div>\\n                                </div>\\n                            </div>\\n\\n                            <!-- VietQR Techcombank Payment Card -->\\n                            <div class=\\"card border-danger border-2 text-start p-4 rounded-3 mb-4 shadow-sm\\" style=\\"background: #fffdfd;\\">\\n                                <div class=\\"d-flex align-items-center gap-2 border-bottom pb-3 mb-3\\">\\n                                    <div class=\\"bg-danger text-white rounded-circle p-2 d-flex align-items-center justify-content-center\\" style=\\"width: 40px; height: 40px;\\">\\n                                        <i class=\\"fa fa-qrcode fa-lg\\"/>\\n                                    </div>\\n                                    <div>\\n                                        <h5 class=\\"fw-bold text-danger mb-0\\">QUÉT MÃ QR THANH TOÁN CHUYỂN KHOẢN (TECHCOMBANK)</h5>\\n                                        <small class=\\"text-muted\\">Quét bằng ứng dụng Ngân hàng (Techcombank, Vietcombank, MB, Momo...)</small>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"row align-items-center g-4\\">\\n                                    <!-- QR Code Column -->\\n                                    <div class=\\"col-md-5 text-center\\">\\n                                        <t t-if=\\"vietqr_url\\">\\n                                            <img t-att-src=\\"vietqr_url\\" class=\\"img-fluid rounded border shadow-sm p-2 bg-white\\" style=\\"max-width: 240px;\\" alt=\\"Mã VietQR Techcombank\\"/>\\n                                            <div class=\\"small text-muted mt-2\\">\\n                                                <i class=\\"fa fa-camera me-1\\"/> Mở App Ngân hàng quét mã này\\n                                            </div>\\n                                        </t>\\n                                    </div>\\n\\n                                    <!-- Bank Transfer Details Column -->\\n                                    <div class=\\"col-md-7\\">\\n                                        <table class=\\"table table-sm table-borderless mb-0\\">\\n                                            <tbody>\\n                                                <tr>\\n                                                    <td class=\\"text-muted\\" style=\\"width: 140px;\\">Ngân hàng:</td>\\n                                                    <td><strong class=\\"text-dark\\">Techcombank (TCB)</strong></td>\\n                                                </tr>\\n                                                <tr>\\n                                                    <td class=\\"text-muted\\">Số tài khoản:</td>\\n                                                    <td>\\n                                                        <strong class=\\"fs-5 text-danger\\" t-esc=\\"bank_account_no or '2101200646'\\"/>\\n                                                        <span class=\\"badge bg-light text-secondary border ms-2\\">Chính thức</span>\\n                                                    </td>\\n                                                </tr>\\n                                                <tr>\\n                                                    <td class=\\"text-muted\\">Chủ tài khoản:</td>\\n                                                    <td><strong class=\\"text-dark\\" t-esc=\\"bank_account_name or 'BUI MINH TRIET'\\"/></td>\\n                                                </tr>\\n                                                <tr>\\n                                                    <td class=\\"text-muted\\">Số tiền chuyển:</td>\\n                                                    <td>\\n                                                        <strong class=\\"fs-5 text-danger\\">\\n                                                            <t t-esc=\\"'{:,.0f}'.format(transfer_amount or booking.room_price)\\"/> đ\\n                                                        </strong>\\n                                                    </td>\\n                                                </tr>\\n                                                <tr>\\n                                                    <td class=\\"text-muted\\">Nội dung CK:</td>\\n                                                    <td>\\n                                                        <code class=\\"fs-6 fw-bold text-primary bg-light px-2 py-1 rounded\\" t-esc=\\"transfer_memo or ('MHOTEL ' + booking.name.replace('/', ''))\\"/>\\n                                                    </td>\\n                                                </tr>\\n                                            </tbody>\\n                                        </table>\\n                                        <div class=\\"alert alert-light border small text-muted mt-3 mb-0\\">\\n                                            <i class=\\"fa fa-check-circle text-success me-1\\"/> Hệ thống tự động ghi nhận giữ phòng ngay sau khi nhận được chuyển khoản hợp lệ.\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n\\n                            <div class=\\"alert alert-info text-start small mb-4\\">\\n                                <i class=\\"fa fa-info-circle me-1\\"/> <strong>Lưu ý nhận phòng:</strong> Quý khách vui lòng cung cấp mã đặt phòng <code><t t-esc=\\"booking.name\\"/></code> hoặc số điện thoại khi đến quầy Lễ tân để làm thủ tục nhận chìa khóa phòng nhanh chóng.\\n                            </div>\\n\\n                            <div class=\\"d-flex justify-content-center gap-3\\">\\n                                <a href=\\"/hotel\\" class=\\"btn btn-outline-dark btn-lg px-4 rounded-pill fw-bold\\">\\n                                    <i class=\\"fa fa-home me-1\\"/> Trang Chủ M-Hotel\\n                                </a>\\n                                <a href=\\"/odoo\\" class=\\"btn btn-primary btn-lg px-4 rounded-pill fw-bold\\">\\n                                    <i class=\\"fa fa-tachometer me-1\\"/> Xem Trên Quản Trị ERP\\n                                </a>\\n                            </div>\\n                        </div>\\n\\n                    </div>\\n                </div>\\n            </t>\\n        </t>"}	<t name="M-Hotel Booking Confirmation" t-name="m_hotel_website.hotel_booking_confirmation">\n            <t t-call="website.layout">\n                <div id="wrap" class="py-5 bg-light">\n                    <div class="container" style="max-width: 800px;">\n                        \n                        <div class="card border-0 shadow-sm rounded-4 overflow-hidden text-center p-5 bg-white">\n                            <div class="mb-4">\n                                <span class="d-inline-flex align-items-center justify-content-center bg-success text-white rounded-circle shadow" style="width: 80px; height: 80px; font-size: 40px;">\n                                    ✓\n                                </span>\n                            </div>\n                            \n                            <h1 class="display-6 fw-bold text-dark mb-2">ĐẶT PHÒNG THÀNH CÔNG!</h1>\n                            <p class="text-muted mb-4 lead">\n                                Cảm ơn quý khách đã tin tưởng và lựa chọn <strong>M-Hotel Hospitality</strong>.\n                            </p>\n\n                            <!-- Booking Receipt Card -->\n                            <div class="card bg-light border text-start p-4 rounded-3 mb-4">\n                                <div class="d-flex justify-content-between align-items-center border-bottom pb-3 mb-3">\n                                    <div>\n                                        <span class="text-muted small d-block">Mã Đặt Phòng ERP:</span>\n                                        <span class="h4 fw-bold text-primary mb-0" t-esc="booking.name"/>\n                                    </div>\n                                    <span class="badge bg-warning text-dark px-3 py-2 rounded-pill fs-6 fw-bold">\n                                        Trạng thái: Đã Giữ Phòng - Chờ Thanh Toán\n                                    </span>\n                                </div>\n\n                                <div class="row g-3">\n                                    <div class="col-sm-6">\n                                        <span class="text-muted small d-block">Khách hàng:</span>\n                                        <strong class="text-dark fs-6" t-esc="booking.partner_id.name"/>\n                                    </div>\n                                    <div class="col-sm-6">\n                                        <span class="text-muted small d-block">Số điện thoại:</span>\n                                        <strong class="text-dark fs-6" t-esc="booking.partner_id.phone or 'Chưa cập nhật'"/>\n                                    </div>\n                                    <div class="col-sm-6">\n                                        <span class="text-muted small d-block">Chi nhánh khách sạn:</span>\n                                        <strong class="text-dark fs-6" t-esc="booking.company_id.name"/>\n                                    </div>\n                                    <div class="col-sm-6">\n                                        <span class="text-muted small d-block">Phòng &amp; Hạng phòng:</span>\n                                        <strong class="text-dark fs-6" t-esc="'%s (%s)' % (booking.room_id.name, booking.room_type_id.name)"/>\n                                    </div>\n                                    <div class="col-sm-6">\n                                        <span class="text-muted small d-block">Thời gian nhận phòng:</span>\n                                        <strong class="text-success fs-6" t-esc="booking.check_in.strftime('%d/%m/%Y %H:%M') if booking.check_in else ''"/>\n                                    </div>\n                                    <div class="col-sm-6">\n                                        <span class="text-muted small d-block">Thời gian trả phòng:</span>\n                                        <strong class="text-danger fs-6" t-esc="booking.check_out.strftime('%d/%m/%Y %H:%M') if booking.check_out else ''"/>\n                                    </div>\n                                    <div class="col-12 pt-3 border-top d-flex justify-content-between align-items-baseline">\n                                        <span class="h6 mb-0 text-dark">Tổng tiền phòng thanh toán:</span>\n                                        <span class="h4 fw-bold text-danger mb-0">\n                                            <t t-esc="'{:,.0f}'.format(booking.room_price)"/> đ\n                                        </span>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- VietQR Techcombank Payment Card -->\n                            <div class="card border-danger border-2 text-start p-4 rounded-3 mb-4 shadow-sm" style="background: #fffdfd;">\n                                <div class="d-flex align-items-center gap-2 border-bottom pb-3 mb-3">\n                                    <div class="bg-danger text-white rounded-circle p-2 d-flex align-items-center justify-content-center" style="width: 40px; height: 40px;">\n                                        <i class="fa fa-qrcode fa-lg"/>\n                                    </div>\n                                    <div>\n                                        <h5 class="fw-bold text-danger mb-0">QUÉT MÃ QR THANH TOÁN CHUYỂN KHOẢN (TECHCOMBANK)</h5>\n                                        <small class="text-muted">Quét bằng ứng dụng Ngân hàng (Techcombank, Vietcombank, MB, Momo...)</small>\n                                    </div>\n                                </div>\n\n                                <div class="row align-items-center g-4">\n                                    <!-- QR Code Column -->\n                                    <div class="col-md-5 text-center">\n                                        <t t-if="vietqr_url">\n                                            <img t-att-src="vietqr_url" class="img-fluid rounded border shadow-sm p-2 bg-white" style="max-width: 240px;" alt="Mã VietQR Techcombank"/>\n                                            <div class="small text-muted mt-2">\n                                                <i class="fa fa-camera me-1"/> Mở App Ngân hàng quét mã này\n                                            </div>\n                                        </t>\n                                    </div>\n\n                                    <!-- Bank Transfer Details Column -->\n                                    <div class="col-md-7">\n                                        <table class="table table-sm table-borderless mb-0">\n                                            <tbody>\n                                                <tr>\n                                                    <td class="text-muted" style="width: 140px;">Ngân hàng:</td>\n                                                    <td><strong class="text-dark">Techcombank (TCB)</strong></td>\n                                                </tr>\n                                                <tr>\n                                                    <td class="text-muted">Số tài khoản:</td>\n                                                    <td>\n                                                        <strong class="fs-5 text-danger" t-esc="bank_account_no or '2101200646'"/>\n                                                        <span class="badge bg-light text-secondary border ms-2">Chính thức</span>\n                                                    </td>\n                                                </tr>\n                                                <tr>\n                                                    <td class="text-muted">Chủ tài khoản:</td>\n                                                    <td><strong class="text-dark" t-esc="bank_account_name or 'BUI MINH TRIET'"/></td>\n                                                </tr>\n                                                <tr>\n                                                    <td class="text-muted">Số tiền chuyển:</td>\n                                                    <td>\n                                                        <strong class="fs-5 text-danger">\n                                                            <t t-esc="'{:,.0f}'.format(transfer_amount or booking.room_price)"/> đ\n                                                        </strong>\n                                                    </td>\n                                                </tr>\n                                                <tr>\n                                                    <td class="text-muted">Nội dung CK:</td>\n                                                    <td>\n                                                        <code class="fs-6 fw-bold text-primary bg-light px-2 py-1 rounded" t-esc="transfer_memo or ('MHOTEL ' + booking.name.replace('/', ''))"/>\n                                                    </td>\n                                                </tr>\n                                            </tbody>\n                                        </table>\n                                        <div class="alert alert-light border small text-muted mt-3 mb-0">\n                                            <i class="fa fa-check-circle text-success me-1"/> Hệ thống tự động ghi nhận giữ phòng ngay sau khi nhận được chuyển khoản hợp lệ.\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class="alert alert-info text-start small mb-4">\n                                <i class="fa fa-info-circle me-1"/> <strong>Lưu ý nhận phòng:</strong> Quý khách vui lòng cung cấp mã đặt phòng <code><t t-esc="booking.name"/></code> hoặc số điện thoại khi đến quầy Lễ tân để làm thủ tục nhận chìa khóa phòng nhanh chóng.\n                            </div>\n\n                            <div class="d-flex justify-content-center gap-3">\n                                <a href="/hotel" class="btn btn-outline-dark btn-lg px-4 rounded-pill fw-bold">\n                                    <i class="fa fa-home me-1"/> Trang Chủ M-Hotel\n                                </a>\n                                <a href="/odoo" class="btn btn-primary btn-lg px-4 rounded-pill fw-bold">\n                                    <i class="fa fa-tachometer me-1"/> Xem Trên Quản Trị ERP\n                                </a>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n            </t>\n        </t>	f	t	2026-10-13 14:47:20.18786	2026-10-30 15:25:53.546262	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
18	16	\N	1	1	Server Action	ir.actions.server	\N	form	base/views/ir_actions_views.xml	primary	{"en_US": "<form string=\\"Server Action\\">\\n                    <header invisible=\\"context.get('is_modal')\\">\\n                        <button name=\\"create_action\\" string=\\"Create Contextual Action\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"binding_model_id\\" help=\\"Display an option in the 'More' top-menu in order to run this action.\\"/>\\n                        <button name=\\"unlink_action\\" string=\\"Remove Contextual Action\\" type=\\"object\\" invisible=\\"not binding_model_id\\" help=\\"Remove 'More' top-menu contextual action related to this action\\"/>\\n                        <button name=\\"run\\" string=\\"Run\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"model_name != 'ir.actions.server' or state != 'code'\\" help=\\"Run this action manually.\\"/>\\n                        <button name=\\"history_wizard_action\\" string=\\"Code History\\" type=\\"object\\" invisible=\\"not show_code_history\\" help=\\"View code history and restore a previous version\\"/>\\n                    </header>\\n                    <sheet>\\n                        <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                            <button type=\\"object\\" name=\\"action_open_parent_action\\" invisible=\\"not parent_id\\" class=\\"oe_stat_button\\" icon=\\"fa-database\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Parent Action</span>\\n                                </div>\\n                            </button>\\n                            <button type=\\"object\\" name=\\"action_open_scheduled_action\\" invisible=\\"not ir_cron_ids or context.key != 'server_action'\\" context=\\"{'key': 'ir_cron'}\\" class=\\"oe_stat_button\\" icon=\\"fa-refresh\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Scheduled Action</span>\\n                                </div>\\n                            </button>\\n                        </div>\\n                        <h1 class=\\"oe_title\\">\\n                            <field name=\\"automated_name\\" invisible=\\"1\\"/> <!-- needed for name compute -->\\n                            <field name=\\"name\\" placeholder=\\"Set an explicit name\\"/>\\n                        </h1>\\n                        <group invisible=\\"context.get('is_modal')\\">\\n                            <group>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" groups=\\"base.group_no_one\\"/>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" groups=\\"!base.group_no_one\\" invisible=\\"context.get('default_model_id')\\" domain=\\"[('id', 'in', available_model_ids)]\\"/>\\n                            </group>\\n                            <group groups=\\"base.group_no_one\\">\\n                                <field name=\\"group_ids\\" widget=\\"many2many_tags\\"/>\\n                            </group>\\n                        </group>\\n                        <t name=\\"action_content\\" invisible=\\"not model_id\\">\\n                            <field name=\\"allowed_states\\" invisible=\\"1\\"/> <!-- Used to filter state using selection_badge_with_filter -->\\n                            <div class=\\"d-flex flex-column\\">\\n                                <label for=\\"state\\"/>\\n                                <field name=\\"state\\" widget=\\"selection_badge_with_filter\\" options=\\"{'size': 'sm', 'allowed_selection_field': 'allowed_states'}\\"/>\\n                            </div>\\n                            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not warning\\">\\n                                <i class=\\"fa fa-warning pe-2\\" title=\\"Warning\\"/><field class=\\"d-inline\\" name=\\"warning\\" nolabel=\\"1\\"/>\\n                            </div>\\n                            <div class=\\"d-flex flex-row flex-wrap gap-2\\" invisible=\\"state != 'object_write'\\">\\n                                <field name=\\"evaluation_type\\" class=\\"oe_inline\\"/>\\n                                <field name=\\"update_path\\" widget=\\"field_selector\\" class=\\"oe_inline\\" options=\\"{'model': 'model_name', 'allow_properties': False}\\" required=\\"state == 'object_write'\\"/>\\n                                <field name=\\"update_field_id\\" invisible=\\"True\\"/>  <!-- The field is store=True and readonly=False, in this view we want to save the value from compute/onchange -->\\n                                <field name=\\"update_related_model_id\\" invisible=\\"True\\"/> <!-- This field is required for 'resource_ref' to compute possible m2m and m2o values -->\\n                                <span invisible=\\"evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']\\">by</span>\\n                                <field name=\\"update_m2m_operation\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']\\" required=\\"update_field_type in ['one2many', 'many2many']\\"/>\\n                                <span invisible=\\"evaluation_type != 'value' or update_field_type in ['one2many', 'many2many']\\">to</span>\\n                                <span invisible=\\"evaluation_type != 'sequence'\\">with</span>\\n                                <field name=\\"value\\" class=\\"oe_inline\\" placeholder=\\"Set a value...\\" invisible=\\"update_field_id == False or value_field_to_show != 'value' or evaluation_type != 'value'\\" string=\\"Custom Value\\"/>\\n                                <field name=\\"html_value\\" class=\\"w-100\\" placeholder=\\"Set a value...\\" invisible=\\"update_field_id == False or value_field_to_show != 'html_value' or evaluation_type != 'value'\\" string=\\"Custom Value\\"/>\\n                                <field name=\\"sequence_id\\" class=\\"oe_inline\\" placeholder=\\"Select a sequence...\\" invisible=\\"evaluation_type != 'sequence'\\" required=\\"evaluation_type == 'sequence'\\"/>\\n                                <field name=\\"resource_ref\\" class=\\"oe_inline\\" placeholder=\\"Choose a value...\\" string=\\"Custom Value\\" options=\\"{'model_field': 'update_related_model_id', 'no_create': True, 'no_open': True}\\" invisible=\\"update_field_id == False or value_field_to_show != 'resource_ref' or evaluation_type == 'equation' or update_m2m_operation == 'clear'\\"/>\\n                                <field name=\\"selection_value\\" class=\\"oe_inline\\" placeholder=\\"Choose a value...\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"update_field_id == False or value_field_to_show != 'selection_value' or evaluation_type == 'equation'\\"/>\\n                                <field name=\\"update_boolean_value\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or value_field_to_show != 'update_boolean_value'\\" required=\\"value_field_to_show == 'update_boolean_value'\\"/>\\n                                <span invisible=\\"update_field_id != False or evaluation_type != 'value'\\" class=\\"o_actions_server_set_a_value text-muted\\">Set a value...</span>\\n                                <span invisible=\\"evaluation_type != 'equation'\\">\\n                                    to this Python expression:\\n                                </span>\\n                                <div class=\\"w-100 d-flex flex-row gap-3\\" invisible=\\"evaluation_type != 'equation'\\">\\n                                    <field name=\\"value\\" class=\\"w-50\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" string=\\"Expression\\"/>\\n                                    <div class=\\"w-50 opacity-75\\">\\n                                        <span colspan=\\"2\\" class=\\"text-muted\\"> Available variables: </span>\\n                                            <ul colspan=\\"2\\" class=\\"text-muted\\">\\n                                                <li><code>env</code>: environment on which the action is triggered</li>\\n                                                <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\\n                                                <li><code>record</code>: record on which the action is triggered</li>\\n                                                <li><code>records</code>: recordset of all records on which the action is triggered in multi mode</li>\\n                                                <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\\n                                                <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\\n                                            </ul>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <group invisible=\\"state not in ['object_create', 'object_copy']\\">\\n                                <group>\\n                                    <field name=\\"crud_model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" required=\\"state in ['object_create', 'object_copy']\\"/>\\n                                    <field name=\\"value\\" widget=\\"char\\" string=\\"Name\\" invisible=\\"state != 'object_create'\\" help=\\"The name of the record to create\\" placeholder=\\"e.g. Follow-up\\"/>\\n                                    <field name=\\"resource_ref\\" placeholder=\\"Choose a record...\\" string=\\"Duplicate from\\" options=\\"{'model_field': 'crud_model_id', 'no_create': True, 'no_open': True}\\" invisible=\\"crud_model_id == False or state != 'object_copy'\\" required=\\"state == 'object_copy'\\"/>\\n                                    <field name=\\"link_field_id\\" domain=\\"[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                         ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]\\" placeholder=\\"Select a field to link the record to\\" options=\\"{'no_create': True, 'no_open': True}\\" context=\\"{'default_model_id': model_id, 'default_relation': crud_model_name}\\"/>\\n                                </group>\\n                            </group>\\n                            <group invisible=\\"state != 'webhook'\\">\\n                                <group>\\n                                    <field name=\\"webhook_url\\" string=\\"URL\\" placeholder=\\"e.g. https://maker.ifttt.com/use/...\\"/>\\n                                    <field name=\\"webhook_field_ids\\" string=\\"Fields\\" widget=\\"many2many_tags\\" context=\\"{'hide_model': 1}\\" domain=\\"[('model_id', '=', model_id)]\\" placeholder=\\"Select fields to include in the request...\\"/>\\n                                </group>\\n                                <group>\\n                                    <label for=\\"webhook_sample_payload\\"/>\\n                                    <field name=\\"webhook_sample_payload\\" string=\\"Sample Payload\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"1\\" widget=\\"code\\" options=\\"{'mode': 'javascript'}\\"/>\\n                                </group>\\n                            </group>\\n                            <t invisible=\\"state != 'multi'\\">\\n                                <field name=\\"child_ids\\" widget=\\"many2many\\" mode=\\"kanban\\" context=\\"{                                     'is_modal': 1,                                     'default_model_id': model_id,                                 }\\"/>\\n                            </t>\\n                            <notebook>\\n                                <page string=\\"Code\\" invisible=\\"state != 'code'\\">\\n                                    <field name=\\"code\\" invisible=\\"state != 'code'\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" placeholder=\\"Enter Python code here. Help about Python expression is available in the help tab of this document.\\"/>\\n                                </page>\\n                                <page string=\\"Help\\" invisible=\\"state != 'code'\\" name=\\"ir_actions_server_code_help\\">\\n                                    <p>The following variables can be used:</p>\\n                                    <ul>\\n                                        <li><code>env</code>: environment on which the action is triggered</li>\\n                                        <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\\n                                        <li><code>record</code>: record on which the action is triggered; may be be void</li>\\n                                        <li><code>records</code>: recordset of all records on which the action is triggered in multi mode; may be void</li>\\n                                        <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\\n                                        <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\\n                                        <li><code>log(message, level='info')</code>: logging function to record debug information in <code>ir.logging</code> table</li>\\n                                        <li><code>_logger.info(message)</code>: logger to emit messages in server logs</li>\\n                                        <li><code>UserError</code>: exception class for raising user-facing warning messages</li>\\n                                        <li><code>Command</code>: x2many commands namespace</li>\\n                                        <li>To return an action, assign: <code>action = {...}</code></li>\\n                                        <li>To notify progress for CRON call and re-trigger a call if there is remaining tasks, use <code>env['ir.cron']._notify_progress(done=task_done_count, remaining=task_remaining_count)</code></li>\\n                                    </ul>\\n                                    <p>\\n                                        <widget name=\\"documentation_link\\" path=\\"/developer/reference/backend/orm.html\\" label=\\"ORM API Documentation\\" icon=\\"oi oi-fw oi-arrow-right me-1\\"/>\\n                                    </p>\\n                                    <div>\\n                                        <p>Example of Python code:</p>\\n                                        <pre style=\\"white-space: pre-wrap\\">partner_name = record.name + '_code'\\nenv['res.partner'].create({'name': partner_name})\\n    </pre>\\n                                    </div>\\n                                </page>\\n                                <page string=\\"Usage\\" name=\\"usage\\" invisible=\\"1\\"/>\\n                            </notebook>\\n                        </t>\\n                    </sheet>\\n                </form>", "vi_VN": "<form string=\\"Tác vụ phía máy chủ\\">\\n                    <header invisible=\\"context.get('is_modal')\\">\\n                        <button name=\\"create_action\\" string=\\"Tạo Tác vụ theo Ngữ cảnh\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"binding_model_id\\" help=\\"Hiển thị phần tùy chọn trong menu 'Thêm' ở phía trên để có thể thực hiện tác vụ này.\\"/>\\n                        <button name=\\"unlink_action\\" string=\\"Bỏ bối cảnh tác vụ\\" type=\\"object\\" invisible=\\"not binding_model_id\\" help=\\"Bỏ menu 'Thêm' trên cùng theo ngữ cảnh liên quan đến tác vụ này\\"/>\\n                        <button name=\\"run\\" string=\\"Chạy\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"model_name != 'ir.actions.server' or state != 'code'\\" help=\\"Thực thi tác vụ này một cách thủ công.\\"/>\\n                        <button name=\\"history_wizard_action\\" string=\\"Code History\\" type=\\"object\\" invisible=\\"not show_code_history\\" help=\\"Xem lịch sử mã nguồn và khôi phục phiên bản trước đó\\"/>\\n                    </header>\\n                    <sheet>\\n                        <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                            <button type=\\"object\\" name=\\"action_open_parent_action\\" invisible=\\"not parent_id\\" class=\\"oe_stat_button\\" icon=\\"fa-database\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Tác vụ chính</span>\\n                                </div>\\n                            </button>\\n                            <button type=\\"object\\" name=\\"action_open_scheduled_action\\" invisible=\\"not ir_cron_ids or context.key != 'server_action'\\" context=\\"{'key': 'ir_cron'}\\" class=\\"oe_stat_button\\" icon=\\"fa-refresh\\">\\n                                <div class=\\"o_stat_info\\">\\n                                    <span class=\\"o_stat_text\\">Tác vụ đã lên lịch</span>\\n                                </div>\\n                            </button>\\n                        </div>\\n                        <h1 class=\\"oe_title\\">\\n                            <field name=\\"automated_name\\" invisible=\\"1\\"/> <!-- needed for name compute -->\\n                            <field name=\\"name\\" placeholder=\\"Đặt tên rõ ràng\\"/>\\n                        </h1>\\n                        <group invisible=\\"context.get('is_modal')\\">\\n                            <group>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" groups=\\"base.group_no_one\\"/>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" groups=\\"!base.group_no_one\\" invisible=\\"context.get('default_model_id')\\" domain=\\"[('id', 'in', available_model_ids)]\\"/>\\n                            </group>\\n                            <group groups=\\"base.group_no_one\\">\\n                                <field name=\\"group_ids\\" widget=\\"many2many_tags\\"/>\\n                            </group>\\n                        </group>\\n                        <t name=\\"action_content\\" invisible=\\"not model_id\\">\\n                            <field name=\\"allowed_states\\" invisible=\\"1\\"/> <!-- Used to filter state using selection_badge_with_filter -->\\n                            <div class=\\"d-flex flex-column\\">\\n                                <label for=\\"state\\"/>\\n                                <field name=\\"state\\" widget=\\"selection_badge_with_filter\\" options=\\"{'size': 'sm', 'allowed_selection_field': 'allowed_states'}\\"/>\\n                            </div>\\n                            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not warning\\">\\n                                <i class=\\"fa fa-warning pe-2\\" title=\\"Cảnh báo\\"/><field class=\\"d-inline\\" name=\\"warning\\" nolabel=\\"1\\"/>\\n                            </div>\\n                            <div class=\\"d-flex flex-row flex-wrap gap-2\\" invisible=\\"state != 'object_write'\\">\\n                                <field name=\\"evaluation_type\\" class=\\"oe_inline\\"/>\\n                                <field name=\\"update_path\\" widget=\\"field_selector\\" class=\\"oe_inline\\" options=\\"{'model': 'model_name', 'allow_properties': False}\\" required=\\"state == 'object_write'\\"/>\\n                                <field name=\\"update_field_id\\" invisible=\\"True\\"/>  <!-- The field is store=True and readonly=False, in this view we want to save the value from compute/onchange -->\\n                                <field name=\\"update_related_model_id\\" invisible=\\"True\\"/> <!-- This field is required for 'resource_ref' to compute possible m2m and m2o values -->\\n                                <span invisible=\\"evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']\\">bởi</span>\\n                                <field name=\\"update_m2m_operation\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']\\" required=\\"update_field_type in ['one2many', 'many2many']\\"/>\\n                                <span invisible=\\"evaluation_type != 'value' or update_field_type in ['one2many', 'many2many']\\">đến</span>\\n                                <span invisible=\\"evaluation_type != 'sequence'\\">với</span>\\n                                <field name=\\"value\\" class=\\"oe_inline\\" placeholder=\\"Thiết lập một giá trị...\\" invisible=\\"update_field_id == False or value_field_to_show != 'value' or evaluation_type != 'value'\\" string=\\"Giá trị tùy chỉnh\\"/>\\n                                <field name=\\"html_value\\" class=\\"w-100\\" placeholder=\\"Thiết lập một giá trị...\\" invisible=\\"update_field_id == False or value_field_to_show != 'html_value' or evaluation_type != 'value'\\" string=\\"Giá trị tùy chỉnh\\"/>\\n                                <field name=\\"sequence_id\\" class=\\"oe_inline\\" placeholder=\\"Chọn một trình tự...\\" invisible=\\"evaluation_type != 'sequence'\\" required=\\"evaluation_type == 'sequence'\\"/>\\n                                <field name=\\"resource_ref\\" class=\\"oe_inline\\" placeholder=\\"Chọn một giá trị...\\" string=\\"Giá trị tùy chỉnh\\" options=\\"{'model_field': 'update_related_model_id', 'no_create': True, 'no_open': True}\\" invisible=\\"update_field_id == False or value_field_to_show != 'resource_ref' or evaluation_type == 'equation' or update_m2m_operation == 'clear'\\"/>\\n                                <field name=\\"selection_value\\" class=\\"oe_inline\\" placeholder=\\"Chọn một giá trị...\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"update_field_id == False or value_field_to_show != 'selection_value' or evaluation_type == 'equation'\\"/>\\n                                <field name=\\"update_boolean_value\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or value_field_to_show != 'update_boolean_value'\\" required=\\"value_field_to_show == 'update_boolean_value'\\"/>\\n                                <span invisible=\\"update_field_id != False or evaluation_type != 'value'\\" class=\\"o_actions_server_set_a_value text-muted\\">Đặt một giá trị...</span>\\n                                <span invisible=\\"evaluation_type != 'equation'\\">\\n                                    cho biểu thức Python này:\\n                                </span>\\n                                <div class=\\"w-100 d-flex flex-row gap-3\\" invisible=\\"evaluation_type != 'equation'\\">\\n                                    <field name=\\"value\\" class=\\"w-50\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" string=\\"Expression\\"/>\\n                                    <div class=\\"w-50 opacity-75\\">\\n                                        <span colspan=\\"2\\" class=\\"text-muted\\"> Biến có sẵn: </span>\\n                                            <ul colspan=\\"2\\" class=\\"text-muted\\">\\n                                                <li><code>env</code>: môi trường mà tác vụ được kích hoạt</li>\\n                                                <li><code>model</code>: mô hình của bản ghi mà tác vụ được kích hoạt; là một tập bản ghi không còn hiệu lực</li>\\n                                                <li><code>bản ghi</code>: bản ghi mà tác vụ được kích hoạt</li>\\n                                                <li><code>các bản ghi</code>: tập hợp tất cả các bản ghi mà tác vụ được kích hoạt ở chế độ \\"nhiều\\"</li>\\n                                                <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: các thư viện Python hữu ích</li>\\n                                                <li><code>float_compare()</code>: hàm tiện ích để so sánh các số thực dựa trên độ chính xác cụ thể</li>\\n                                            </ul>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <group invisible=\\"state not in ['object_create', 'object_copy']\\">\\n                                <group>\\n                                    <field name=\\"crud_model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" required=\\"state in ['object_create', 'object_copy']\\"/>\\n                                    <field name=\\"value\\" widget=\\"char\\" string=\\"Tên\\" invisible=\\"state != 'object_create'\\" help=\\"Tên của bản ghi cần tạo\\" placeholder=\\"VD: Follow-up\\"/>\\n                                    <field name=\\"resource_ref\\" placeholder=\\"Chọn một bản ghi...\\" string=\\"Sao chép từ\\" options=\\"{'model_field': 'crud_model_id', 'no_create': True, 'no_open': True}\\" invisible=\\"crud_model_id == False or state != 'object_copy'\\" required=\\"state == 'object_copy'\\"/>\\n                                    <field name=\\"link_field_id\\" domain=\\"[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                         ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]\\" placeholder=\\"Chọn một trường để liên kết với bản ghi\\" options=\\"{'no_create': True, 'no_open': True}\\" context=\\"{'default_model_id': model_id, 'default_relation': crud_model_name}\\"/>\\n                                </group>\\n                            </group>\\n                            <group invisible=\\"state != 'webhook'\\">\\n                                <group>\\n                                    <field name=\\"webhook_url\\" string=\\"URL\\" placeholder=\\"VD: https://maker.ifttt.com/use/...\\"/>\\n                                    <field name=\\"webhook_field_ids\\" string=\\"Trường\\" widget=\\"many2many_tags\\" context=\\"{'hide_model': 1}\\" domain=\\"[('model_id', '=', model_id)]\\" placeholder=\\"Chọn trường để thêm vào yêu cầu...\\"/>\\n                                </group>\\n                                <group>\\n                                    <label for=\\"webhook_sample_payload\\"/>\\n                                    <field name=\\"webhook_sample_payload\\" string=\\"Payload mẫu\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"1\\" widget=\\"code\\" options=\\"{'mode': 'javascript'}\\"/>\\n                                </group>\\n                            </group>\\n                            <t invisible=\\"state != 'multi'\\">\\n                                <field name=\\"child_ids\\" widget=\\"many2many\\" mode=\\"kanban\\" context=\\"{                                     'is_modal': 1,                                     'default_model_id': model_id,                                 }\\"/>\\n                            </t>\\n                            <notebook>\\n                                <page string=\\"Mã\\" invisible=\\"state != 'code'\\">\\n                                    <field name=\\"code\\" invisible=\\"state != 'code'\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" placeholder=\\"Điền mã Python ở đây. Thông tin hỗ trợ về các biểu thức Python có trong phần hỗ trợ của tài liệu này.\\"/>\\n                                </page>\\n                                <page string=\\"Hỗ trợ\\" invisible=\\"state != 'code'\\" name=\\"ir_actions_server_code_help\\">\\n                                    <p>Các biến sau có thể được sử dụng:</p>\\n                                    <ul>\\n                                        <li><code>env</code>: môi trường mà tác vụ được kích hoạt</li>\\n                                        <li><code>model</code>: mô hình của bản ghi mà tác vụ được kích hoạt; là một tập bản ghi không còn hiệu lực</li>\\n                                        <li><code>bản ghi</code>: bản ghi mà tác vụ được kích hoạt, có thể không còn hiệu lực</li>\\n                                        <li><code>các bản ghi</code>: tập hợp tất cả các bản ghi mà tác vụ được kích hoạt ở chế độ \\"nhiều\\"; có thể không còn hiệu lực</li>\\n                                        <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: các thư viện Python hữu ích</li>\\n                                        <li><code>float_compare()</code>: hàm tiện ích để so sánh các số thực dựa trên độ chính xác cụ thể</li>\\n                                        <li><code>log(message, level='info')</code>: hàm ghi nhật ký để ghi lại thông tin gỡ lỗi trong bảng <code>ir.logging</code></li>\\n                                        <li><code>_logger.info(message)</code>: trình ghi nhật ký phát ra các thông báo trong nhật ký máy chủ</li>\\n                                        <li><code>UserError</code>: lớp ngoại lệ để đưa ra các thông báo cảnh báo dành cho người dùng</li>\\n                                        <li><code>Lệnh</code>: namespace lệnh x2many</li>\\n                                        <li>Để trả về một tác vụ, chỉ định: <code>action = {...}</code></li>\\n                                        <li>Để thông báo tiến độ cho lệnh gọi CRON và kích hoạt lại lệnh gọi nếu vẫn còn nhiệm vụ, sử dụng <code>env['ir.cron']._notify_progress(done=task_done_count, remaining=task_remaining_count)</code></li>\\n                                    </ul>\\n                                    <p>\\n                                        <widget name=\\"documentation_link\\" path=\\"/developer/reference/backend/orm.html\\" label=\\"Tài liệu tham khảo API ORM\\" icon=\\"oi oi-fw oi-arrow-right me-1\\"/>\\n                                    </p>\\n                                    <div>\\n                                        <p>Ví dụ về mã Python:</p>\\n                                        <pre style=\\"white-space: pre-wrap\\">partner_name = record.name + '_code'\\nenv['res.partner'].create({'name': partner_name})\\n    </pre>\\n                                    </div>\\n                                </page>\\n                                <page string=\\"Cách dùng\\" name=\\"usage\\" invisible=\\"1\\"/>\\n                            </notebook>\\n                        </t>\\n                    </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Server Action">\n                    <header invisible="context.get('is_modal')">\n                        <button name="create_action" string="Create Contextual Action" type="object" class="btn-primary" invisible="binding_model_id" help="Display an option in the 'More' top-menu in order to run this action."/>\n                        <button name="unlink_action" string="Remove Contextual Action" type="object" invisible="not binding_model_id" help="Remove 'More' top-menu contextual action related to this action"/>\n                        <button name="run" string="Run" type="object" class="btn-primary" invisible="model_name != 'ir.actions.server' or state != 'code'" help="Run this action manually."/>\n                        <button name="history_wizard_action" string="Code History" type="object" invisible="not show_code_history" help="View code history and restore a previous version"/>\n                    </header>\n                    <sheet>\n                        <div class="oe_button_box" name="button_box">\n                            <button type="object" name="action_open_parent_action" invisible="not parent_id" class="oe_stat_button" icon="fa-database">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Parent Action</span>\n                                </div>\n                            </button>\n                            <button type="object" name="action_open_scheduled_action" invisible="not ir_cron_ids or context.key != 'server_action'" context="{'key': 'ir_cron'}" class="oe_stat_button" icon="fa-refresh">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Scheduled Action</span>\n                                </div>\n                            </button>\n                        </div>\n                        <h1 class="oe_title">\n                            <field name="automated_name" invisible="1"/> <!-- needed for name compute -->\n                            <field name="name" placeholder="Set an explicit name"/>\n                        </h1>\n                        <group invisible="context.get('is_modal')">\n                            <group>\n                                <field name="model_id" options="{'no_create': True, 'no_open': True}" groups="base.group_no_one"/>\n                                <field name="model_id" options="{'no_create': True, 'no_open': True}" groups="!base.group_no_one" invisible="context.get('default_model_id')" domain="[('id', 'in', available_model_ids)]"/>\n                            </group>\n                            <group groups="base.group_no_one">\n                                <field name="group_ids" widget="many2many_tags"/>\n                            </group>\n                        </group>\n                        <t name="action_content" invisible="not model_id">\n                            <field name="allowed_states" invisible="1"/> <!-- Used to filter state using selection_badge_with_filter -->\n                            <div class="d-flex flex-column">\n                                <label for="state"/>\n                                <field name="state" widget="selection_badge_with_filter" options="{'size': 'sm', 'allowed_selection_field': 'allowed_states'}"/>\n                            </div>\n                            <div class="alert alert-warning" role="alert" invisible="not warning">\n                                <i class="fa fa-warning pe-2" title="Warning"/><field class="d-inline" name="warning" nolabel="1"/>\n                            </div>\n                            <div class="d-flex flex-row flex-wrap gap-2" invisible="state != 'object_write'">\n                                <field name="evaluation_type" class="oe_inline"/>\n                                <field name="update_path" widget="field_selector" class="oe_inline" options="{'model': 'model_name', 'allow_properties': False}" required="state == 'object_write'"/>\n                                <field name="update_field_id" invisible="True"/>  <!-- The field is store=True and readonly=False, in this view we want to save the value from compute/onchange -->\n                                <field name="update_related_model_id" invisible="True"/> <!-- This field is required for 'resource_ref' to compute possible m2m and m2o values -->\n                                <span invisible="evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']">by</span>\n                                <field name="update_m2m_operation" class="oe_inline" invisible="evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']" required="update_field_type in ['one2many', 'many2many']"/>\n                                <span invisible="evaluation_type != 'value' or update_field_type in ['one2many', 'many2many']">to</span>\n                                <span invisible="evaluation_type != 'sequence'">with</span>\n                                <field name="value" class="oe_inline" placeholder="Set a value..." invisible="update_field_id == False or value_field_to_show != 'value' or evaluation_type != 'value'" string="Custom Value"/>\n                                <field name="html_value" class="w-100" placeholder="Set a value..." invisible="update_field_id == False or value_field_to_show != 'html_value' or evaluation_type != 'value'" string="Custom Value"/>\n                                <field name="sequence_id" class="oe_inline" placeholder="Select a sequence..." invisible="evaluation_type != 'sequence'" required="evaluation_type == 'sequence'"/>\n                                <field name="resource_ref" class="oe_inline" placeholder="Choose a value..." string="Custom Value" options="{'model_field': 'update_related_model_id', 'no_create': True, 'no_open': True}" invisible="update_field_id == False or value_field_to_show != 'resource_ref' or evaluation_type == 'equation' or update_m2m_operation == 'clear'"/>\n                                <field name="selection_value" class="oe_inline" placeholder="Choose a value..." options="{'no_create': True, 'no_open': True}" invisible="update_field_id == False or value_field_to_show != 'selection_value' or evaluation_type == 'equation'"/>\n                                <field name="update_boolean_value" class="oe_inline" invisible="evaluation_type != 'value' or value_field_to_show != 'update_boolean_value'" required="value_field_to_show == 'update_boolean_value'"/>\n                                <span invisible="update_field_id != False or evaluation_type != 'value'" class="o_actions_server_set_a_value text-muted">Set a value...</span>\n                                <span invisible="evaluation_type != 'equation'">\n                                    to this Python expression:\n                                </span>\n                                <div class="w-100 d-flex flex-row gap-3" invisible="evaluation_type != 'equation'">\n                                    <field name="value" class="w-50" widget="code" options="{'mode': 'python'}" string="Expression"/>\n                                    <div class="w-50 opacity-75">\n                                        <span colspan="2" class="text-muted"> Available variables: </span>\n                                            <ul colspan="2" class="text-muted">\n                                                <li><code>env</code>: environment on which the action is triggered</li>\n                                                <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\n                                                <li><code>record</code>: record on which the action is triggered</li>\n                                                <li><code>records</code>: recordset of all records on which the action is triggered in multi mode</li>\n                                                <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\n                                                <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\n                                            </ul>\n                                    </div>\n                                </div>\n                            </div>\n                            <group invisible="state not in ['object_create', 'object_copy']">\n                                <group>\n                                    <field name="crud_model_id" options="{'no_create': True, 'no_open': True}" required="state in ['object_create', 'object_copy']"/>\n                                    <field name="value" widget="char" string="Name" invisible="state != 'object_create'" help="The name of the record to create" placeholder="e.g. Follow-up"/>\n                                    <field name="resource_ref" placeholder="Choose a record..." string="Duplicate from" options="{'model_field': 'crud_model_id', 'no_create': True, 'no_open': True}" invisible="crud_model_id == False or state != 'object_copy'" required="state == 'object_copy'"/>\n                                    <field name="link_field_id" domain="[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                         ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]" placeholder="Select a field to link the record to" options="{'no_create': True, 'no_open': True}" context="{'default_model_id': model_id, 'default_relation': crud_model_name}"/>\n                                </group>\n                            </group>\n                            <group invisible="state != 'webhook'">\n                                <group>\n                                    <field name="webhook_url" string="URL" placeholder="e.g. https://maker.ifttt.com/use/..."/>\n                                    <field name="webhook_field_ids" string="Fields" widget="many2many_tags" context="{'hide_model': 1}" domain="[('model_id', '=', model_id)]" placeholder="Select fields to include in the request..."/>\n                                </group>\n                                <group>\n                                    <label for="webhook_sample_payload"/>\n                                    <field name="webhook_sample_payload" string="Sample Payload" nolabel="1" colspan="2" readonly="1" widget="code" options="{'mode': 'javascript'}"/>\n                                </group>\n                            </group>\n                            <t invisible="state != 'multi'">\n                                <field name="child_ids" widget="many2many" mode="kanban" context="{                                     'is_modal': 1,                                     'default_model_id': model_id,                                 }"/>\n                            </t>\n                            <notebook>\n                                <page string="Code" invisible="state != 'code'">\n                                    <field name="code" invisible="state != 'code'" widget="code" options="{'mode': 'python'}" placeholder="Enter Python code here. Help about Python expression is available in the help tab of this document."/>\n                                </page>\n                                <page string="Help" invisible="state != 'code'" name="ir_actions_server_code_help">\n                                    <p>The following variables can be used:</p>\n                                    <ul>\n                                        <li><code>env</code>: environment on which the action is triggered</li>\n                                        <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\n                                        <li><code>record</code>: record on which the action is triggered; may be be void</li>\n                                        <li><code>records</code>: recordset of all records on which the action is triggered in multi mode; may be void</li>\n                                        <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\n                                        <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\n                                        <li><code>log(message, level='info')</code>: logging function to record debug information in <code>ir.logging</code> table</li>\n                                        <li><code>_logger.info(message)</code>: logger to emit messages in server logs</li>\n                                        <li><code>UserError</code>: exception class for raising user-facing warning messages</li>\n                                        <li><code>Command</code>: x2many commands namespace</li>\n                                        <li>To return an action, assign: <code>action = {...}</code></li>\n                                        <li>To notify progress for CRON call and re-trigger a call if there is remaining tasks, use <code>env['ir.cron']._notify_progress(done=task_done_count, remaining=task_remaining_count)</code></li>\n                                    </ul>\n                                    <p>\n                                        <widget name="documentation_link" path="/developer/reference/backend/orm.html" label="ORM API Documentation" icon="oi oi-fw oi-arrow-right me-1"/>\n                                    </p>\n                                    <div>\n                                        <p>Example of Python code:</p>\n                                        <pre style="white-space: pre-wrap">partner_name = record.name + '_code'\nenv['res.partner'].create({'name': partner_name})\n    </pre>\n                                    </div>\n                                </page>\n                                <page string="Usage" name="usage" invisible="1"/>\n                            </notebook>\n                        </t>\n                    </sheet>\n                </form>\n            	f	t	2026-10-13 11:41:24.189279	2026-10-13 14:41:44.098182	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
