\n                            <field name=\\"code\\" groups=\\"base.group_no_one\\" readonly=\\"id\\"/>\\n                            <field name=\\"state\\" widget=\\"radio\\"/>\\n                            <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{&quot;no_open&quot;:True}\\"/>\\n                        </group>\\n                    </group>\\n                    <notebook invisible=\\"module_id and module_state != 'installed'\\">\\n                        <page string=\\"Thông tin đăng nhập\\" name=\\"credentials\\" invisible=\\"code == 'none'\\">\\n                            <group name=\\"provider_credentials\\"/>\\n                        </page>\\n                        <page string=\\"Cấu hình\\" name=\\"configuration\\">\\n                            <group name=\\"provider_config\\">\\n                                <group string=\\"Biểu mẫu thanh toán\\" name=\\"payment_form\\">\\n                                    <field name=\\"payment_method_ids\\" string=\\"Phương thức thanh toán\\" domain=\\"[('is_primary', '=', True)]\\" readonly=\\"True\\" invisible=\\"state == 'disabled'\\" widget=\\"many2many_tags\\"/>\\n                                    <div colspan=\\"2\\">\\n                                        <a type=\\"object\\" name=\\"action_view_payment_methods\\" class=\\"btn btn-link\\" role=\\"button\\" invisible=\\"state == 'disabled'\\">\\n                                            <i class=\\"oi oi-fw o_button_icon oi-arrow-right\\"/>\\n                                            Bật phương thức thanh toán\\n                                        </a>\\n                                    </div>\\n                                    <field name=\\"allow_tokenization\\" invisible=\\"not support_tokenization\\"/>\\n                                    <field name=\\"capture_manually\\" invisible=\\"not support_manual_capture\\"/>\\n                                    <field name=\\"allow_express_checkout\\" invisible=\\"not support_express_checkout\\"/>\\n                                </group>\\n                                <group string=\\"Trạng thái khả dụng\\" name=\\"availability\\">\\n                                    <field name=\\"maximum_amount\\"/>\\n                                    <label for=\\"available_currency_ids\\" groups=\\"base.group_system\\"/>\\n                                    <!-- Use `o_row` to allow placing a button next to the field in overrides. -->\\n                                    <div name=\\"available_currencies\\" class=\\"o_row\\" groups=\\"base.group_system\\">\\n                                        <field name=\\"available_currency_ids\\" widget=\\"many2many_tags\\" placeholder=\\"Chọn tiền tệ. Để trống để không giới hạn loại tiền tệ.\\" options=\\"{'no_create': True}\\"/>\\n                                    </div>\\n                                    <field name=\\"available_country_ids\\" widget=\\"many2many_tags\\" placeholder=\\"Chọn quốc gia. Để trống để sử dụng ở mọi nơi.\\" options=\\"{'no_create': True}\\"/>\\n                                </group>\\n                                <group string=\\"Follow-up thanh toán\\" name=\\"payment_followup\\" invisible=\\"1\\"/>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Tin nhắn\\" name=\\"messages\\" invisible=\\"module_id and module_state != 'installed'\\">\\n                            <group>\\n                                <field name=\\"pre_msg\\"/>\\n                                <field name=\\"pending_msg\\"/>\\n                                <field name=\\"auth_msg\\" invisible=\\"not support_manual_capture\\"/>\\n                                <field name=\\"done_msg\\"/>\\n                                <field name=\\"cancel_msg\\"/>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n