\\" column_invisible=\\"True\\"/>\\n                            <button string=\\"Grant Access\\" name=\\"action_grant_access\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"is_portal or is_internal or email_state != 'ok'\\"/>\\n                            <button string=\\"Revoke Access\\" name=\\"action_revoke_access\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"not is_portal or is_internal\\"/>\\n                            <button string=\\"Re-Invite\\" name=\\"action_invite_again\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"not is_portal or is_internal or email_state != 'ok'\\"/>\\n                            <button string=\\"Internal User\\" invisible=\\"not is_internal\\" disabled=\\"True\\" title=\\"This partner is linked to an internal User and already has access to the Portal.\\"/>\\n                        </list>\\n                    </field>\\n                    <footer>\\n                        <button string=\\"Close\\" class=\\"btn-primary\\" special=\\"save\\" data-hotkey=\\"v\\"/>\\n                    </footer>\\n                </form>", "vi_VN": "<form string=\\"Quản lý Truy cập Portal\\">\\n                    <div class=\\"mb-3\\">\\n                        Hãy chọn các liên hệ mà sẽ thuộc về nhóm Portal trong danh sách dưới đây.\\n                        Địa chỉ email của từng liên hệ phải là địa chỉ email hợp lệ và duy nhất.\\n                        Nếu cần thiết, bạn có thể sửa bất cứ địa chỉ email của liên hệ nào trực tiếp\\n                        ngay trong danh sách.\\n                    </div>\\n                    <field name=\\"welcome_message\\" placeholder=\\"Nội dung này nằm trong phần cuối email gửi tới người dùng cổng thông tin mới.\\" class=\\"mb-3\\"/>\\n                    <field name=\\"user_ids\\" class=\\"o_portal_wizard_user_one2many\\" widget=\\"portal_wizard_user_one2many\\">\\n                        <list string=\\"Liên hệ\\" editable=\\"bottom\\" create=\\"false\\" delet