e=\\"\\" t-field=\\"o.scheduled_date\\" class=\\"m-0\\"/>\\n                        </div>\\n                        <div t-if=\\"o.user_id\\" class=\\"col-auto\\" name=\\"div_operator\\">\\n                            <strong>Người phụ trách:</strong>\\n                                <p t-field=\\"o.user_id\\">Mitchel Admin</p>\\n                        </div>\\n                    </div>\\n                    <div class=\\"oe_structure\\"/>\\n                    <t t-set=\\"format_number\\" t-value=\\"lambda x: int(x) if x == int(x) else x\\"/>\\n                    <table class=\\"table table-sm table-borderless\\" t-if=\\"o.state!='done'\\" name=\\"stock_move_table\\">\\n                        <thead>\\n                            <tr>\\n                                <th name=\\"th_sm_product\\"><strong>Sản phẩm</strong></th>\\n                                <th name=\\"th_sm_ordered\\" class=\\"text-end\\"><strong>Đã đặt hàng</strong></th>\\n                                <th name=\\"th_sm_quantity\\" class=\\"text-end\\"><strong>Đã giao</strong></th>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                            <t t-set=\\"lines\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty)\\"/>\\n                            <tr t-foreach=\\"lines\\" t-as=\\"move\\">\\n                                <td>\\n                                    <span t-field=\\"move.product_id\\">Bàn điều chỉnh được</span>\\n                                    <p t-if=\\"move.description_picking and move.description_picking != move.product_id.name and move._get_report_description_picking()\\">\\n                                        <span t-out=\\"move._get_report_description_picking()\\" t-options=\\"{'widget': 'text'}\\">Mô tả lệnh chuyển hàng</span>\\n                                    </p>\\n                                </td>\\n                                <td class=\\"o_td_quantity text-end\\">\\n                                    <span t-out=\\"format_number(move.product_uom_qty)\\" class=\\"text-nowrap\\">3.00</span>\\n                                    <span t-field=\\"move.product_uom\\" groups=\\"uom.group_uom\\">đơn vị</span>\\n                                    <t t-if=\\"move.packaging_uom_id != move.product_uom\\" groups=\\"uom.group_uom\\">\\n                                        <br/>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_qty\\">1.00</span>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_id\\">Gói 6 sản phẩm</span>\\n                                    </t>\\n                                </td>\\n                                <td class=\\"o_td_quantity text-end\\">\\n                                    <span t-out=\\"format_number(move.quantity)\\" class=\\"text-nowrap\\">3.00</span>\\n                                    <span t-field=\\"move.product_uom\\" groups=\\"uom.group_uom\\">đơn vị</span>\\n                                    <t t-if=\\"move.packaging_uom_id != move.product_uom\\" groups=\\"uom.group_uom\\">\\n                                        <br/>\\n                                        <span class=\\"text-muted\\" t-esc=\\"move.product_uom._compute_quantity(move.quantity, move.packaging_uom_id)\\">1.00</span>\\n                                        <span class=\\"text-muted\\" t-field=\\"move.packaging_uom_id\\">Gói 6 sản phẩm</span>\\n                                    </t>\\n                                </td>\\n                            </tr>\\n                        </tbody>\\n                    </table>\\n                    <table class=\\"table table-sm table-borderless\\" t-elif=\\"o.move_line_ids and o.state=='done'\\" name=\\"stock_move_line_table\\">\\n                        <t t-set=\\"has_multi_level_packages\\" t-value=\\"len(o.package_history_ids.filtered(lambda ph: ph.parent_dest_id)) &gt; 0\\"/>\\n                        <t t-set=\\"has_serial_number\\" t-value=\\"False\\"/>\\n                        <t t-set=\\"has_serial_number\\" t-value=\\"o.move_line_ids.mapped('lot_id')\\" groups=\\"stock.group_lot_on_delivery_slip\\"/>\\n                        <thead>\\n                            <tr>\\n                                <th name=\\"th_sml_product\\">Sản phẩm</th>\\n                                <th name=\\"th_sml_package\\" t-if=\\"has_multi_level_packages\\">Kiện hàng</th>\\n                                <th name=\\"th_sml_qty_ordered\\" class=\\"text-end\\" t-if=\\"not has_serial_number\\">\\n                                    Đã đặt\\n                                </th>\\n                                <th name=\\"lot_serial\\" class=\\"text-end\\" t-else=\\"\\">\\n                                    Số lô/sê-ri\\n                                </th>\\n                                <th name=\\"th_sml_quantity\\" class=\\"text-end\\">Đã giao</th>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\\n                                    product + description + uom combinations\\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\\n                            <!-- If has destination packages => create sections of corresponding products -->\\n                            <t t-if=\\"o.packages_count\\" name=\\"has_packages\\">\\n                                <t t-set=\\"packages\\" t-value=\\"o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id).package_id\\"/>\\n                                <t t-foreach=\\"packages\\" t-as=\\"package\\">\\n                                    <t t-call=\\"stock.stock_report_delivery_package_section_line\\"/>\\n                                    <t t-set=\\"package_move_lines\\" t-value=\\"o.move_ids.move_line_ids.filtered(lambda l: l.result_package_id == package or l.package_history_id.outermost_dest_id == package).sorted('product_id')\\"/>\\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\\n                                    <t t-if=\\"has_serial_number\\">\\n                                        <tr t-foreach=\\"package_move_lines\\" t-as=\\"move_line\\">\\n                                            <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                        </tr>\\n                                    </t>\\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\\n                                    <t t-else=\\"\\">\\n                                        <t t-set=\\"aggregated_lines\\" t-value=\\"package_move_lines._get_aggregated_product_quantities(strict=True)\\"/>\\n                                        <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                    </t>\\n                                </t>\\n                                <!-- Make sure we do another section for package-less products if they exist -->\\n                                <t t-set=\\"move_lines\\" t-value=\\"o.move_ids.move_line_ids.filtered(lambda l: not l.result_package_id)\\"/>\\n                                <t t-set=\\"aggregated_lines\\" t-value=\\"o.move_ids.move_line_ids._get_aggregated_product_quantities(except_package=True)\\"/>\\n                                <t t-if=\\"move_lines or aggregated_lines\\" name=\\"no_package_move_lines\\">\\n                                    <t t-call=\\"stock.stock_report_delivery_no_package_section_line\\" name=\\"no_package_section\\"/>\\n                                    <t t-if=\\"has_serial_number\\">\\n                                        <tr t-foreach=\\"move_lines\\" t-as=\\"move_line\\">\\n                                            <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                        </tr>\\n                                    </t>\\n                                    <t t-elif=\\"aggregated_lines\\">\\n                                        <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                    </t>\\n                                </t>\\n                            </t>\\n                            <!-- No destination packages -->\\n                            <t t-else=\\"\\">\\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\\n                                <t t-if=\\"has_serial_number\\">\\n                                    <tr t-foreach=\\"o.move_ids.move_line_ids\\" t-as=\\"move_line\\">\\n                                        <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                    </tr>\\n                                </t>\\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\\n                                <t t-else=\\"\\" name=\\"aggregated_move_lines\\">\\n                                    <t t-set=\\"aggregated_lines\\" t-value=\\"o.move_ids.move_line_ids._get_aggregated_product_quantities()\\"/>\\n                                    <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                </t>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                    <div class=\\"oe_structure\\"/>\\n                    <t t-set=\\"backorders\\" t-value=\\"o.backorder_ids.filtered(lambda x: x.state not in ('done', 'cancel'))\\"/>\\n                    <div t-if=\\"not (o.backorder_ids and backorders)\\" class=\\"oe_structure\\"/>\\n                    <div t-else=\\"\\">\\n                        <p class=\\"mt-5\\">\\n                            <span>Số lượng còn lại chưa giao:</span>\\n                        </p>\\n                        <table class=\\"table table-sm table-borderless\\" name=\\"stock_backorder_table\\">\\n                            <thead>\\n                                <tr>\\n                                    <th name=\\"th_sb_product\\"><strong>Sản phẩm</strong></th>\\n                                    <th/>\\n                                    <th name=\\"th_sb_quantity\\" class=\\"text-end\\"><strong>Số lượng</strong></th>\\n                                </tr>\\n                            </thead>\\n                            <tbody>\\n                                <tr t-foreach=\\"backorders.mapped('move_ids').filtered(lambda x: x.product_uom_qty)\\" t-as=\\"bo_line\\">\\n                                    <td class=\\"w-auto\\">\\n                                        <span t-field=\\"bo_line.product_id\\">Ghế văn phòng</span>\\n                                        <p t-if=\\"bo_line.description_picking and bo_line.description_picking != bo_line.product_id.name and bo_line._get_report_description_picking()\\">\\n                                            <span t-out=\\"bo_line._get_report_description_picking()\\" t-options=\\"{'widget': 'text'}\\">Mô tả lệnh chuyển hàng</span>\\n                                        </p>\\n                                    </td>\\n                                    <td/>\\n                                    <td class=\\"text-end w-auto\\">\\n                                        <span t-out=\\"format_number(bo_line.product_uom_qty)\\">3.00</span>\\n                                        <span t-field=\\"bo_line.product_uom\\" groups=\\"uom.group_uom\\">đơn vị</span>\\n                                    </td>\\n                                </tr>\\n                            </tbody>\\n                        </table>\\n                    </div>\\n\\n                    <div t-if=\\"not o.signature\\" class=\\"oe_structure\\"/>\\n                    <div t-else=\\"\\" class=\\"mt32 ml64 mr4\\" name=\\"signature\\">\\n                        <div class=\\"offset-8\\">\\n                            <strong>Chữ ký</strong>\\n                        </div>\\n                        <div class=\\"offset-8\\">\\n                            <img t-att-src=\\"image_data_uri(o.signature)\\" style=\\"max-height: 4cm; max-width: 8cm;\\"/>\\n                        </div>\\n                        <div t-if=\\"o.partner_id.name\\" class=\\"offset-8 text-center\\">\\n                            <p t-field=\\"o.partner_id.name\\">John Doe</p>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n         </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_delivery_document">\n        <t t-call="web.html_container">\n            <t t-call="web.external_layout">\n                <t t-set="o" t-value="o.with_context(lang=o._get_report_lang())"/>\n                <t t-set="partner" t-value="o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False"/>\n\n                <t t-set="address">\n                    <div name="div_outgoing_address">\n                        <div name="outgoing_delivery_address" t-if="o.should_print_delivery_address()">\n                            <strong>Delivery Address</strong>\n                            <div t-out="o.move_ids[0].partner_id or o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        </div>\n                        <div name="outgoing_warehouse_address" t-elif="o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id">\n                            <strong>Warehouse Address</strong>\n                            <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        </div>\n                    </div>\n                </t>\n                <t t-set="information_block">\n                    <div class="row">\n                        <div class="col-7" name="div_incoming_address">\n                            <t t-set="show_partner" t-value="False"/>\n                            <div name="vendor_address" t-if="o.picking_type_id.code=='incoming' and partner">\n                                <strong>Vendor Address</strong>\n                                <t t-set="show_partner" t-value="True"/>\n                            </div>\n                            <div name="customer_address" t-if="o.picking_type_id.code=='outgoing' and partner and partner != partner.commercial_partner_id">\n                                <strong>Customer</strong>\n                                <t t-set="show_partner" t-value="True"/>\n                            </div>\n                            <div t-if="show_partner" name="partner_header">\n                                <div t-field="partner.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                            </div>\n                        </div>\n                    </div>\n                </t>\n                <div class="page">\n                    <h2 style="margin-top: 15px;">\n                        <span t-out="o.picking_type_id._get_code_report_name()"/>\n                        <span t-field="o.name">WH/OUT/0001</span>\n                    </h2>\n                    <div class="oe_structure"/>\n                    <div id="informations" class="report-wrapping-flexbox clearfix row mb-4">\n                        <div t-if="o.origin" class="col col-3 mw-100 mb-2" name="div_origin">\n                            <strong>Order</strong>\n                            <div t-field="o.origin" class="m-0">S0001</div>\n                        </div>\n                        <div t-if="o.picking_type_id.code == 'internal' and o.partner_id" class="col col-3 mw-100 mb-2" name="div_contact">\n                            <strong>Contact</strong>\n                            <div t-field="o.partner_id" class="m-0"/>\n                        </div>\n                        <div t-if="o.state" class="col col-3 mw-100 mb-2" name="div_sched_date">\n                            <strong>Shipping Date</strong>\n                            <div t-if="o.state == 'done'" t-field="o.date_done" class="m-0"/>\n                            <div t-else="" t-field="o.scheduled_date" class="m-0"/>\n                        </div>\n                        <div t-if="o.user_id" class="col-auto" name="div_operator">\n                            <strong>Operator:</strong>\n                                <p t-field="o.user_id">Mitchel Admin</p>\n                        </div>\n                    </div>\n                    <div class="oe_structure"/>\n                    <t t-set="format_number" t-value="lambda x: int(x) if x == int(x) else x"/>\n                    <table class="table table-sm table-borderless" t-if="o.state!='done'" name="stock_move_table">\n                        <thead>\n                            <tr>\n                                <th name="th_sm_product"><strong>Product</strong></th>\n                                <th name="th_sm_ordered" class="text-end"><strong>Ordered</strong></th>\n                                <th name="th_sm_quantity" class="text-end"><strong>Delivered</strong></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-set="lines" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty)"/>\n                            <tr t-foreach="lines" t-as="move">\n                                <td>\n                                    <span t-field="move.product_id">Customizable Desk</span>\n                                    <p t-if="move.description_picking and move.description_picking != move.product_id.name and move._get_report_description_picking()">\n                                        <span t-out="move._get_report_description_picking()" t-options="{'widget': 'text'}">Description on transfer</span>\n                                    </p>\n                                </td>\n                                <td class="o_td_quantity text-end">\n                                    <span t-out="format_number(move.product_uom_qty)" class="text-nowrap">3.00</span>\n                                    <span t-field="move.product_uom" groups="uom.group_uom">units</span>\n                                    <t t-if="move.packaging_uom_id != move.product_uom" groups="uom.group_uom">\n                                        <br/>\n                                        <span class="text-muted" t-field="move.packaging_uom_qty">1.00</span>\n                                        <span class="text-muted" t-field="move.packaging_uom_id">Pack of 6</span>\n                                    </t>\n                                </td>\n                                <td class="o_td_quantity text-end">\n                                    <span t-out="format_number(move.quantity)" class="text-nowrap">3.00</span>\n                                    <span t-field="move.product_uom" groups="uom.group_uom">units</span>\n                                    <t t-if="move.packaging_uom_id != move.product_uom" groups="uom.group_uom">\n                                        <br/>\n                                        <span class="text-muted" t-esc="move.product_uom._compute_quantity(move.quantity, move.packaging_uom_id)">1.00</span>\n                                        <span class="text-muted" t-field="move.packaging_uom_id">Pack of 6</span>\n                                    </t>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                    <table class="table table-sm table-borderless" t-elif="o.move_line_ids and o.state=='done'" name="stock_move_line_table">\n                        <t t-set="has_multi_level_packages" t-value="len(o.package_history_ids.filtered(lambda ph: ph.parent_dest_id)) &gt; 0"/>\n                        <t t-set="has_serial_number" t-value="False"/>\n                        <t t-set="has_serial_number" t-value="o.move_line_ids.mapped('lot_id')" groups="stock.group_lot_on_delivery_slip"/>\n                        <thead>\n                            <tr>\n                                <th name="th_sml_product">Product</th>\n                                <th name="th_sml_package" t-if="has_multi_level_packages">Package</th>\n                                <th name="th_sml_qty_ordered" class="text-end" t-if="not has_serial_number">\n                                    Ordered\n                                </th>\n                                <th name="lot_serial" class="text-end" t-else="">\n                                    Lot/Serial Number\n                                </th>\n                                <th name="th_sml_quantity" class="text-end">Delivered</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\n                                    product + description + uom combinations\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\n                            <!-- If has destination packages => create sections of corresponding products -->\n                            <t t-if="o.packages_count" name="has_packages">\n                                <t t-set="packages" t-value="o.package_history_ids.filtered(lambda ph: not ph.parent_dest_id).package_id"/>\n                                <t t-foreach="packages" t-as="package">\n                                    <t t-call="stock.stock_report_delivery_package_section_line"/>\n                                    <t t-set="package_move_lines" t-value="o.move_ids.move_line_ids.filtered(lambda l: l.result_package_id == package or l.package_history_id.outermost_dest_id == package).sorted('product_id')"/>\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\n                                    <t t-if="has_serial_number">\n                                        <tr t-foreach="package_move_lines" t-as="move_line">\n                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                        </tr>\n                                    </t>\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\n                                    <t t-else="">\n                                        <t t-set="aggregated_lines" t-value="package_move_lines._get_aggregated_product_quantities(strict=True)"/>\n                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                    </t>\n                                </t>\n                                <!-- Make sure we do another section for package-less products if they exist -->\n                                <t t-set="move_lines" t-value="o.move_ids.move_line_ids.filtered(lambda l: not l.result_package_id)"/>\n                                <t t-set="aggregated_lines" t-value="o.move_ids.move_line_ids._get_aggregated_product_quantities(except_package=True)"/>\n                                <t t-if="move_lines or aggregated_lines" name="no_package_move_lines">\n                                    <t t-call="stock.stock_report_delivery_no_package_section_line" name="no_package_section"/>\n                                    <t t-if="has_serial_number">\n                                        <tr t-foreach="move_lines" t-as="move_line">\n                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                        </tr>\n                                    </t>\n                                    <t t-elif="aggregated_lines">\n                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                    </t>\n                                </t>\n                            </t>\n                            <!-- No destination packages -->\n                            <t t-else="">\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\n                                <t t-if="has_serial_number">\n                                    <tr t-foreach="o.move_ids.move_line_ids" t-as="move_line">\n                                        <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                    </tr>\n                                </t>\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\n                                <t t-else="" name="aggregated_move_lines">\n                                    <t t-set="aggregated_lines" t-value="o.move_ids.move_line_ids._get_aggregated_product_quantities()"/>\n                                    <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                    <div class="oe_structure"/>\n                    <t t-set="backorders" t-value="o.backorder_ids.filtered(lambda x: x.state not in ('done', 'cancel'))"/>\n                    <div t-if="not (o.backorder_ids and backorders)" class="oe_structure"/>\n                    <div t-else="">\n                        <p class="mt-5">\n                            <span>Remaining quantities not yet delivered:</span>\n                        </p>\n                        <table class="table table-sm table-borderless" name="stock_backorder_table">\n                            <thead>\n                                <tr>\n                                    <th name="th_sb_product"><strong>Product</strong></th>\n                                    <th/>\n                                    <th name="th_sb_quantity" class="text-end"><strong>Quantity</strong></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr t-foreach="backorders.mapped('move_ids').filtered(lambda x: x.product_uom_qty)" t-as="bo_line">\n                                    <td class="w-auto">\n                                        <span t-field="bo_line.product_id">Office Chair</span>\n                                        <p t-if="bo_line.description_picking and bo_line.description_pi