792	16	\N	1	1	Account Terms and Conditions Setting Banner	\N	account.account_terms_conditions_setting_banner	qweb	account/views/terms_template.xml	primary	{"en_US": "<t name=\\"Account Terms and Conditions Setting Banner\\" t-name=\\"account.account_terms_conditions_setting_banner\\">\\n        <div id=\\"terms_conditions\\" t-ignore=\\"true\\" class=\\"text-center\\">\\n            <span>This is a preview of your Terms &amp; Conditions.</span>\\n            <a t-att-href=\\"backend_url\\"><i class=\\"oi oi-arrow-right me-1\\"/>Back to settings</a>\\n        </div>\\n        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Close\\"/>\\n    </t>", "vi_VN": "<t name=\\"Account Terms and Conditions Setting Banner\\" t-name=\\"account.account_terms_conditions_setting_banner\\">\\n        <div id=\\"terms_conditions\\" t-ignore=\\"true\\" class=\\"text-center\\">\\n            <span>Đây là bản xem trước Điều khoản &amp; điều kiện của bạn.</span>\\n            <a t-att-href=\\"backend_url\\"><i class=\\"oi oi-arrow-right me-1\\"/>Quay lại cài đặt</a>\\n        </div>\\n        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Đóng\\"/>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Account Terms and Conditions Setting Banner" t-name="account.account_terms_conditions_setting_banner">\n        <div id="terms_conditions" t-ignore="true" class="text-center">\n            <span>This is a preview of your Terms &amp; Conditions.</span>\n            <a t-att-href="backend_url"><i class="oi oi-arrow-right me-1"/>Back to settings</a>\n        </div>\n        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>\n    </t>\n\n    	f	t	2026-10-13 11:46:47.690611	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
794	16	\N	1	1	account_default_terms_and_conditions	\N	account.account_default_terms_and_conditions	qweb	account/views/terms_template.xml	primary	{"en_US": "<t t-name=\\"account.account_default_terms_and_conditions\\">\\n        <div>\\n            <h1>STANDARD TERMS AND CONDITIONS OF SALE</h1>\\n            <p>You should update this document to reflect your T&amp;C.</p>\\n            <p>Below text serves as a suggestion and doesn’t engage Odoo S.A. responsibility.</p>\\n            <ol>\\n                <li>\\n                    The client explicitly waives its own standard terms and conditions, even if these were drawn up after these standard terms and conditions of sale. In order to be valid, any derogation must be expressly agreed to in advance in writing.\\n                </li>\\n                <li>\\n                    Our invoices are payable within 21 working days, unless another payment timeframe is indicated on either the invoice or the order. In the event of non-payment by the due date, <t t-out=\\"company_name\\"/> reserves the right to request a fixed interest payment amounting to 10% of the sum remaining due. <t t-out=\\"company_name\\"/> will be authorized to suspend any provision of services without prior warning in the event of late payment.\\n                </li>\\n                <li>\\n                    If a payment is still outstanding more than sixty (60) days after the due payment date, <t t-out=\\"company_name\\"/> reserves the right to call on the services of a debt recovery company. All legal expenses will be payable by the client.\\n                </li>\\n                <li>\\n                    Certain countries apply withholding at source on the amount of invoices, in accordance with their internal legislation. Any withholding at source will be paid by the client to the tax authorities. Under no circumstances can <t t-out=\\"company_name\\"/> become involved in costs related to a country's legislation. The amount of the invoice will therefore be due to <t t-out=\\"company_name\\"/> in its entirety and does not include any costs relating to the legislation of the country in which the client is located.\\n                </li>\\n                <li>\\n                    <t t-out=\\"company_name\\"/> undertakes to do its best to supply performant services in due time in accordance with the agreed timeframes. However, none of its obligations can be considered as being an obligation to achieve results. <t t-out=\\"company_name\\"/> cannot under any circumstances, be required by the client to appear as a third party in the context of any claim for damages filed against the client by an end consumer.\\n                </li>\\n                <li>\\n                    In order for it to be admissible, <t t-out=\\"company_name\\"/> must be notified of any claim by means of a letter sent by recorded delivery to its registered office within 8 days of the delivery of the goods or the provision of the services.\\n                </li>\\n                <li>\\n                    All our contractual relations will be governed exclusively by <t t-out=\\"company_country\\"/> law.\\n                </li>\\n            </ol>\\n        </div>\\n    </t>", "vi_VN": "<t t-name=\\"account.account_default_terms_and_conditions\\">\\n        <div>\\n            <h1>ĐIỀU KHOẢN VÀ ĐIỀU KIỆN BÁN HÀNG TIÊU CHUẨN</h1>\\n            <p>Bạn nên cập nhật chứng từ này để thể hiện điều khoản và điều kiện của mình.</p>\\n            <p>Văn bản dưới đây được xem như một gợi ý và không liên quan đến trách nhiệm của Odoo S.A.</p>\\n            <ol>\\n                <li>\\n                    Khách hàng từ bỏ một cách rõ ràng các điều khoản và điều kiện tiêu chuẩn của riêng mình, ngay cả khi những điều khoản và điều kiện đó được soạn thảo sau các điều khoản và điều kiện bán hàng tiêu chuẩn này. Để có hiệu lực, việc huỷ bỏ phải được đồng ý trước một cách rõ ràng bằng văn bản.\\n                </li>\\n                <li>\\n                    Hóa đơn của chúng tôi được thanh toán trong vòng 21 ngày làm việc, trừ khi khung thời gian thanh toán khác được ghi trên hóa đơn hoặc đơn hàng. Trong trường hợp không thanh toán đúng hạn, <t t-out=\\"company_name\\"/> có quyền yêu cầu một khoản thanh toán lãi cố định lên tới 10% số tiền còn lại chưa thanh toán. <t t-out=\\"company_name\\"/> sẽ có quyền tạm dừng cung cấp dịch vụ mà không cần cảnh báo trước trong trường hợp thanh toán chậm.\\n                </li>\\n                <li>\\n                    Nếu một khoản thanh toán vẫn chưa được thanh toán quá sáu mươi (60) ngày sau ngày đến hạn thanh toán, <t t-out=\\"company_name\\"/> có quyền sử dụng dịch vụ của một công ty thu hồi nợ. Mọi chi phí pháp lý sẽ do khách hàng chi trả.\\n                </li>\\n                <li>\\n                    Một số quốc gia áp dụng khấu lưu tại nguồn đối với số lượng hóa đơn, phù hợp với luật nội bộ của họ. Mọi khoản khấu trừ tại nguồn sẽ được khách hàng nộp cho cơ quan thuế. Trong mọi trường hợp không thể <t t-out=\\"company_name\\"/> không được tham gia vào các chi phí liên quan đến luật pháp của một quốc gia. Do đó, toàn bộ số tiền trên hóa đơn sẽ do <t t-out=\\"company_name\\"/> toàn bộ và không bao gồm bất kỳ chi phí nào liên quan đến luật pháp của quốc gia nơi khách hàng đặt trụ sở.\\n                </li>\\n                <li>\\n                    <t t-out=\\"company_name\\"/> cam kết sẽ cố gắng cung cấp dịch vụ đúng hạn theo khung thời gian đã thỏa thuận. Tuy nhiên, không có nghĩa vụ bắt buộc phải đạt được điều đó. <t t-out=\\"company_name\\"/> trong mọi trường hợp, không thể được khách hàng yêu cầu xuất hiện với tư cách là bên thứ ba nếu có bất kỳ yêu cầu bồi thường thiệt hại nào từ người tiêu dùng cuối cùng đối với khách hàng.\\n                </li>\\n                <li>\\n                    Để được chấp nhận, <t t-out=\\"company_name\\"/> phải được thông báo về bất kỳ khiếu nại nào bằng một lá thư gửi theo phương thức đã xác định đến văn phòng chính thức trong vòng 8 ngày kể từ ngày giao hàng hoặc cung cấp dịch vụ.\\n                </li>\\n                <li>\\n                    Tất cả quan hệ hợp đồng của chúng tôi sẽ được độc quyền điều chỉnh bởi <t t-out=\\"company_country\\"/> pháp luật.\\n                </li>\\n            </ol>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="account.account_default_terms_and_conditions">\n        <div>\n            <h1>STANDARD TERMS AND CONDITIONS OF SALE</h1>\n            <p>You should update this document to reflect your T&amp;C.</p>\n            <p>Below text serves as a suggestion and doesn’t engage Odoo S.A. responsibility.</p>\n            <ol>\n                <li>\n                    The client explicitly waives its own standard terms and conditions, even if these were drawn up after these standard terms and conditions of sale. In order to be valid, any derogation must be expressly agreed to in advance in writing.\n                </li>\n                <li>\n                    Our invoices are payable within 21 working days, unless another payment timeframe is indicated on either the invoice or the order. In the event of non-payment by the due date, <t t-out="company_name"/> reserves the right to request a fixed interest payment amounting to 10% of the sum remaining due. <t t-out="company_name"/> will be authorized to suspend any provision of services without prior warning in the event of late payment.\n                </li>\n                <li>\n                    If a payment is still outstanding more than sixty (60) days after the due payment date, <t t-out="company_name"/> reserves the right to call on the services of a debt recovery company. All legal expenses will be payable by the client.\n                </li>\n                <li>\n                    Certain countries apply withholding at source on the amount of invoices, in accordance with their internal legislation. Any withholding at source will be paid by the client to the tax authorities. Under no circumstances can <t t-out="company_name"/> become involved in costs related to a country's legislation. The amount of the invoice will therefore be due to <t t-out="company_name"/> in its entirety and does not include any costs relating to the legislation of the country in which the client is located.\n                </li>\n                <li>\n                    <t t-out="company_name"/> undertakes to do its best to supply performant services in due time in accordance with the agreed timeframes. However, none of its obligations can be considered as being an obligation to achieve results. <t t-out="company_name"/> cannot under any circumstances, be required by the client to appear as a third party in the context of any claim for damages filed against the client by an end consumer.\n                </li>\n                <li>\n                    In order for it to be admissible, <t t-out="company_name"/> must be notified of any claim by means of a letter sent by recorded delivery to its registered office within 8 days of the delivery of the goods or the provision of the services.\n                </li>\n                <li>\n                    All our contractual relations will be governed exclusively by <t t-out="company_country"/> law.\n                </li>\n            </ol>\n        </div>\n    </t>\n\n	f	t	2026-10-13 11:46:47.690611	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
