                </button>\\n                        <button name=\\"action_see_package_histories\\" string=\\"Packages\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-cubes\\" invisible=\\"state != 'done' or not packages_count\\" groups=\\"stock.group_tracking_lot\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Packages</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"311\\" icon=\\"oi-arrow-up\\" class=\\"oe_stat_button\\" type=\\"action\\" invisible=\\"state != 'done' or not has_tracking\\" groups=\\"stock.group_production_lot\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Traceability</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_view_reception_report\\" type=\\"object\\" context=\\"{'default_picking_ids': [id]}\\" class=\\"oe_stat_button\\" icon=\\"fa-list\\" invisible=\\"not show_allocation\\" groups=\\"stock.group_reception_report\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Allocation</span>\\n                            </div>\\n                        </button>\\n                        <!-- Use the following button to avoid onchange on one2many -->\\n                        <button name=\\"action_picking_move_tree\\" class=\\"oe_stat_button\\" icon=\\"oi-arrows-v\\" type=\\"object\\" help=\\"List view of operations\\" groups=\\"base.group_no_one\\" invisible=\\"(is_locked or state == 'done') or state == 'done' and is_locked\\" context=\\"{'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref':'stock.view_move_form', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id}\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Operations</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_detailed_operations\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" help=\\"List view of detailed operations\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Moves</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_next_transfer\\" class=\\"oe_stat_button\\" icon=\\"fa-exchange\\" type=\\"object\\" help=\\"List view of next transfers\\" invisible=\\"not show_next_pickings\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Next Transfer</span>\\n                            </div>\\n                        </button>\\n                    </div>\\n                    <div class=\\"oe_title\\">\\n                        <h1 class=\\"d-flex\\">\\n                            <field name=\\"priority\\" widget=\\"priority\\" class=\\"me-3\\"/>\\n                            <div invisible=\\"id\\">New <field name=\\"picking_type_code\\"/></div>\\n                            <field name=\\"name\\" invisible=\\"not id\\"/>\\n                        </h1>\\n                    </div>\\n                    <group>\\n                        <group>\\n                            <div class=\\"o_td_label\\">\\n                                <label for=\\"partner_id\\" string=\\"Delivery Address\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code != 'outgoing'\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Receive From\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code != 'incoming'\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Contact\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code in ['incoming', 'outgoing']\\"/>\\n                            </div>\\n                            <field name=\\"partner_id\\" nolabel=\\"1\\" readonly=\\"state in ['cancel', 'done']\\" placeholder=\\"e.g. Lumber Inc\\"/>\\n                            <field name=\\"picking_type_id\\" options=\\"{'no_open': True}\\" readonly=\\"state in ('done', 'cancel')\\" domain=\\"[('code', 'in', ('incoming', 'outgoing', 'internal'))]\\"/>\\n                            <field name=\\"location_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_dest_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_id\\" options=\\"{'no_create': True}\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"picking_type_code == 'incoming'\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_dest_id\\" options=\\"{'no_create': True}\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"picking_type_code == 'outgoing'\\" readonly=\\"state == 'done'\\" domain=\\"[('usage','!=','view')]\\"/>\\n                            <field name=\\"backorder_id\\" invisible=\\"not backorder_id\\"/>\\n                            <field name=\\"use_create_lots\\" invisible=\\"1\\"/> <!-- used by embedded stock.move list view below -->\\n                        </group>\\n                        <group>\\n                            <label for=\\"scheduled_date\\"/>\\n                            <div class=\\"o_row\\">\\n                                <field name=\\"scheduled_date\\" readonly=\\"not is_date_editable\\" required=\\"id\\" decoration-warning=\\"state not in ('done', 'cancel') and scheduled_date &lt; now\\" decoration-danger=\\"state not in ('done', 'cancel') and scheduled_date &lt; current_date\\" decoration-bf=\\"state not in ('done', 'cancel') and (scheduled_date &lt; current_date or scheduled_date &lt; now)\\"/>\\n                                <field name=\\"json_popover\\" nolabel=\\"1\\" widget=\\"stock_rescheduling_popover\\" invisible=\\"not json_popover\\"/>\\n                            </div>\\n                            <field name=\\"date_deadline\\" invisible=\\"state in ('done', 'cancel') or not date_deadline\\" decoration-danger=\\"date_deadline and date_deadline &lt; current_date\\" decoration-bf=\\"date_deadline and date_deadline &lt; current_date\\"/>\\n                            <field name=\\"products_availability_state\\" invisible=\\"1\\"/>\\n                            <field name=\\"products_availability\\" invisible=\\"picking_type_code not in ('outgoing', 'internal') or state not in ['confirmed', 'waiting', 'assigned']\\" decoration-success=\\"state == 'assigned' or products_availability_state == 'available'\\" decoration-warning=\\"state != 'assigned' and products_availability_state in ('expected', 'available')\\" decoration-danger=\\"state != 'assigned' and products_availability_state == 'late'\\"/>\\n                            <field name=\\"date_done\\" string=\\"Effective Date\\" invisible=\\"state != 'done'\\" readonly=\\"not is_date_editable\\"/>\\n                            <field name=\\"origin\\" placeholder=\\"e.g. PO0032\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                            <field name=\\"owner_id\\" groups=\\"stock.group_tracking_owner\\" invisible=\\"picking_type_code != 'incoming'\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                        </group>\\n                    </group>\\n                    <field name=\\"picking_properties\\" columns=\\"2\\"/>\\n                    <notebook>\\n                        <page string=\\"Operations\\" name=\\"operations\\">\\n                            <field name=\\"move_ids\\" mode=\\"list,kanban\\" widget=\\"stock_move_one2many\\" add-label=\\"Add a Product\\" readonly=\\"state == 'done' and is_locked\\" context=\\"{'default_company_id': company_id, 'default_date': scheduled_date, 'default_date_deadline': date_deadline, 'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref': 'stock.view_stock_move_operations', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_partner_id': partner_id, 'picking_state': state}\\">\\n                                <list decoration-muted=\\"scrap_id or state == 'cancel' or (state == 'done' and is_locked == True)\\" string=\\"Stock Moves\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Add a Product\\"/>\\n                                    </control>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" readonly=\\"0\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_dest_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"partner_id\\" column_invisible=\\"True\\" readonly=\\"state == 'done'\\"/>\\n                                    <field name=\\"picking_code\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_details_visible\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"additional\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_lines_count\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_locked\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_storable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_tracking\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\" required=\\"1\\" readonly=\\"(state != 'draft' and not additional) or move_lines_count &gt; 0\\" force_save=\\"1\\" widget=\\"move_product_label_field\\"/>\\n                                    <field name=\\"forecast_availability\\" string=\\"\\" widget=\\"forecast_widget\\" column_invisible=\\"parent.state in ('cancel', 'done') or parent.picking_type_code not in ['internal', 'outgoing']\\"/>\\n                                    <field name=\\"packaging_uom_qty\\" optional=\\"hide\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"packaging_uom_id\\" optional=\\"hide\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"location_final_id\\" optional=\\"hide\\" groups=\\"stock.group_stock_multi_locations\\"/>\\n                                    <field name=\\"description_picking\\" string=\\"Description\\" optional=\\"show\\"/>\\n                                    <field name=\\"date\\" optional=\\"hide\\"/>\\n                                    <field name=\\"date_deadline\\" optional=\\"hide\\"/>\\n                                    <field name=\\"is_quantity_done_editable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_quant\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_lots_text\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_lots_m2o\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_initial_demand_editable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"display_import_lot\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_lines_without_result_package\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"package_ids\\" optional=\\"show\\" widget=\\"package_m2m\\" groups=\\"stock.group_tracking_lot\\" width=\\"200px\\" readonly=\\"1\\"/>\\n                                    <field name=\\"product_uom_qty\\" string=\\"Demand\\" readonly=\\"not is_initial_demand_editable\\"/>\\n                                    <field name=\\"forecast_expected_date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_qty\\" readonly=\\"1\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"quantity\\" string=\\"Quantity\\" readonly=\\"not is_quantity_done_editable\\" column_invisible=\\"parent.state=='draft'\\" decoration-danger=\\"product_uom_qty and quantity &gt; product_uom_qty and parent.state not in ['done', 'cancel']\\"/>\\n                                    <field name=\\"product_uom\\" readonly=\\"state != 'draft' and not additional\\" options=\\"{'no_open': True, 'no_create': True}\\" widget=\\"many2one_uom\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"picked\\" optional=\\"hide\\" column_invisible=\\"parent.state=='draft'\\"/>\\n                                    <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" column_invisible=\\"parent.state == 'draft'\\" groups=\\"stock.group_production_lot\\" invisible=\\"not show_details_visible or has_tracking == 'none'\\" optional=\\"hide\\" options=\\"{'create': [('parent.use_create_lots', '=', True)]}\\" context=\\"{'default_company_id': company_id, 'default_product_id': product_id, 'active_picking_id': parent.id}\\" domain=\\"[('product_id','=',product_id)]\\"/>\\n                                    <button name=\\"action_show_details\\" type=\\"object\\" string=\\"Details\\" title=\\"Details\\" invisible=\\"not show_details_visible\\"/>\\n                                </list>\\n                            </field>\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <button class=\\"btn-secondary float-end\\" name=\\"action_put_in_pack\\" type=\\"object\\" string=\\"Put in Pack\\" invisible=\\"state in ('draft', 'done', 'cancel')\\" groups=\\"stock.group_tracking_lot\\" data-hotkey=\\"shift+g\\"/>\\n                        </page>\\n                        <page string=\\"Additional Info\\" name=\\"extra\\">\\n                            <group>\\n                                <group string=\\"Other Information\\" name=\\"other_infos\\">\\n                                    <field name=\\"move_type\\" invisible=\\"picking_type_code == 'incoming'\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" domain=\\"[('share', '=', False)]\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" force_save=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Note\\" name=\\"note\\">\\n                            <field name=\\"note\\" string=\\"Note\\" placeholder=\\"Add an internal note that will be printed on the Picking Operations sheet\\"/>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>", "vi_VN": "<form string=\\"Lệnh chuyển hàng\\">\\n                <header>\\n                    <button name=\\"action_confirm\\" invisible=\\"state != 'draft'\\" string=\\"Đánh dấu việc cần làm\\" type=\\"object\\" class=\\"oe_highlight\\" groups=\\"base.group_user\\" data-hotkey=\\"q\\"/>\\n                    <button name=\\"action_assign\\" invisible=\\"not show_check_availability\\" string=\\"Kiểm tra tình trạng còn hàng\\" type=\\"object\\" class=\\"oe_highlight\\" groups=\\"base.group_user\\" data-hotkey=\\"w\\"/>\\n                    <button name=\\"button_validate\\" invisible=\\"state in ('draft', 'confirmed', 'done', 'cancel')\\" string=\\"Xác nhận\\" type=\\"object\\" class=\\"oe_highlight\\" groups=\\"stock.group_stock_user\\" data-hotkey=\\"v\\"/>\\n                    <button name=\\"button_validate\\" invisible=\\"state in ('waiting', 'assigned', 'done', 'cancel')\\" string=\\"Xác nhận\\" type=\\"object\\" groups=\\"stock.group_stock_user\\" class=\\"o_btn_validate\\" data-hotkey=\\"v\\"/>\\n                    <widget name=\\"signature\\" string=\\"Ký tên\\" highlight=\\"1\\" invisible=\\"not id or picking_type_code != 'outgoing' or state != 'done' or is_signed\\" full_name=\\"partner_id\\" groups=\\"stock.group_stock_sign_delivery\\"/>\\n                    <widget name=\\"signature\\" string=\\"Ký tên\\" invisible=\\"not id or picking_type_code != 'outgoing' or state == 'done' or is_signed\\" full_name=\\"partner_id\\" groups=\\"stock.group_stock_sign_delivery\\"/>\\n                    <button name=\\"do_print_picking\\" string=\\"In\\" groups=\\"stock.group_stock_user\\" type=\\"object\\" invisible=\\"state != 'assigned'\\" data-hotkey=\\"o\\"/>\\n                    <button name=\\"315\\" string=\\"In\\" invisible=\\"state != 'done'\\" type=\\"action\\" groups=\\"base.group_user\\" data-hotkey=\\"o\\"/>\\n                    <button name=\\"334\\" string=\\"Trả hàng\\" invisible=\\"state != 'done'\\" type=\\"action\\" groups=\\"base.group_user\\" data-hotkey=\\"k\\"/>\\n                    <field name=\\"state\\" widget=\\"statusbar\\" invisible=\\"picking_type_code != 'incoming'\\" statusbar_visible=\\"draft,assigned,done\\"/>\\n                    <field name=\\"state\\" widget=\\"statusbar\\" invisible=\\"picking_type_code == 'incoming'\\" statusbar_visible=\\"draft,confirmed,assigned,done\\"/>\\n                    <button name=\\"action_cancel\\" invisible=\\"state not in ('assigned', 'confirmed', 'draft', 'waiting')\\" string=\\"Hủy\\" groups=\\"base.group_user\\" type=\\"object\\" confirm=\\"Bạn có chắc chắn muốn huỷ lệnh chuyển hàng này không?\\" data-hotkey=\\"x\\"/>\\n                </header>\\n                <div class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"not picking_warning_text\\">\\n                    <field name=\\"picking_warning_text\\" class=\\"fw-bold\\"/>\\n                </div>\\n                <sheet>\\n                    <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                        <button name=\\"action_see_returns\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-rotate-left\\" invisible=\\"return_count == 0\\">\\n                            <field string=\\"Trả hàng\\" name=\\"return_count\\" widget=\\"statinfo\\"/>\\n                        </button>\\n                        <button name=\\"action_see_move_scrap\\" string=\\"Loại bỏ\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"oi-arrows-v\\" invisible=\\"not has_scrap_move\\"/>\\n                        <button name=\\"action_see_packages\\" string=\\"Kiện hàng\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-cubes\\" invisible=\\"state == 'done' or not packages_count\\" groups=\\"stock.group_tracking_lot\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Packages</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_see_package_histories\\" string=\\"Kiện hàng\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-cubes\\" invisible=\\"state != 'done' or not packages_count\\" groups=\\"stock.group_tracking_lot\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Packages</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"311\\" icon=\\"oi-arrow-up\\" class=\\"oe_stat_button\\" type=\\"action\\" invisible=\\"state != 'done' or not has_tracking\\" groups=\\"stock.group_production_lot\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Khả năng truy xuất nguồn gốc</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_view_reception_report\\" type=\\"object\\" context=\\"{'default_picking_ids': [id]}\\" class=\\"oe_stat_button\\" icon=\\"fa-list\\" invisible=\\"not show_allocation\\" groups=\\"stock.group_reception_report\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Phân bổ</span>\\n                            </div>\\n                        </button>\\n                        <!-- Use the following button to avoid onchange on one2many -->\\n                        <button name=\\"action_picking_move_tree\\" class=\\"oe_stat_button\\" icon=\\"oi-arrows-v\\" type=\\"object\\" help=\\"Chế độ xem danh sách của hoạt động\\" groups=\\"base.group_no_one\\" invisible=\\"(is_locked or state == 'done') or state == 'done' and is_locked\\" context=\\"{'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref':'stock.view_move_form', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id}\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Hoạt động</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_detailed_operations\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" help=\\"Chế độ xem danh sách của hoạt động chi tiết\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Điều chuyển</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_next_transfer\\" class=\\"oe_stat_button\\" icon=\\"fa-exchange\\" type=\\"object\\" help=\\"Chế độ xem danh sách của lệnh chuyển hàng tiếp theo\\" invisible=\\"not show_next_pickings\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Lệnh chuyển hàng tiếp theo</span>\\n                            </div>\\n                        </button>\\n                    </div>\\n                    <div class=\\"oe_title\\">\\n                        <h1 class=\\"d-flex\\">\\n                            <field name=\\"priority\\" widget=\\"priority\\" class=\\"me-3\\"/>\\n                            <div invisible=\\"id\\">Mới <field name=\\"picking_type_code\\"/></div>\\n                            <field name=\\"name\\" invisible=\\"not id\\"/>\\n                        </h1>\\n                    </div>\\n                    <group>\\n                        <group>\\n                            <div class=\\"o_td_label\\">\\n                                <label for=\\"partner_id\\" string=\\"Địa chỉ giao hàng\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code != 'outgoing'\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Nhập từ\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code != 'incoming'\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Liên hệ\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code in ['incoming', 'outgoing']\\"/>\\n                            </div>\\n                            <field name=\\"partner_id\\" nolabel=\\"1\\" readonly=\\"state in ['cancel', 'done']\\" placeholder=\\"ví dụ. Lumber Inc\\"/>\\n                            <field name=\\"picking_type_id\\" options=\\"{'no_open': True}\\" readonly=\\"state in ('done', 'cancel')\\" domain=\\"[('code', 'in', ('incoming', 'outgoing', 'internal'))]\\"/>\\n                            <field name=\\"location_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_dest_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_id\\" options=\\"{'no_create': True}\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"picking_type_code == 'incoming'\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_dest_id\\" options=\\"{'no_create': True}\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"picking_type_code == 'outgoing'\\" readonly=\\"state == 'done'\\" domain=\\"[('usage','!=','view')]\\"/>\\n                            <field name=\\"backorder_id\\" invisible=\\"not backorder_id\\"/>\\n                            <field name=\\"use_create_lots\\" invisible=\\"1\\"/> <!-- used by embedded stock.move list view below -->\\n                        </group>\\n                        <group>\\n                            <label for=\\"scheduled_date\\"/>\\n                            <div class=\\"o_row\\">\\n                                <field name=\\"scheduled_date\\" readonly=\\"not is_date_editable\\" required=\\"id\\" decoration-warning=\\"state not in ('done', 'cancel') and scheduled_date &lt; now\\" decoration-danger=\\"state not in ('done', 'cancel') and scheduled_date &lt; current_date\\" decoration-bf=\\"state not in ('done', 'cancel') and (scheduled_date &lt; current_date or scheduled_date &lt; now)\\"/>\\n                                <field name=\\"json_popover\\" nolabel=\\"1\\" widget=\\"stock_rescheduling_popover\\" invisible=\\"not json_popover\\"/>\\n                            </div>\\n                            <field name=\\"date_deadline\\" invisible=\\"state in ('done', 'cancel') or not date_deadline\\" decoration-danger=\\"date_deadline and date_deadline &lt; current_date\\" decoration-bf=\\"date_deadline and date_deadline &lt; current_date\\"/>\\n                            <field name=\\"products_availability_state\\" invisible=\\"1\\"/>\\n                            <field name=\\"products_availability\\" invisible=\\"picking_type_code not in ('outgoing', 'internal') or state not in ['confirmed', 'waiting', 'assigned']\\" decoration-success=\\"state == 'assigned' or products_availability_state == 'available'\\" decoration-warning=\\"state != 'assigned' and products_availability_state in ('expected', 'available')\\" decoration-danger=\\"state != 'assigned' and products_availability_state == 'late'\\"/>\\n                            <field name=\\"date_done\\" string=\\"Ngày hiệu lực\\" invisible=\\"state != 'done'\\" readonly=\\"not is_date_editable\\"/>\\n                            <field name=\\"origin\\" placeholder=\\"VD: PO0032\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                            <field name=\\"owner_id\\" groups=\\"stock.group_tracking_owner\\" invisible=\\"picking_type_code != 'incoming'\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                        </group>\\n                    </group>\\n                    <field name=\\"picking_properties\\" columns=\\"2\\"/>\\n                    <notebook>\\n                        <page string=\\"Hoạt động\\" name=\\"operations\\">\\n                            <field name=\\"move_ids\\" mode=\\"list,kanban\\" widget=\\"stock_move_one2many\\" add-label=\\"Thêm một sản phẩm\\" readonly=\\"state == 'done' and is_locked\\" context=\\"{'default_company_id': company_id, 'default_date': scheduled_date, 'default_date_deadline': date_deadline, 'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref': 'stock.view_stock_move_operations', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_partner_id': partner_id, 'picking_state': state}\\">\\n                                <list decoration-muted=\\"scrap_id or state == 'cancel' or (state == 'done' and is_locked == True)\\" string=\\"Điều chuyển tồn kho\\" editable=\\"bottom\\">\\n                                    <control>\\n                                        <create string=\\"Thêm một sản phẩm\\"/>\\n                                    </control>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" readonly=\\"0\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_dest_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"partner_id\\" column_invisible=\\"True\\" readonly=\\"state == 'done'\\"/>\\n                                    <field name=\\"picking_code\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_details_visible\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"additional\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_lines_count\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_locked\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_storable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_tracking\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\" required=\\"1\\" readonly=\\"(state != 'draft' and not additional) or move_lines_count &gt; 0\\" force_save=\\"1\\" widget=\\"move_product_label_field\\"/>\\n                                    <field name=\\"forecast_availability\\" string=\\"\\" widget=\\"forecast_widget\\" column_invisible=\\"parent.state in ('cancel', 'done') or parent.picking_type_code not in ['internal', 'outgoing']\\"/>\\n                                    <field name=\\"packaging_uom_qty\\" optional=\\"hide\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"packaging_uom_id\\" optional=\\"hide\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"location_final_id\\" optional=\\"hide\\" groups=\\"stock.group_stock_multi_locations\\"/>\\n                                    <field name=\\"description_picking\\" string=\\"Mô tả\\" optional=\\"show\\"/>\\n                                    <field name=\\"date\\" optional=\\"hide\\"/>\\n                                    <field name=\\"date_deadline\\" optional=\\"hide\\"/>\\n                                    <field name=\\"is_quantity_done_editable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_quant\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_lots_text\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_lots_m2o\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_initial_demand_editable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"display_import_lot\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_lines_without_result_package\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"package_ids\\" optional=\\"show\\" widget=\\"package_m2m\\" groups=\\"stock.group_tracking_lot\\" width=\\"200px\\" readonly=\\"1\\"/>\\n                                    <field name=\\"product_uom_qty\\" string=\\"Nhu cầu\\" readonly=\\"not is_initial_demand_editable\\"/>\\n                                    <field name=\\"forecast_expected_date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_qty\\" readonly=\\"1\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"quantity\\" string=\\"Số lượng\\" readonly=\\"not is_quantity_done_editable\\" column_invisible=\\"parent.state=='draft'\\" decoration-danger=\\"product_uom_qty and quantity &gt; product_uom_qty and parent.state not in ['done', 'cancel']\\"/>\\n                                    <field name=\\"product_uom\\" readonly=\\"state != 'draft' and not additional\\" options=\\"{'no_open': True, 'no_create': True}\\" widget=\\"many2one_uom\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"picked\\" optional=\\"hide\\" column_invisible=\\"parent.state=='draft'\\"/>\\n                                    <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" column_invisible=\\"parent.state == 'draft'\\" groups=\\"stock.group_production_lot\\" invisible=\\"not show_details_visible or has_tracking == 'none'\\" optional=\\"hide\\" options=\\"{'create': [('parent.use_create_lots', '=', True)]}\\" context=\\"{'default_company_id': company_id, 'default_product_id': product_id, 'active_picking_id': parent.id}\\" domain=\\"[('product_id','=',product_id)]\\"/>\\n                                    <button name=\\"action_show_details\\" type=\\"object\\" string=\\"Chi tiết\\" title=\\"Chi tiết\\" invisible=\\"not show_details_visible\\"/>\\n                                </list>\\n                            </field>\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <button class=\\"btn-secondary float-end\\" name=\\"action_put_in_pack\\" type=\\"object\\" string=\\"Đóng hàng thành kiện\\" invisible=\\"state in ('draft', 'done', 'cancel')\\" groups=\\"stock.group_tracking_lot\\" data-hotkey=\\"shift+g\\"/>\\n                        </page>\\n                        <page string=\\"Thông tin bổ sung\\" name=\\"extra\\">\\n                            <group>\\n                                <group string=\\"Thông tin khác\\" name=\\"other_infos\\">\\n                                    <field name=\\"move_type\\" invisible=\\"picking_type_code == 'incoming'\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" domain=\\"[('share', '=', False)]\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" force_save=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Ghi chú\\" name=\\"note\\">\\n                            <field name=\\"note\\" string=\\"Ghi chú\\" placeholder=\\"Thêm một ghi chú nội bộ sẽ được in trên phiếu Hoạt động xuất kho\\"/>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Transfer">\n                <header>\n                    <button name="action_confirm" invisible="state != 'draft'" string="Mark as Todo" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="q"/>\n                    <button name="action_assign" invisible="not show_check_availability" string="Check Availability" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="w"/>\n                    <button name="button_validate" invisible="state in ('draft', 'confirmed', 'done', 'cancel')" string="Validate" type="object" class="oe_highlight" groups="stock.group_stock_user" data-hotkey="v"/>\n                    <button name="button_validate" invisible="state in ('waiting', 'assigned', 'done', 'cancel')" string="Validate" type="object" groups="stock.group_stock_user" class="o_btn_validate" data-hotkey="v"/>\n                    <widget name="signature" string="Sign" highlight="1" invisible="not id or picking_type_code != 'outgoing' or state != 'done' or is_signed" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>\n                    <widget name="signature" string="Sign" invisible="not id or picking_type_code != 'outgoing' or state == 'done' or is_signed" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>\n                    <button name="do_print_picking" string="Print" groups="stock.group_stock_user" type="object" invisible="state != 'assigned'" data-hotkey="o"/>\n                    <button name="315" string="Print" invisible="state != 'done'" type="action" groups="base.group_user" data-hotkey="o"/>\n                    <button name="334" string="Return" invisible="state != 'done'" type="action" groups="base.group_user" data-hotkey="k"/>\n                    <field name="state" widget="statusbar" invisible="picking_type_code != 'incoming'" statusbar_visible="draft,assigned,done"/>\n                    <field name="state" widget="statusbar" invisible="picking_type_code == 'incoming'" statusbar_visible="draft,confirmed,assigned,done"/>\n                    <button name="action_cancel" invisible="state not in ('assigned', 'confirmed', 'draft', 'waiting')" string="Cancel" groups="base.group_user" type="object" confirm="Are you sure you want to cancel this transfer?" data-hotkey="x"/>\n                </header>\n                <div class="alert alert-info" role="alert" invisible="not picking_warning_text">\n                    <field name="picking_warning_text" class="fw-bold"/>\n                </div>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <button name="action_see_returns" type="object" class="oe_stat_button" icon="fa-rotate-left" invisible="return_count == 0">\n                            <field string="Returns" name="return_count" widget="statinfo"/>\n                        </button>\n                        <button name="action_see_move_scrap" string="Scraps" type="object" class="oe_stat_button" icon="oi-arrows-v" invisible="not has_scrap_move"/>\n                        <button name="action_see_packages" string="Packages" type="object" class="oe_stat_button" icon="fa-cubes" invisible="state == 'done' or not packages_count" groups="stock.group_tracking_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Packages</span>\n                            </div>\n                        </button>\n                        <button name="action_see_package_histories" string="Packages" type="object" class="oe_stat_button" icon="fa-cubes" invisible="state != 'done' or not packages_count" groups="stock.group_tracking_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Packages</span>\n                            </div>\n                        </button>\n                        <button name="311" icon="oi-arrow-up" class="oe_stat_button" type="action" invisible="state != 'done' or not has_tracking" groups="stock.group_production_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Traceability</span>\n                            </div>\n                        </button>\n                        <button name="action_view_reception_report" type="object" context="{'default_picking_ids': [id]}" class="oe_stat_button" icon="fa-list" invisible="not show_allocation" groups="stock.group_reception_report">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Allocation</span>\n                            </div>\n                        </button>\n                        <!-- Use the following button to avoid onchange on one2many -->\n                        <button name="action_picking_move_tree" class="oe_stat_button" icon="oi-arrows-v" type="object" help="List view of operations" groups="base.group_no_one" invisible="(is_locked or state == 'done') or state == 'done' and is_locked" context="{'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref':'stock.view_move_form', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id}">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Operations</span>\n                            </div>\n                        </button>\n                        <button name="action_detailed_operations" class="oe_stat_button" icon="fa-bars" type="object" help="List view of detailed operations">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Moves</span>\n                            </div>\n                        </button>\n                        <button name="action_next_transfer" class="oe_stat_button" icon="fa-exchange" type="object" help="List view of next transfers" invisible="not show_next_pickings">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Next Transfer</span>\n                            </div>\n                        </button>\n                    </div>\n                    <div class="oe_title">\n                        <h1 class="d-flex">\n                            <field name="priority" widget="priority" class="me-3"/>\n                            <div invisible="id">New <field name="picking_type_code"/></div>\n                            <field name="name" invisible="not id"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <div class="o_td_label">\n                                <label for="partner_id" string="Delivery Address" style="font-weight:bold;" invisible="picking_type_code != 'outgoing'"/>\n                                <label for="partner_id" string="Receive From" style="font-weight:bold;" invisible="picking_type_code != 'incoming'"/>\n                                <label for="partner_id" string="Contact" style="font-weight:bold;" invisible="picking_type_code in ['incoming', 'outgoing']"/>\n                            </div>\n                            <field name="partner_id" nolabel="1" readonly="state in ['cancel', 'done']" placeholder="e.g. Lumber Inc"/>\n                            <field name="picking_type_id" options="{'no_open': True}" readonly="state in ('done', 'cancel')" domain="[('code', 'in', ('incoming', 'outgoing', 'internal'))]"/>\n                            <field name="location_id" groups="!stock.group_stock_multi_locations" invisible="1" readonly="state == 'done'"/>\n                            <field name="location_dest_id" groups="!stock.group_stock_multi_locations" invisible="1" readonly="state == 'done'"/>\n                            <field name="location_id" options="{'no_create': True}" groups="stock.group_stock_multi_locations" invisible="picking_type_code == 'incoming'" readonly="state == 'done'"/>\n                            <field name="location_dest_id" options="{'no_create': True}" groups="stock.group_stock_multi_locations" invisible="picking_type_code == 'outgoing'" readonly="state == 'done'" domain="[('usage','!=','view')]"/>\n                            <field name="backorder_id" invisible="not backorder_id"/>\n                            <field name="use_create_lots" invisible="1"/> <!-- used by embedded stock.move list view below -->\n                        </group>\n                        <group>\n                            <label for="scheduled_date"/>\n                            <div class="o_row">\n                                <field name="scheduled_date" readonly="not is_date_editable" required="id" decoration-warning="state not in ('done', 'cancel') and scheduled_date &lt; now" decoration-danger="state not in ('done', 'cancel') and scheduled_date &lt; current_date" decoration-bf="state not in ('done', 'cancel') and (scheduled_date &lt; current_date or scheduled_date &lt; now)"/>\n                                <field name="json_popover" nolabel="1" widget="stock_rescheduling_popover" invisible="not json_popover"/>\n                            </div>\n                            <field name="date_deadline" invisible="state in ('done', 'cancel') or not date_deadline" decoration-danger="date_deadline and date_deadline &lt; current_date" decoration-bf="date_deadline and date_deadline &lt; current_date"/>\n                            <field name="products_availability_state" invisible="1"/>\n                            <field name="products_availability" invisible="picking_type_code not in ('outgoing', 'internal') or state not in ['confirmed', 'waiting', 'assigned']" decoration-success="state == 'assigned' or products_availability_state == 'available'" decoration-warning="state != 'assigned' and products_availability_state in ('expected', 'available')" decoration-danger="state != 'assigned' and products_availability_state == 'late'"/>\n                            <field name="date_done" string="Effective Date" invisible="state != 'done'" readonly="not is_date_editable"/>\n                            <field name="origin" placeholder="e.g. PO0032" readonly="state in ['cancel', 'done']"/>\n                            <field name="owner_id" groups="stock.group_tracking_owner" invisible="picking_type_code != 'incoming'" readonly="state in ['cancel', 'done']"/>\n                        </group>\n                    </group>\n                    <field name="picking_properties" columns="2"/>\n                    <notebook>\n                        <page string="Operations" name="operations">\n                            <field name="move_ids" mode="list,kanban" widget="stock_move_one2many" add-label="Add a Product" readonly="state == 'done' and is_locked" context="{'default_company_id': company_id, 'default_date': scheduled_date, 'default_date_deadline': date_deadline, 'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref': 'stock.view_stock_move_operations', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_partner_id': partner_id, 'picking_state': state}">\n                                <list decoration-muted="scrap_id or state == 'cancel' or (state == 'done' and is_locked == True)" string="Stock Moves" editable="bottom">\n                                    <control>\n                                        <create string="Add a Product"/>\n                                    </control>\n                                    <field name="company_id" column_invisible="True"/>\n                                    <field name="state" readonly="0" column_invisible="True"/>\n                                    <field name="picking_type_id" column_invisible="True"/>\n                                    <field name="location_id" column_invisible="True"/>\n                                    <field name="location_dest_id" column_invisible="True"/>\n                                    <field name="partner_id" column_invisible="True" readonly="state == 'done'"/>\n                                    <field name="picking_code" column_invisible="True"/>\n                                    <field name="show_details_visible" column_invisible="True"/>\n                                    <field name="additional" column_invisible="True"/>\n                                    <field name="move_lines_count" column_invisible="True"/>\n                                    <field name="is_locked" column_invisible="True"/>\n                                    <field name="is_storable" column_invisible="True"/>\n                                    <field name="has_tracking" column_invisible="True"/>\n                                    <field name="product_id" context="{'default_is_storable': True}" required="1" readonly="(state != 'draft' and not additional) or move_lines_count &gt; 0" force_save="1" widget="move_product_label_field"/>\n                                    <field name="forecast_availability" string="" widget="forecast_widget" column_invisible="parent.state in ('cancel', 'done') or parent.picking_type_code not in ['internal', 'outgoing']"/>\n                                    <field name="packaging_uom_qty" optional="hide" groups="uom.group_uom"/>\n                                    <field name="packaging_uom_id" optional="hide" groups="uom.group_uom"/>\n                                    <field name="location_final_id" optional="hide" groups="stock.group_stock_multi_locations"/>\n                                    <field name="description_picking" string="Description" optional="show"/>\n                                    <field name="date" optional="hide"/>\n                                    <field name="date_deadline" optional="hide"/>\n                                    <field name="is_quantity_done_editable" column_invisible="True"/>\n               