odule_product_margin\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Reporting\\" id=\\"account_reports_settings\\" groups=\\"account.group_account_user\\" invisible=\\"not module_account_reports\\">\\n                            <setting string=\\"Restrictive Audit Trail\\" company_dependent=\\"1\\" invisible=\\"force_restrictive_audit_trail\\" help=\\"Log changes to posted journal entries immutably\\">\\n                                <field name=\\"restrictive_audit_trail\\"/>\\n                            </setting>\\n                        </block>\\n                        <field name=\\"is_account_peppol_eligible\\" invisible=\\"1\\"/>\\n                        <block title=\\"Storno Accounting\\" id=\\"storno\\" groups=\\"account.group_account_user\\" invisible=\\"not display_account_storno\\">\\n                            <setting id=\\"enable_storno_accounting\\" company_dependent=\\"1\\" help=\\"Use negative numbers to reverse original entries\\">\\n                                <field name=\\"account_storno\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Accounting Firms mode\\" id=\\"quick_edit_mode\\">\\n                            <div class=\\"text-muted\\">\\n                                <p style=\\"margin-bottom: 0\\">Accounting firm mode will change invoice/bill encoding:</p>\\n                                <p style=\\"margin-bottom: 0\\"> - The document's sequence becomes editable on all documents.</p>\\n                                <p style=\\"margin-bottom: 0\\"> - A new field « Total (tax inc.) » to speed up and control the encoding by automating line creation with the right account &amp; tax.</p>\\n                            </div>\\n                            <setting company_dependent=\\"1\\">\\n                                <field name=\\"quick_edit_mode\\" placeholder=\\"Disabled\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>", "vi_VN": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                    <field name=\\"country_code\\" invisible=\\"1\\" groups=\\"account.group_account_manager\\"/>\\n                    <app data-string=\\"Invoicing\\" string=\\"Hóa đơn\\" name=\\"account\\" groups=\\"account.group_account_manager\\">\\n                        <field name=\\"has_chart_of_accounts\\" invisible=\\"1\\"/>\\n                        <field name=\\"has_accounting_entries\\" invisible=\\"1\\"/>\\n                        <block title=\\"Bản địa hoá tài chính\\" name=\\"fiscal_localization_setting_container\\" invisible=\\"not is_root_company\\">\\n                            <setting string=\\"Bản địa hoá tài chính\\" company_dependent=\\"1\\" help=\\"Thuế, vị trí tài chính, hệ thống tài khoản &amp; các báo cáo luật định cho quốc gia của bạn\\" documentation=\\"/applications/finance/fiscal_localizations.html\\">\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt16\\">\\n                                        <div>\\n                                            <label for=\\"chart_template\\" string=\\"Gói\\" class=\\"col-2 o_light_label\\"/>\\n                                            <field name=\\"chart_template\\" readonly=\\"has_accounting_entries\\" required=\\"chart_template\\"/>\\n                                        </div>\\n                                        <div class=\\"mt16\\">\\n                                            <button name=\\"reload_template\\" type=\\"object\\" string=\\"Tải lại\\" class=\\"btn-secondary ps-2 w-100\\" icon=\\"fa-refresh\\" title=\\"Hãy tải lại dữ liệu kế toán (thuế, tài khoản,...) nếu bạn nhận thấy có sự mâu thuẫn. Không thể đảo ngược tác vụ này.\\" invisible=\\"not has_accounting_entries or not chart_template\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Electronic Invoicing\\" id=\\"peppol\\" invisible=\\"not is_account_peppol_eligible\\">\\n                            <div id=\\"account_peppol_install\\" class=\\"col-12 col-lg-12 o_setting_box\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_peppol\\" readonly=\\"False\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"module_account_peppol\\" string=\\"Bật PEPPOL\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Cho phép gửi và nhận hóa đơn qua mạng PEPPOL\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </block>\\n                        <block title=\\"Thuế\\" name=\\"default_taxes_setting_container\\">\\n                            <setting id=\\"default_taxes\\" string=\\"Thuế mặc định\\" company_dependent=\\"1\\" help=\\"Thuế mặc định áp dụng khi tạo sản phẩm mới.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/default_taxes.html\\">\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label string=\\"Thuế bán hàng\\" for=\\"sale_tax_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"sale_tax_id\\" domain=\\"[('type_tax_use', 'in', ('sale', 'all'))]\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Thuế mua hàng\\" for=\\"purchase_tax_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"purchase_tax_id\\" domain=\\"[('type_tax_use', 'in', ('purchase', 'all'))]\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <div class=\\"col-lg-3\\">\\n                                            <label string=\\"Giá\\" for=\\"account_price_include\\" class=\\"o_light_label\\"/>\\n                                            <div class=\\"fa fa-question-circle\\" title=\\"Cài đặt này sẽ khóa sau khi một bút toán được tạo.\\"/>\\n                                        </div>\\n                                        <field name=\\"account_price_include\\" readonly=\\"has_accounting_entries\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"rounding_method\\" company_dependent=\\"1\\" string=\\"Phương pháp làm tròn\\" help=\\"Cách tổng tiền thuế được tính trong đơn hàng hoặc hóa đơn\\" title=\\"Nên làm tròn theo từng dòng nếu giá của bạn đã bao gồm thuế. Theo cách này, tổng thành tiền của các dòng sẽ bằng tổng tiền bao gồm thuế.\\">\\n                                <field name=\\"tax_calculation_rounding_method\\" class=\\"o_light_label mt16\\" widget=\\"radio\\"/>\\n                            </setting>\\n                            <setting id=\\"eu_service\\" title=\\"Nếu bạn bán hàng hóa và dịch vụ cho khách hàng ở nước ngoài thuộc EU, bạn phải tính thuế GTGT dựa trên địa chỉ giao hàng. Quy tắc này áp dụng bất kể bạn đang ở đâu.\\" string=\\"Bán hàng từ xa trong cộng đồng EU\\" documentation=\\"/applications/finance/accounting/taxation/taxes/eu_distance_selling.html\\" help=\\"Áp dụng thuế GTGT của quốc gia EU mà hàng hóa và dịch vụ được giao đến.\\" invisible=\\"not('EU' in company_country_group_codes or company_country_code in ('CH', 'UK'))\\">\\n                                <button type=\\"object\\" name=\\"action_eu_oss_tax_mapping\\" icon=\\"fa-refresh\\" string=\\"Mapping thuế OSS\\" class=\\"btn-link\\"/>\\n                            </setting>\\n                            <setting id=\\"tax_exigibility\\" company_dependent=\\"1\\" help=\\"Cho phép cấu hình thuế bằng cơ sở dòng tiền\\" title=\\"Chọn mục này nếu thuế nên sử dụng cơ sở tiền mặt, việc này sẽ tạo ra một bút toán cho các loại thuế đó trên một tài khoản nhất định trong quá trình đối chiếu.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/cash_basis_taxes.html\\">\\n                                <field name=\\"tax_exigibility\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not tax_exigibility\\" groups=\\"account.group_account_user\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label for=\\"tax_cash_basis_journal_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"tax_cash_basis_journal_id\\"/>\\n                                    </div>\\n                                    <div class=\\"row mt16\\">\\n                                        <label for=\\"account_cash_basis_base_account_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"account_cash_basis_base_account_id\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"tax_fiscal_country_234\\" string=\\"Quốc gia tài chính\\" company_dependent=\\"1\\" help=\\"Quốc gia nội địa cho kế toán của bạn\\">\\n                                <field name=\\"account_fiscal_country_id\\" options=\\"{'no_create': True, 'no_open': True}\\"/>\\n        