ustomer_invoices/snailmail.html\\">\\n                                <field name=\\"module_snailmail_account\\"/>\\n                            </setting>\\n                            <setting id=\\"invoice_delivery_addresses\\" documentation=\\"/applications/sales/sales/send_quotations/different_addresses.html\\" help=\\"Chọn địa chỉ giao hàng và hóa đơn cụ thể\\">\\n                                <field name=\\"group_sale_delivery_address\\"/>\\n                            </setting>\\n                            <setting id=\\"smallest_coinage_currency\\" help=\\"Xác định đơn vị nhỏ nhất của loại tiền tệ được sử dụng để thanh toán bằng tiền mặt\\" documentation=\\"/applications/finance/accounting/receivables/customer_invoices/cash_rounding.html\\">\\n                                <field name=\\"group_cash_rounding\\"/>\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"293\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Làm tròn tiền\\" class=\\"btn-link\\" invisible=\\"not group_cash_rounding\\"/>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"intrastat_statistics\\" help=\\"Thu thập thông tin và tạo số liệu thống kê về thương mại hàng hóa ở châu Âu với intastat\\" documentation=\\"/applications/finance/accounting/reporting/declarations/intrastat.html\\" invisible=\\"'INTRASTAT' not in company_country_group_codes\\">\\n                                <field name=\\"module_account_intrastat\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"default_incoterm\\" string=\\"Điều khoản Incoterm mặc định\\" help=\\"Incoterm mặc định của công ty của bạn\\">\\n                                <field name=\\"incoterm_id\\"/>\\n                            </setting>\\n                            <setting id=\\"show_sale_receipts\\" help=\\"Kích hoạt để tạo