\\"/>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Thanh toán của khách hàng\\" id=\\"pay_invoice_online_setting_container\\">\\n                            <setting help=\\"Cho phép khách hàng của bạn thanh toán hóa đơn online\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/online_payment.html\\">\\n                                <field name=\\"module_account_payment\\"/>\\n                                <div class=\\"mt-3 d-flex\\" invisible=\\"not module_account_payment\\">\\n                                    <field name=\\"link_qr_code\\" string=\\"Thêm liên kết mã QR trên PDF\\"/>\\n                                    <div>\\n                                        <label for=\\"link_qr_code\\"/><br/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"account_batch_payment\\" string=\\"Thanh toán theo lô\\" help=\\"Nhóm thanh toán thành một đợt duy nhất để thuận tiện cho quá trình đối chiếu\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/batch.html\\">\\n                                <field name=\\"module_account_batch_payment\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"collect_customer_payment\\" title=\\"Nếu chọn ô này, bạn sẽ có thể thu các khoản thanh toán bằng cách sử dụng ủy quyền Ghi nợ trực tiếp SEPA.\\" string=\\"Ghi nợ trực tiếp SEPA (SDD)\\" company_dependent=\\"1\\" help=\\"Nhận các khoản thanh toán bán hàng chỉ trong một cú nhấp chuột khi dùng dịch vụ SEPA của châu Âu\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/batch_sdd.html\\" invisible=\\"'SEPA' not in company_country_group_codes\\">\\n                                <field nam