 </setting>\\n                            <setting id=\\"sepa_payments\\" title=\\"Nếu bạn đánh dấu vào ô này, bạn có thể đăng ký thanh toán của mình bằng SEPA / ISO20022.\\" company_dependent=\\"1\\" help=\\"Thanh toán hóa đơn chỉ với một cú nhấp chuột thông qua Dịch vụ Euro SEPA/ISO20022\\" documentation=\\"/applications/finance/accounting/payables/pay/sepa.html\\">\\n                                <field name=\\"module_account_iso20022\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n\\n                        <block title=\\"Số hóa\\" id=\\"account_digitalization\\">\\n                            <setting id=\\"account_ocr_settings\\" help=\\"Số hóa các chứng từ PDF hoặc đã quét của bạn bằng OCR và trí tuệ nhân tạo\\" documentation=\\"/applications/finance/accounting/payables/supplier_bills/invoice_digitization.html\\">\\n                                <field name=\\"module_account_extract\\" widget=\\"upgrade_boolean\\"/>\\n                                <div id=\\"msg_invoice_extract\\" class=\\"content-group\\" invisible=\\"not module_account_extract\\">\\n                                    <div class=\\"text-warning mt16 mb4\\">\\n                                        Lưu trang này và quay lại đây để thiết lập tính năng.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Tài khoản mặc định\\" id=\\"default_accounts\\">\\n                                <setting invisible=\\"not group_multi_currency\\" string=\\"Bút toán chênh lệch tỷ giá:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"currency_exchange_journal_id