926	16	\N	1	1	stock.inventory.conflict.form.view	stock.inventory.conflict	\N	form	stock/wizard/stock_inventory_conflict.xml	primary	{"en_US": "<form>\\n                <div>\\n                    <strong>Due to some stock moves done between your initial update of the quantity and now, the difference of quantity is not consistent anymore.</strong>\\n                </div>\\n                <div>\\n                    You can either :\\n                    <ul>\\n                        <li>Keep the <strong>Counted Quantity</strong> (the Difference will be updated)</li>\\n                        <li>Keep the <strong>Difference</strong> (the Counted Quantity will be updated to reflect the same difference as when you counted)</li>\\n                        <li>Discard and manually resolve the conflict</li>\\n                    </ul>\\n                </div>\\n                <div>\\n                    <br/>\\n                    <field name=\\"quant_ids\\" invisible=\\"1\\"/>\\n                    <field name=\\"quant_to_fix_ids\\" readonly=\\"1\\" style=\\"margin-top:10px;\\">\\n                        <list editable=\\"bottom\\" create=\\"0\\" delete=\\"0\\">\\n                            <field name=\\"id\\" column_invisible=\\"True\\"/>\\n                            <field name=\\"tracking\\" column_invisible=\\"True\\"/>\\n                            <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                            <field name=\\"product_id\\" readonly=\\"context.get('single_product', False) or id\\" column_invisible=\\"context.get('single_product', False)\\" force_save=\\"1\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"location_id\\" column_invisible=\\"context.get('hide_location', False)\\" readonly=\\"id\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"lot_id\\" groups=\\"stock.group_production_lot\\" column_invisible=\\"context.get('hide_lot', False)\\" readonly=\\"id or tracking not in ['serial', 'lot']\\" required=\\"tracking != 'none'\\" context=\\"{'default_product_id': product_id}\\"/>\\n                            <field name=\\"package_id\\" groups=\\"stock.group_tracking_lot\\" readonly=\\"id\\"/>\\n                            <field name=\\"owner_id\\" groups=\\"stock.group_tracking_owner\\" readonly=\\"id\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"quantity\\" string=\\"Quantity\\"/>\\n                            <field name=\\"inventory_quantity\\" string=\\"Counted Quantity\\" decoration-muted=\\"inventory_quantity == 0\\" readonly=\\"0\\"/>\\n                            <field name=\\"inventory_diff_quantity\\" string=\\"Difference\\" decoration-muted=\\"inventory_quantity == 0\\" decoration-danger=\\"inventory_diff_quantity &lt; 0\\" decoration-success=\\"inventory_diff_quantity &gt; 0\\" decoration-bf=\\"inventory_diff_quantity != 0\\"/>\\n                            <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                            <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" optional=\\"show\\"/>\\n                        </list>\\n                    </field>\\n                </div>\\n                <footer>\\n                    <button name=\\"action_keep_counted_quantity\\" string=\\"Keep Counted Quantity\\" type=\\"object\\" class=\\"btn-primary\\" data-hotkey=\\"q\\"/>\\n                    <button name=\\"action_keep_difference\\" string=\\"Keep Difference\\" type=\\"object\\" class=\\"btn-primary\\" data-hotkey=\\"w\\"/>\\n                    <button name=\\"cancel_button\\" string=\\"Discard\\" class=\\"btn-secondary\\" special=\\"cancel\\" data-hotkey=\\"x\\"/>\\n                </footer>\\n            </form>", "vi_VN": "<form>\\n                <div>\\n                    <strong>Do một số lần điều chuyển tồn kho được thực hiện giữa lần cập nhật số lượng ban đầu và hiện tại, chênh lệch số lượng không còn nhất quán.</strong>\\n                </div>\\n                <div>\\n                    Bạn có thể:\\n                    <ul>\\n                        <li>Giữ <strong>số lượng được đếm</strong> (Chênh lệch sẽ được cập nhật)</li>\\n                        <li>Giữ <strong>chênh lệch</strong> (Số lượng được đếm sẽ được cập nhật để phản ánh cùng mức chênh lệch khi bạn đếm)</li>\\n                        <li>Loại bỏ và xử lý các điểm không nhất quán theo cách thủ công</li>\\n                    </ul>\\n                </div>\\n                <div>\\n                    <br/>\\n                    <field name=\\"quant_ids\\" invisible=\\"1\\"/>\\n                    <field name=\\"quant_to_fix_ids\\" readonly=\\"1\\" style=\\"margin-top:10px;\\">\\n                        <list editable=\\"bottom\\" create=\\"0\\" delete=\\"0\\">\\n                            <field name=\\"id\\" column_invisible=\\"True\\"/>\\n                            <field name=\\"tracking\\" column_invisible=\\"True\\"/>\\n                            <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                            <field name=\\"product_id\\" readonly=\\"context.get('single_product', False) or id\\" column_invisible=\\"context.get('single_product', False)\\" force_save=\\"1\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"location_id\\" column_invisible=\\"context.get('hide_location', False)\\" readonly=\\"id\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"lot_id\\" groups=\\"stock.group_production_lot\\" column_invisible=\\"context.get('hide_lot', False)\\" readonly=\\"id or tracking not in ['serial', 'lot']\\" required=\\"tracking != 'none'\\" context=\\"{'default_product_id': product_id}\\"/>\\n                            <field name=\\"package_id\\" groups=\\"stock.group_tracking_lot\\" readonly=\\"id\\"/>\\n                            <field name=\\"owner_id\\" groups=\\"stock.group_tracking_owner\\" readonly=\\"id\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"quantity\\" string=\\"Số lượng\\"/>\\n                            <field name=\\"inventory_quantity\\" string=\\"Số lượng đã đếm\\" decoration-muted=\\"inventory_quantity == 0\\" readonly=\\"0\\"/>\\n                            <field name=\\"inventory_diff_quantity\\" string=\\"Chênh lệch\\" decoration-muted=\\"inventory_quantity == 0\\" decoration-danger=\\"inventory_diff_quantity &lt; 0\\" decoration-success=\\"inventory_diff_quantity &gt; 0\\" decoration-bf=\\"inventory_diff_quantity != 0\\"/>\\n                            <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" widget=\\"many2one_uom\\"/>\\n                            <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" optional=\\"show\\"/>\\n                        </list>\\n                    </field>\\n                </div>\\n                <footer>\\n                    <button name=\\"action_keep_counted_quantity\\" string=\\"Giữ số lượng được đếm\\" type=\\"object\\" class=\\"btn-primary\\" data-hotkey=\\"q\\"/>\\n                    <button name=\\"action_keep_difference\\" string=\\"Giữ chênh lệch\\" type=\\"object\\" class=\\"btn-primary\\" data-hotkey=\\"w\\"/>\\n                    <button name=\\"cancel_button\\" string=\\"Huỷ bỏ\\" class=\\"btn-secondary\\" special=\\"cancel\\" data-hotkey=\\"x\\"/>\\n                </footer>\\n            </form>"}	<?xml version="1.0"?>\n<form>\n                <div>\n                    <strong>Due to some stock moves done between your initial update of the quantity and now, the difference of quantity is not consistent anymore.</strong>\n                </div>\n                <div>\n                    You can either :\n                    <ul>\n                        <li>Keep the <strong>Counted Quantity</strong> (the Difference will be updated)</li>\n                        <li>Keep the <strong>Difference</strong> (the Counted Quantity will be updated to reflect the same difference as when you counted)</li>\n                        <li>Discard and manually resolve the conflict</li>\n                    </ul>\n                </div>\n                <div>\n                    <br/>\n                    <field name="quant_ids" invisible="1"/>\n                    <field name="quant_to_fix_ids" readonly="1" style="margin-top:10px;">\n                        <list editable="bottom" create="0" delete="0">\n                            <field name="id" column_invisible="True"/>\n                            <field name="tracking" column_invisible="True"/>\n                            <field name="company_id" column_invisible="True"/>\n                            <field name="product_id" readonly="context.get('single_product', False) or id" column_invisible="context.get('single_product', False)" force_save="1" options="{'no_create': True}"/>\n                            <field name="location_id" column_invisible="context.get('hide_location', False)" readonly="id" options="{'no_create': True}"/>\n                            <field name="lot_id" groups="stock.group_production_lot" column_invisible="context.get('hide_lot', False)" readonly="id or tracking not in ['serial', 'lot']" required="tracking != 'none'" context="{'default_product_id': product_id}"/>\n                            <field name="package_id" groups="stock.group_tracking_lot" readonly="id"/>\n                            <field name="owner_id" groups="stock.group_tracking_owner" readonly="id" options="{'no_create': True}"/>\n                            <field name="quantity" string="Quantity"/>\n                            <field name="inventory_quantity" string="Counted Quantity" decoration-muted="inventory_quantity == 0" readonly="0"/>\n                            <field name="inventory_diff_quantity" string="Difference" decoration-muted="inventory_quantity == 0" decoration-danger="inventory_diff_quantity &lt; 0" decoration-success="inventory_diff_quantity &gt; 0" decoration-bf="inventory_diff_quantity != 0"/>\n                            <field name="product_uom_id" groups="uom.group_uom" widget="many2one_uom"/>\n                            <field name="company_id" groups="base.group_multi_company" optional="show"/>\n                        </list>\n                    </field>\n                </div>\n                <footer>\n                    <button name="action_keep_counted_quantity" string="Keep Counted Quantity" type="object" class="btn-primary" data-hotkey="q"/>\n                    <button name="action_keep_difference" string="Keep Difference" type="object" class="btn-primary" data-hotkey="w"/>\n                    <button name="cancel_button" string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>\n                </footer>\n            </form>\n        	f	t	2026-10-13 11:46:51.305968	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
