           <div class=\\"mb-1 o_caps_lock_warning\\">\\n                        <label for=\\"new\\">Mật khẩu mới:</label>\\n                        <div class=\\"input-group input-group-sm mb-1\\">\\n                            <input type=\\"password\\" t-attf-class=\\"form-control {{ 'is-invalid' if get_error(errors, 'password.new1') else '' }}\\" id=\\"new\\" name=\\"new1\\" autocomplete=\\"new-password\\" required=\\"required\\"/>\\n                            <button type=\\"button\\" class=\\"btn border border-start-0 o_show_password rounded-end\\">\\n                                <i class=\\"fa fa-eye\\"/>\\n                            </button>\\n                            <div class=\\"invalid-feedback\\">\\n                                <t t-out=\\"get_error(errors, 'password.new1')\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                    <div class=\\"mb-3\\">\\n                        <label for=\\"new2\\">Xác nhận mật khẩu mới:</label>\\n                        <div class=\\"input-group input-group-sm\\">\\n                            <input type=\\"password\\" t-attf-class=\\"form-control {{ 'is-invalid' if get_error(errors, 'password.new2') else '' }}\\" id=\\"new2\\" name=\\"new2\\" autocomplete=\\"new-password\\" required=\\"required\\"/>\\n                            <button type=\\"button\\" class=\\"btn border border-start-0 o_show_password rounded-end\\">\\n                                <i class=\\"fa fa-eye\\"/>\\n                            </button>\\n                            <div class=\\"invalid-feedback\\">\\n                                <t t-out=\\"get_error(errors, 'password.new2')\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                    <button type=\\"submit\\" class=\\"btn btn-light\\">Thay đổi Mật khẩu</button>\\n                </form>\\n            </section>\\n            <section name=\\"portal_revoke_all_devices_popup\\">\\n            <h4>Thu hồi tất cả các phiên</h4>\\n                <t t-set=\\"path\\"/>\\n                    <button type=\\"button\\" class=\\"btn btn-light\\" id=\\"portal_revoke_all_sessions_popup\\">\\n                        Đăng xuất khỏi tất cả thiết bị\\n                    </button>\\n            </section>\\n            <section t-if=\\"debug and allow_api_keys\\">\\n                <h4>\\n                Khoá API của nhà phát triển\\n                    <a href=\\"https://www.odoo.com/documentation/latest/developer/reference/external_api.html#api-key\\" target=\\"_blank\\">\\n                        <i title=\\"Tài liệu\\" class=\\"fa fa-fw o_button_icon fa-info-circle\\"/>\\n                    </a>\\n                </h4>\\n                <div>\\n                    <table class=\\"table o_main_table\\">\\n                        <thead>\\n                            <tr>\\n                                <th>Mô tả</th>\\n                                <th>Phạm vi</th>\\n                                <th>Đã thêm vào</th>\\n                                <th>Ngày hết hạn</th>\\n                                <th/>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                            <t t-foreach=\\"request.env.user.api_key_ids\\" t-as=\\"key\\">\\n                                <tr>\\n                                    <td><span t-field=\\"key.name\\"/></td>\\n                                    <td><span t-field=\\"key.scope\\"/></td>\\n                                    <td><span t-field=\\"key.create_date\\"/></td>\\n                                    <td><span t-field=\\"key.expiration_date\\"/></td>\\n                                    <td>\\n                                        <i class=\\"fa fa-trash text-danger o_portal_remove_api_key\\" type=\\"button\\" t-att-id=\\"key.id\\"/>\\n                                    </td>\\n                                </tr>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                </div>\\n                <div>\\n                    <button type=\\"submit\\" class=\\"btn btn-light o_portal_new_api_key\\">Khóa API mới</button>\\n                </div>\\n            </section>\\n            <section name=\\"portal_deactivate_account\\" groups=\\"base.group_portal\\">\\n                <h4>Xoá tài khoản</h4>\\n                <t t-set=\\"deactivate_error\\" t-value=\\"get_error(errors, 'deactivate')\\"/>\\n                <button class=\\"btn btn-light\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#portal_deactivate_account_modal\\">\\n                    Xoá tài khoản\\n                </button>\\n                <div t-attf-class=\\"modal #{'show d-block' if open_deactivate_modal else ''}\\" id=\\"portal_deactivate_account_modal\\" tabindex=\\"-1\\" role=\\"dialog\\">\\n                    <div class=\\"modal-dialog\\" role=\\"document\\">\\n                        <div class=\\"modal-content\\">\\n                            <div class=\\"modal-header bg-danger\\">\\n                                <h5 class=\\"modal-title\\">Bạn có chắc chắn muốn thực hiện việc này không?</h5>\\n                                <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"modal\\"/>\\n                            </div>\\n                            <form action=\\"/my/deactivate_account\\" method=\\"post\\" class=\\"modal-body\\" id=\\"portal_deactivate_account_form\\">\\n                                <div>\\n                                    <div class=\\"alert alert-danger\\" t-esc=\\"get_error(errors, 'deactivate.other')\\"/>\\n                                    <p class=\\"text-muted\\">\\n                                        Vô hiệu hóa tài khoản của bạn để ngăn chặn mọi hoạt động đăng nhập tiếp theo.<br/>\\n                                        <b>\\n                                            <i class=\\"fa fa-exclamation-triangle text-danger\\"/>\\n                                            Bạn không thể hoàn tác hành động này.\\n                                        </b>\\n                                    </p>\\n                                    <hr/>\\n                                    <p>1. Nhập mật khẩu của bạn để xác thực bạn sở hữu tài khoản này</p>\\n                                    <input name=\\"password\\" type=\\"password\\" required=\\"1\\" t-attf-class=\\"form-control #{'is-invalid' if deactivate_error == 'password' else ''}\\" placeholder=\\"Mật khẩu\\"/>\\n                                    <div t-if=\\"deactivate_error == 'password'\\" class=\\"invalid-feedback\\">\\n                                        Sai mật khẩu.\\n                                    </div>\\n                                    <hr/>\\n                                    <p>\\n                                        2. Xác nhận bạn muốn xoá tài khoản của mình bằng cách\\n                                        sao chép tên đăng nhập của bạn (<t t-esc=\\"env.user.login\\"/>).\\n                                    </p>\\n                                    <input name=\\"validation\\" type=\\"text\\" required=\\"1\\" t-attf-class=\\"form-control #{'is-invalid' if deactivate_error == 'validation' else ''}\\"/>\\n                                    <div t-if=\\"deactivate_error == 'validation'\\" class=\\"invalid-feedback\\">\\n                                        Bạn nên nhập \\"<t t-esc=\\"env.user.login\\"/>\\" để xác thực hành động của bạn.\\n                                    </div>\\n                                    <div class=\\"d-flex flex-row align-items-center\\">\\n                                        <input type=\\"checkbox\\" name=\\"request_blacklist\\" id=\\"request_blacklist\\" checked=\\"1\\"/>\\n                                        <label for=\\"request_blacklist\\" class=\\"ms-2 mw-100 fw-normal mt-3\\">\\n                                            Thêm email và số điện thoại của tôi vào danh sách chặn để chắc chắn rằng tôi không được liên hệ nữa\\n                                        </label>\\n                                    </div>\\n                                </div>\\n                                <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                            </form>\\n                            <div class=\\"modal-footer justify-content-start\\">\\n                                <input type=\\"submit\\" class=\\"btn btn-danger\\" form=\\"portal_deactivate_account_form\\" value=\\"Delete Account\\"/>\\n                                <button type=\\"button\\" class=\\"btn\\" data-bs-dismiss=\\"modal\\">\\n                                    Hủy\\n                                </button>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n            </section>\\n        </div></t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="portal.portal_my_security">\n        <t t-call="portal.portal_layout"><div class="o_portal_security_body w-md-75 w-lg-50 pb-5">\n            <t t-set="additional_title">Security</t>\n            <t t-set="no_breadcrumbs" t-value="1"/>\n            <div class="alert alert-danger" role="alert" t-if="get_error(errors)">\n                <t t-esc="errors"/>\n            </div>\n            <div class="d-flex gap-2 my-3">\n                <a href="/my/" title="Go Back" class="btn btn-light px-2"><i class="oi oi-chevron-left"/></a>\n                <h3 class="my-0">Connection &amp; Security</h3>\n            </div>\n            <section name="portal_change_password">\n                <h4>Change Password</h4>\n                <t t-set="path">password</t>\n                <div class="alert alert-success" role="alert" t-if="success and success.get('password')">\n                    Password Updated!\n                </div>\n                <div class="alert alert-danger" role="alert" t-if="get_error(errors, 'password')">\n                    <t t-esc="errors['password']"/>\n                </div>\n                <form action="/my/security" method="post" class="oe_reset_password_form">\n                    <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n                    <input type="hidden" name="op" value="password"/>\n                    <div class="mb-4">\n                        <label for="current">Password:</label>\n                        <div class="input-group input-group-sm">\n                            <input type="password" t-attf-class="form-control {{ 'is-invalid' if get_error(errors, 'password.old') else '' }}" id="current" name="old" autocomplete="current-password" required="required"/>\n                            <button class="btn border border-start-0 o_show_password rounded-end" type="button">\n                                <i class="fa fa-eye"/>\n                            </button>\n                            <div class="invalid-feedback">\n                                <t t-out="get_error(errors, 'password.old')"/>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="mb-1 o_caps_lock_warning">\n                        <label for="new">New Password:</label>\n                        <div class="input-group input-group-sm mb-1">\n                            <input type="password" t-attf-class="form-control {{ 'is-invalid' if get_error(errors, 'password.new1') else '' }}" id="new" name="new1" autocomplete="new-password" required="required"/>\n                            <button type="button" class="btn border border-start-0 o_show_password rounded-end">\n                                <i class="fa fa-eye"/>\n                            </button>\n                            <div class="invalid-feedback">\n                                <t t-out="get_error(errors, 'password.new1')"/>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="mb-3">\n                        <label for="new2">Verify New Password:</label>\n                        <div class="input-group input-group-sm">\n                            <input type="password" t-attf-class="form-control {{ 'is-invalid' if get_error(errors, 'password.new2') else '' }}" id="new2" name="new2" autocomplete="new-password" required="required"/>\n                            <button type="button" class="btn border border-start-0 o_show_password rounded-end">\n                                <i class="fa fa-eye"/>\n                            </button>\n                            <div class="invalid-feedback">\n                                <t t-out="get_error(errors, 'password.new2')"/>\n                            </div>\n                        </div>\n                    </div>\n                    <button type="submit" class="btn btn-light">Change Password</button>\n                </form>\n            </section>\n            <section name="portal_revoke_all_devices_popup">\n            <h4>Revoke All Sessions</h4>\n                <t t-set="path"/>\n                    <button type="button" class="btn btn-light" id="portal_revoke_all_sessions_popup">\n                        Log out from all devices\n                    </button>\n            </section>\n            <section t-if="debug and allow_api_keys">\n                <h4>\n                Developer API Keys\n                    <a href="https://www.odoo.com/documentation/latest/developer/reference/external_api.html#api-key" target="_blank">\n                        <i title="Documentation" class="fa fa-fw o_button_icon fa-info-circle"/>\n                    </a>\n                </h4>\n                <div>\n                    <table class="table o_main_table">\n                        <thead>\n                            <tr>\n                                <th>Description</th>\n                                <th>Scope</th>\n                                <th>Added On</th>\n                                <th>Expiration Date</th>\n                                <th/>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-foreach="request.env.user.api_key_ids" t-as="key">\n                                <tr>\n                                    <td><span t-field="key.name"/></td>\n                                    <td><span t-field="key.scope"/></td>\n                                    <td><span t-field="key.create_date"/></td>\n                                    <td><span t-field="key.expiration_date"/></td>\n                                    <td>\n                                        <i class="fa fa-trash text-danger o_portal_remove_api_key" type="button" t-att-id="key.id"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n                <div>\n                    <button type="submit" class="btn btn-light o_portal_new_api_key">New API Key</button>\n                </div>\n            </section>\n            <section name="portal_deactivate_account" groups="base.group_portal">\n                <h4>Delete Account</h4>\n                <t t-set="deactivate_error" t-value="get_error(errors, 'deactivate')"/>\n                <button class="btn btn-light" data-bs-toggle="modal" data-bs-target="#portal_deactivate_account_modal">\n                    Delete Account\n                </button>\n                <div t-attf-class="modal #{'show d-block' if open_deactivate_modal else ''}" id="portal_deactivate_account_modal" tabindex="-1" role="dialog">\n                    <div class="modal-dialog" role="document">\n                        <div class="modal-content">\n                            <div class="modal-header bg-danger">\n                                <h5 class="modal-title">Are you sure you want to do this?</h5>\n                                <button type="button" class="btn-close" data-bs-dismiss="modal"/>\n                            </div>\n                            <form action="/my/deactivate_account" method="post" class="modal-body" id="portal_deactivate_account_form">\n                                <div>\n                                    <div class="alert alert-danger" t-esc="get_error(errors, 'deactivate.other')"/>\n                                    <p class="text-muted">\n                                        Disable your account, preventing any further login.<br/>\n                                        <b>\n                                            <i class="fa fa-exclamation-triangle text-danger"/>\n                                            This action cannot be undone.\n                                        </b>\n                                    </p>\n                                    <hr/>\n                                    <p>1. Enter your password to confirm you own this account</p>\n                                    <input name="password" type="password" required="1" t-attf-class="form-control #{'is-invalid' if deactivate_error == 'password' else ''}" placeholder="Password"/>\n                                    <div t-if="deactivate_error == 'password'" class="invalid-feedback">\n                                        Wrong password.\n                                    </div>\n                                    <hr/>\n                                    <p>\n                                        2. Confirm you want to delete your account by\n                                        copying down your login (<t t-esc="env.user.login"/>).\n                                    </p>\n                                    <input name="validation" type="text" required="1" t-attf-class="form-control #{'is-invalid' if deactivate_error == 'validation' else ''}"/>\n                                    <div t-if="deactivate_error == 'validation'" class="invalid-feedback">\n                                        You should enter "<t t-esc="env.user.login"/>" to validate your action.\n                                    </div>\n                                    <div class="d-flex flex-row align-items-center">\n                                        <input type="checkbox" name="request_blacklist" id="request_blacklist" checked="1"/>\n                                        <label for="request_blacklist" class="ms-2 mw-100 fw-normal mt-3">\n                                            Put my email and phone in a block list to make sure I'm never contacted again\n                                        </label>\n                                    </div>\n                                </div>\n                                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n                            </form>\n                            <div class="modal-footer justify-content-start">\n                                <input type="submit" class="btn btn-danger" form="portal_deactivate_account_form" value="Delete Account"/>\n                                <button type="button" class="btn" data-bs-dismiss="modal">\n                                    Cancel\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n        </div></t>\n    </t>\n\n    	f	t	2026-10-13 11:46:44.801786	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
658	16	\N	1	1	Payment Form	\N	payment.form	qweb	payment/views/payment_form_templates.xml	primary	{"en_US": "<t name=\\"Payment Form\\" t-name=\\"payment.form\\">\\n        <!-- Form customization parameters:\\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\\n                                     (through the `assign_token_route` parameter); default: `True`.\\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\\n                                           shown; used only in `payment` mode.\\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\\n        -->\\n        <!-- Payment context:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\\n                                    recordset.\\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\\n            - transaction_route: The route to call to create the transaction.\\n            - assign_token_route: The route to call to assign a new or existing token to a record.\\n            - landing_route: The route the user is redirected to after payment.\\n            - access_token: The access token used to authenticate the partner.\\n        -->\\n        <t t-set=\\"mode\\" t-value=\\"mode or 'payment'\\"/>\\n        <t t-set=\\"allow_token_selection\\" t-value=\\"True if allow_token_selection is None else allow_token_selection\\"/>\\n        <t t-set=\\"allow_token_deletion\\" t-value=\\"allow_token_deletion or False\\"/>\\n        <t t-set=\\"selected_token_id\\" t-value=\\"allow_token_selection and (default_token_id or tokens_sudo[:1].id)\\"/>\\n        <t t-set=\\"selected_method_id\\" t-value=\\"not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id\\"/>\\n        <t t-set=\\"collapse_payment_methods\\" t-value=\\"tokens_sudo and allow_token_selection and payment_methods_sudo\\"/>\\n        <t t-set=\\"display_submit_button\\" t-value=\\"True if display_submit_button is None else display_submit_button\\"/>\\n        <t t-set=\\"pay_label\\">Pay</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"save_label\\">Save</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"submit_button_label\\" t-value=\\"submit_button_label or (pay_label if mode == 'payment' else save_label)\\"/>\\n        <form t-if=\\"payment_methods_sudo or tokens_sudo\\" id=\\"o_payment_form\\" class=\\"o_payment_form\\" t-att-data-mode=\\"mode\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-assign-token-route=\\"assign_token_route\\" t-att-data-landing-route=\\"landing_route\\" t-att-data-access-token=\\"access_token\\">\\n            <div id=\\"o_payment_form_options\\" class=\\"d-flex flex-column gap-3\\">\\n                <!-- === Payment tokens === -->\\n                <div t-if=\\"tokens_sudo\\">\\n                    <!-- === Header === -->\\n                    <h4 id=\\"o_payment_tokens_heading\\">\\n                        Your payment methods\\n                    </h4>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"tokens_sudo\\" t-as=\\"token_sudo\\">\\n                            <li name=\\"o_payment_option\\" t-att-class=\\"'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')\\">\\n                                <t t-call=\\"payment.token_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"token_sudo.id == selected_token_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n                <!-- === Payment methods === -->\\n                <div t-if=\\"payment_methods_sudo\\" id=\\"o_payment_methods\\" t-att-class=\\"'collapse' if collapse_payment_methods else ''\\">\\n                    <!-- === Header === -->\\n                    <p t-attf-class=\\"mb-3 {{collapse_payment_methods and 'h5' or 'h4'}}\\">\\n                        <t t-if=\\"not collapse_payment_methods\\">Payment method</t>\\n                        <t t-else=\\"\\">Other payment methods</t>\\n                        <t t-call=\\"payment.availability_report_button\\"/>\\n                    </p>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"payment_methods_sudo\\" t-as=\\"pm_sudo\\">\\n                            <li name=\\"o_payment_option\\" class=\\"list-group-item d-flex flex-column gap-2 py-3 o_outline\\">\\n                                <t t-call=\\"payment.method_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"pm_sudo.id == selected_method_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n            </div>\\n            <div class=\\"d-flex justify-content-end flex-column flex-md-row gap-2 my-2\\">\\n                <!-- === Expand payment methods button === -->\\n                <button t-if=\\"collapse_payment_methods\\" name=\\"o_payment_expand_button\\" type=\\"button\\" href=\\"#o_payment_methods\\" class=\\"btn btn-link\\" data-bs-toggle=\\"collapse\\">\\n                    Choose another method <i class=\\"oi oi-arrow-down\\"/>\\n                </button>\\n                <!-- === Submit button === -->\\n                <t t-if=\\"display_submit_button\\" t-call=\\"payment.submit_button\\"/>\\n            </div>\\n            <!-- === Availability report === -->\\n            <t t-call=\\"payment.availability_report\\"/>\\n        </form>\\n        <t t-else=\\"\\" t-call=\\"payment.no_pms_available_warning\\"/>\\n    </t>", "vi_VN": "<t name=\\"Payment Form\\" t-name=\\"payment.form\\">\\n        <!-- Form customization parameters:\\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\\n                                     (through the `assign_token_route` parameter); default: `True`.\\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\\n                                           shown; used only in `payment` mode.\\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\\n        -->\\n        <!-- Payment context:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\\n                                    recordset.\\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\\n            - transaction_route: The route to call to create the transaction.\\n            - assign_token_route: The route to call to assign a new or existing token to a record.\\n            - landing_route: The route the user is redirected to after payment.\\n            - access_token: The access token used to authenticate the partner.\\n        -->\\n        <t t-set=\\"mode\\" t-value=\\"mode or 'payment'\\"/>\\n        <t t-set=\\"allow_token_selection\\" t-value=\\"True if allow_token_selection is None else allow_token_selection\\"/>\\n        <t t-set=\\"allow_token_deletion\\" t-value=\\"allow_token_deletion or False\\"/>\\n        <t t-set=\\"selected_token_id\\" t-value=\\"allow_token_selection and (default_token_id or tokens_sudo[:1].id)\\"/>\\n        <t t-set=\\"selected_method_id\\" t-value=\\"not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id\\"/>\\n        <t t-set=\\"collapse_payment_methods\\" t-value=\\"tokens_sudo and allow_token_selection and payment_methods_sudo\\"/>\\n        <t t-set=\\"display_submit_button\\" t-value=\\"True if display_submit_button is None else display_submit_button\\"/>\\n        <t t-set=\\"pay_label\\">Thanh toán</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"save_label\\">Lưu</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"submit_button_label\\" t-value=\\"submit_button_label or (pay_label if mode == 'payment' else save_label)\\"/>\\n        <form t-if=\\"payment_methods_sudo or tokens_sudo\\" id=\\"o_payment_form\\" class=\\"o_payment_form\\" t-att-data-mode=\\"mode\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-assign-token-route=\\"assign_token_route\\" t-att-data-landing-route=\\"landing_route\\" t-att-data-access-token=\\"access_token\\">\\n            <div id=\\"o_payment_form_options\\" class=\\"d-flex flex-column gap-3\\">\\n                <!-- === Payment tokens === -->\\n                <div t-if=\\"tokens_sudo\\">\\n                    <!-- === Header === -->\\n                    <h4 id=\\"o_payment_tokens_heading\\">\\n                        Phương thức thanh toán của bạn\\n                    </h4>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"tokens_sudo\\" t-as=\\"token_sudo\\">\\n                            <li name=\\"o_payment_option\\" t-att-class=\\"'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')\\">\\n                                <t t-call=\\"payment.token_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"token_sudo.id == selected_token_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n                <!-- === Payment methods === -->\\n                <div t-if=\\"payment_methods_sudo\\" id=\\"o_payment_methods\\" t-att-class=\\"'collapse' if collapse_payment_methods else ''\\">\\n                    <!-- === Header === -->\\n                    <p t-attf-class=\\"mb-3 {{collapse_payment_methods and 'h5' or 'h4'}}\\">\\n                        <t t-if=\\"not collapse_payment_methods\\">Phương thức thanh toán</t>\\n                        <t t-else=\\"\\">Phương thức thanh toán khác</t>\\n                        <t t-call=\\"payment.availability_report_button\\"/>\\n                    </p>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"payment_methods_sudo\\" t-as=\\"pm_sudo\\">\\n                            <li name=\\"o_payment_option\\" class=\\"list-group-item d-flex flex-column gap-2 py-3 o_outline\\">\\n                                <t t-call=\\"payment.method_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"pm_sudo.id == selected_method_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n            </div>\\n            <div class=\\"d-flex justify-content-end flex-column flex-md-row gap-2 my-2\\">\\n                <!-- === Expand payment methods button === -->\\n                <button t-if=\\"collapse_payment_methods\\" name=\\"o_payment_expand_button\\" type=\\"button\\" href=\\"#o_payment_methods\\" class=\\"btn btn-link\\" data-bs-toggle=\\"collapse\\">\\n                    Chọn phương thức khác <i class=\\"oi oi-arrow-down\\"/>\\n                </button>\\n                <!-- === Submit button === -->\\n                <t t-if=\\"display_submit_button\\" t-call=\\"payment.submit_button\\"/>\\n            </div>\\n            <!-- === Availability report === -->\\n            <t t-call=\\"payment.availability_report\\"/>\\n        </form>\\n        <t t-else=\\"\\" t-call=\\"payment.no_pms_available_warning\\"/>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Payment Form" t-name="payment.form">\n        <!-- Form customization parameters:\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\n                                     (through the `assign_token_route` parameter); default: `True`.\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\n                                           shown; used only in `payment` mode.\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\n        -->\n        <!-- Payment context:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\n                                    recordset.\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\n            - transaction_route: The route to call to create the transaction.\n            - assign_token_route: The route to call to assign a new or existing token to a record.\n            - landing_route: The route the user is redirected to after payment.\n            - access_token: The access token used to authenticate the partner.\n        -->\n        <t t-set="mode" t-value="mode or 'payment'"/>\n        <t t-set="allow_token_selection" t-value="True if allow_token_selection is None else allow_token_selection"/>\n        <t t-set="allow_token_deletion" t-value="allow_token_deletion or False"/>\n        <t t-set="selected_token_id" t-value="allow_token_selection and (default_token_id or tokens_sudo[:1].id)"/>\n        <t t-set="selected_method_id" t-value="not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id"/>\n        <t t-set="collapse_payment_methods" t-value="tokens_sudo and allow_token_selection and payment_methods_sudo"/>\n        <t t-set="display_submit_button" t-value="True if display_submit_button is None else display_submit_button"/>\n        <t t-set="pay_label">Pay</t> <!-- Allow translating the label. -->\n        <t t-set="save_label">Save</t> <!-- Allow translating the label. -->\n        <t t-set="submit_button_label" t-value="submit_button_label or (pay_label if mode == 'payment' else save_label)"/>\n        <form t-if="payment_methods_sudo or tokens_sudo" id="o_payment_form" class="o_payment_form" t-att-data-mode="mode" t-att-data-reference-prefix="reference_prefix" t-att-data-amount="amount" t-att-data-currency-id="currency and currency.id" t-att-data-partner-id="partner_id" t-att-data-transaction-route="transaction_route" t-att-data-assign-token-route="assign_token_route" t-att-data-landing-route="landing_route" t-att-data-access-token="access_token">\n            <div id="o_payment_form_options" class="d-flex flex-column gap-3">\n                <!-- === Payment tokens === -->\n                <div t-if="tokens_sudo">\n                    <!-- === Header === -->\n                    <h4 id="o_payment_tokens_heading">\n                        Your payment methods\n                    </h4>\n                    <!-- === Body === -->\n                    <ul class="list-group">\n                        <t t-foreach="tokens_sudo" t-as="token_sudo">\n                            <li name="o_payment_option" t-att-class="'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')">\n                                <t t-call="payment.token_form">\n                                    <t t-set="is_selected" t-value="token_sudo.id == selected_token_id"/>\n                                </t>\n                            </li>\n                        </t>\n                    </ul>\n                </div>\n                <!-- === Payment methods === -->\n                <div t-if="payment_methods_sudo" id="o_payment_methods" t-att-class="'collapse' if collapse_payment_methods else ''">\n                    <!-- === Header === -->\n                    <p t-attf-class="mb-3 {{collapse_payment_methods and 'h5' or 'h4'}}">\n                        <t t-if="not collapse_payment_methods">Payment method</t>\n                        <t t-else="">Other payment methods</t>\n                        <t t-call="payment.availability_report_button"/>\n                    </p>\n                    <!-- === Body === -->\n                    <ul class="list-group">\n                        <t t-foreach="payment_methods_sudo" t-as="pm_sudo">\n                            <li name="o_payment_option" class="list-group-item d-flex flex-column gap-2 py-3 o_outline">\n                                <t t-call="payment.method_form">\n                                    <t t-set="is_selected" t-value="pm_sudo.id == selected_method_id"/>\n                                </t>\n                            </li>\n                        </t>\n                    </ul>\n                </div>\n            </div>\n            <div class="d-flex justify-content-end flex-column flex-md-row gap-2 my-2">\n                <!-- === Expand payment methods button === -->\n                <button t-if="collapse_payment_methods" name="o_payment_expand_button" type="button" href="#o_payment_methods" class="btn btn-link" data-bs-toggle="collapse">\n                    Choose another method <i class="oi oi-arrow-down"/>\n                </button>\n                <!-- === Submit button === -->\n                <t t-if="display_submit_button" t-call="payment.submit_button"/>\n            </div>\n            <!-- === Availability report === -->\n            <t t-call="payment.availability_report"/>\n        </form>\n        <t t-else="" t-call="payment.no_pms_available_warning"/>\n    </t>\n\n    	f	t	2026-10-13 11:46:45.457521	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
