704	16	\N	1	1	account.payment.form	account.payment	\N	form	account/views/account_payment_view.xml	primary	{"en_US": "<form string=\\"Pay\\">\\n                    <header>\\n                        <button name=\\"action_post\\" string=\\"Confirm\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"state != 'draft'\\" data-hotkey=\\"q\\"/>\\n                        <button name=\\"action_validate\\" string=\\"Validate\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"state != 'in_process' or move_id\\" data-hotkey=\\"q\\"/>\\n                        <button name=\\"action_reject\\" string=\\"Reject\\" type=\\"object\\" invisible=\\"state != 'in_process' or not is_sent\\" data-hotkey=\\"q\\"/>\\n                        <button name=\\"action_draft\\" string=\\"Reset to Draft\\" type=\\"object\\" class=\\"btn btn-secondary\\" invisible=\\"state in ('draft')\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"w\\"/>\\n                        <button string=\\"Request Cancel\\" name=\\"button_request_cancel\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"state != 'in_process' or not move_id or not need_cancel_request\\" data-hotkey=\\"w\\"/>\\n                        <button name=\\"mark_as_sent\\" string=\\"Mark as Sent\\" type=\\"object\\" data-hotkey=\\"v\\" invisible=\\"state != 'in_process' or is_sent or payment_method_code != 'manual'\\"/>\\n                        <button name=\\"unmark_as_sent\\" string=\\"Unmark as Sent\\" type=\\"object\\" data-hotkey=\\"k\\" invisible=\\"state != 'in_process' or not is_sent or payment_method_code != 'manual'\\"/>\\n                        <button name=\\"action_cancel\\" string=\\"Cancel\\" type=\\"object\\" invisible=\\"not id or not (state == 'draft' or (state == 'in_process' and is_sent))\\" data-hotkey=\\"x\\"/>\\n                        <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,in_process,paid\\"/>\\n                    </header>\\n     