e\\" string=\\"Text Confirmation\\">\\n                                <field name=\\"stock_text_confirmation\\"/>\\n                                <field name=\\"module_stock_sms\\" invisible=\\"1\\"/>\\n                                <div class=\\"content-group\\" id=\\"module_install_warning\\" invisible=\\"not stock_text_confirmation\\">\\n                                    <field name=\\"stock_confirmation_type\\" required=\\"stock_text_confirmation\\"/>\\n                                    <div class=\\"mt16 text-warning\\" id=\\"module_install_warning_sms\\" invisible=\\"stock_confirmation_type != 'sms'\\">\\n                                        <strong>Save</strong> this page and come back here to set up the feature.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"signature_delivery_orders\\" help=\\"Require a signature on your delivery orders\\">\\n                                <field name=\\"group_stock_sign_delivery\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Shipping Connectors\\" name=\\"shipping_connectors_setting_container\\">\\n                            <setting id=\\"compute_shipping_costs_ups\\" help=\\"Compute shipping costs and ship with UPS\\">\\n                                <div class=\\"o_form_label\\">UPS Connector</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentation\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with UPS<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                <