t-2\\" invisible=\\"not module_quality_control\\">\\n                                    <field name=\\"module_quality_control_worksheet\\" widget=\\"upgrade_boolean\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    <div class=\\"col ps-0\\">\\n                                        <label for=\\"module_quality_control_worksheet\\"/>\\n                                        <div class=\\"text-muted\\">\\n                                            Tạo bảng công tác tùy chỉnh cho kiểm tra chất lượng\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"annual_inventory_date\\" groups=\\"stock.group_stock_manager\\" string=\\"Ngày và tháng kiểm kho hàng năm\\" help=\\"Ngày và tháng mà việc kiểm đếm hàng tồn kho hàng năm sẽ diễn ra.\\">\\n                                <div class=\\"content-group\\">\\n                                    <field name=\\"annual_inventory_day\\" class=\\"o_light_label\\" style=\\"width: 30px;\\"/>\\n                                    <field name=\\"annual_inventory_month\\" class=\\"o_light_label\\"/>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"reception_report\\" help=\\"Xem và phân bổ số lượng đã nhận.\\">\\n                                <field name=\\"group_stock_reception_report\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Mã vạch\\" name=\\"barcode_setting_container\\">\\n                            <setting id=\\"process_operations_barcodes\\" help=\\"Xử lý các hoạt động nhanh hơn với mã vạch\\" company_dependent=\\"1\\" documentation=\\"/applications/inventory_and_mrp/inventory/barcode/setup/software.html\\">\\n                                <field name=\\"module_stock_barcode\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"process_stock_barcodelookup\\" string=\\"Cơ sở dữ liệu mã vạch tồn kho\\" help=\\"\\" documentation=\\"https://www.barcodelookup.com/api-documentation\\">\\n                                <field name=\\"module_stock_barcode_barcodelookup\\" placeholder=\\"VD: d7vctmiv2rwgenebha8bxq7irooudn\\"/>\\n                                <span class=\\"text-muted\\">\\n                                    Tạo sản phẩm dễ dàng bằng cách quét bằng <a href=\\"https://www.barcodelookup.com\\" target=\\"_blank\\">barcodelookup.com</a> trong mã vạch.\\n                                </span>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Vận chuyển\\" name=\\"shipping_setting_container\\">\\n                            <setting id=\\"delivery\\" help=\\"Tính chi phí giao hàng\\" title=\\"Đơn vị vận chuyển cho phép tính toán chi phí giao hàng, in phiếu giao hàng và yêu cầu đơn vị vận chuyển lấy hàng từ kho hàng của bạn để giao cho khách hàng. Chọn liên kết vận chuyển từ phương thức giao hàng.\\">\\n                                <field name=\\"module_delivery\\"/>\\n                            </setting>\\n                            <setting id=\\"stock_fleet\\" help=\\"Quản lý vận chuyển: sắp xếp các kiện hàng trong đội xe hoặc đơn vị vận chuyển.\\">\\n                                <field name=\\"module_stock_fleet\\"/>\\n                            </setting>\\n                            <setting id=\\"stock_move_email\\" company_dependent=\\"1\\" string=\\"Email xác nhận\\" help=\\"Tự động gửi một email xác nhận khi Lệnh giao hàng hoàn tất\\">\\n                                <field name=\\"stock_move_email_validation\\"/>\\n                            </setting>\\n                            <setting id=\\"stock_text_confirmation\\" company_dependent=\\"1\\" help=\\"Send an automatic confirmation Text Message when Delivery Orders are done\\" string=\\"Text Confirmation\\">\\n                                <field name=\\"stock_text_confirmation\\"/>\\n                                <field name=\\"module_stock_sms\\" invisible=\\"1\\"/>\\n                                <div class=\\"content-group\\" id=\\"module_install_warning\\" invisible=\\"not stock_text_confirmation\\">\\n                                    <field name=\\"stock_confirmation_type\\" required=\\"stock_text_confirmation\\"/>\\n                                    <div class=\\"mt16 text-warning\\" id=\\"module_install_warning_sms\\" invisible=\\"stock_confirmation_type != 'sms'\\">\\n                                        <strong>Lưu</strong> trang này và quay lại đây để cài đặt tính năng này.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"signature_delivery_orders\\" help=\\"Yêu cầu chữ ký trên lệnh giao hàng của bạn\\">\\n                                <field name=\\"group_stock_sign_delivery\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Đơn vị vận chuyển\\" name=\\"shipping_connectors_setting_container\\">\\n                            <setting id=\\"compute_shipping_costs_ups\\" help=\\"Tính toán phí giao hàng và giao bằng UPS\\">\\n                                <div class=\\"o_form_label\\">Đơn vị vận chuyển UPS</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Tài liệu\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with UPS<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_dhl\\" help=\\"Tính toán phí giao hàng và giao bằng DHL\\">\\n                                <div class=\\"o_form_label\\">Đơn vị vận chuyển DHL</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Tài liệu\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with DHL<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_fedex\\" help=\\"Tính toán phí giao hàng và giao bằng FedEx\\">\\n                                <div class=\\"o_form_label\\">Đơn vị vận chuyển FedEx</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Tài liệu\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with FedEx<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_usps\\" help=\\"Tính toán phí giao hàng và giao bằng USPS\\">\\n                                <div class=\\"o_form_label\\">Đơn vị vận chuyển USPS</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Tài liệu\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with USPS<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_bpost\\" help=\\"Tính toán phí giao hàng và giao bằng bpost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_bpost\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n\\n                            <setting id=\\"compute_shipping_costs_easypost\\" help=\\"Tính toán phí giao hàng và giao bằng Easypost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_easypost\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_sendcloud\\" help=\\"Tính toán phí giao hàng và giao bằng Sendcloud\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_sendcloud\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_shiprocket\\" help=\\"Tính toán phí giao hàng và giao bằng Shiprocket\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_shiprocket\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_starshipit\\" help=\\"Tính toán phí vận chuyển và vận chuyển bằng Starshipit\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_starshipit\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_envia\\" help=\\"Tính toán phí giao hàng và giao bằng Envia.com\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_envia\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Sản phẩm\\" name=\\"product_setting_container\\">\\n                            <setting id=\\"product_attributes\\" help=\\"Thiết lập thuộc tính sản phẩm (vd: màu sắc, kích thước) để quản lý các biến thể\\" documentation=\\"/applications/sales/sales/products_prices/products/variants.html\\">\\n                                <field name=\\"group_product_variant\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_product_variant\\">\\n                                        <button name=\\"192\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Thuộc tính\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"sell_purchase_uom\\" help=\\"Bán và mua sản phẩm theo các đơn vị tính hoặc quy cách đóng gói khác nhau\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/products/uom.html\\">\\n                                <field name=\\"group_uom\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_uom\\">\\n                                        <button name=\\"78\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Đơn vị &amp; đóng gói\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Truy xuất nguồn gốc\\" id=\\"production_lot_info\\">\\n                            <setting id=\\"full_traceability\\" help=\\"Truy xuất nguồn gốc đầy đủ từ nhà cung cấp đến khách hàng\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/lots_serial_numbers/differences.html\\">\\n                                <field name=\\"group_stock_production_lot\\"/>\\n                                <div class=\\"row mt-2\\" invisible=\\"not group_stock_production_lot\\">\\n                                    <field name=\\"group_stock_lot_print_gs1\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    <div class=\\"col ps-0\\">\\n                                        <label for=\\"group_stock_lot_print_gs1\\"/>\\n                                        <div class=\\"text-muted\\">Sử dụng ma trận dữ liệu danh pháp GS1 bất cứ khi nào mã vạch được in cho lô và số sê-ri.</div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"row mt-2\\" invisible=\\"not group_stock_production_lot or not group_stock_tracking_lot\\">\\n                                    <span class=\\"o_form_label\\">Thành phần kiện hàng có thể quét được</span>\\n                                    <div class=\\"col-12\\">\\n                                        <div class=\\"text-muted\\">Nếu dấu phân cách được xác định, thì mã QR chứa tất cả số sê-ri có trong kiện hàng sẽ được tạo, bằng (các) ký tự đã xác định để phân tách từng số</div>\\n                                    </div>\\n                                    <div class=\\"col\\">\\n                                        <label for=\\"barcode_separator\\"/>\\n                                        <field name=\\"barcode_separator\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"expiration_dates_serial_numbers\\" help=\\"Đặt ngày hết hạn theo số lô &amp; số sê-ri\\" invisible=\\"not group_stock_production_lot\\" title=\\"Theo dõi các ngày sau đây theo số lô và số sê-ri: tốt nhất trước ngày, xuất kho, hết hạn, cảnh báo. Những ngày này được đặt tự động khi tạo số lô và số sê-ri dựa trên các giá trị sản phẩm (tính theo ngày).\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/lots_serial_numbers/expiration_dates.html\\">\\n                                <field name=\\"module_product_expiry\\"/>\\n                            </setting>\\n                            <setting help=\\"Số lô &amp; sê-ri sẽ xuất hiện trên phiếu giao hàng\\" invisible=\\"not group_stock_production_lot\\" id=\\"group_lot_on_delivery_slip\\">\\n                                <field name=\\"group_lot_on_delivery_slip\\"/>\\n                            </setting>\\n                            <setting id=\\"owner_stored_products\\" help=\\"Chọn người phụ trách các sản phẩm được lưu kho\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/misc/owned_stock.html\\">\\n                                <field name=\\"group_stock_tracking_owner\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Kho hàng\\" name=\\"warehouse_setting_container\\">\\n                            <setting id=\\"track_product_location\\" help=\\"Theo dõi vị trí sản phẩm trong kho hàng của bạn\\" documentation=\\"/applications/inventory_and_mrp/inventory/warehouses_storage/inventory_management/use_locations.html\\" title=\\"Lưu trữ sản phẩm ở các vị trí cụ thể trong kho của bạn (ví dụ: thùng, giá đỡ) và theo dõi tồn kho tương ứng.\\">\\n                                <field name=\\"group_stock_multi_locations\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_multi_locations\\">\\n                                        <button name=\\"394\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Vị trí\\" class=\\"btn-link\\"/><br/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"use_own_routes\\" help=\\"Sử dụng các tuyến của bạn\\" documentation=\\"/applications/inventory_and_mrp/inventory/routes/concepts/use_routes.html\\" title=\\"Thêm và tùy chỉnh hoạt động theo tuyến để xử lý các điều chuyển sản phẩm trong (các) kho hàng của bạn: ví dụ: dỡ hàng&gt; kiểm soát chất lượng&gt; tồn kho cho các sản phẩm sắp nhập, lấy hàng &gt; đóng gói &gt; giao hàng. Bạn cũng có thể thiết lập chiến lược lưu kho trong các vị trí của kho hàng để chuyển sản phẩm sắp nhập đến các vị trí phụ cụ thể ngay lập tức (ví dụ: thùng, giá đỡ cụ thể).\\">\\n                                <field name=\\"group_stock_adv_location\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_adv_location\\">\\n                                        <button name=\\"354\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Cài đặt tuyến cung ứng của kho hàng\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Lên lịch nâng cao\\" id=\\"schedule_info\\">\\n                            <setting company_dependent=\\"1\\" help=\\"Thiết lập khoảng thời gian dự trù để hệ thống kích hoạt quy tắc tái đặt hàng sớm hơn, từ đó giúp chủ động bổ sung hàng và tránh chậm trễ, hoặc đặt về ('0 ngày') để chỉ đặt hàng đúng lúc cần, hạn chế tồn kho dư thừa.\\">\\n                                <field name=\\"horizon_days\\" class=\\"oe_inline\\"/><span> ngày</span>\\n                            </setting>\\n                            <div id=\\"sale_security_lead\\"/>\\n                            <div id=\\"purchase_po_lead\\"/>\\n                        </block>\\n                        <block title=\\"Logistics\\" name=\\"request_vendor_setting_container\\">\\n                            <setting title=\\"Một tuyến dropship được bổ sung để áp dụng cho sản phẩm với mục đích yêu cầu nhà cung cấp giao hàng cho khách hàng của bạn. Một sản phẩm để dropship sẽ tạo ra một yêu cầu báo giá khi đơn bán hàng được xác nhận. Đây là một quy trình theo yêu cầu. Địa chỉ giao hàng được yêu cầu sẽ là địa chỉ giao hàng của khách hàng, không phải là kho hàng của bạn.\\" help=\\"Yêu cầu nhà cung cấp giao hàng tới khách hàng của bạn\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/delivery/dropshipping.html\\">\\n                                <field name=\\"module_stock_dropshipping\\"/>\\n                            </setting>\\n                            <setting title=\\"Điều này sẽ thêm tuyến Bổ sung theo đơn đặt hàng (MTO) để áp dụng cho sản phẩm nhằm tạo ra đơn bổ sung hàng theo nhu cầu, được liên kết trực tiếp với, ví dụ như, các đơn bán hàng ngay khi chúng được xác nhận. Các đơn mua hàng, lệnh sản xuất,... sẽ được kích hoạt tùy thuộc vào phương thức bổ sung hàng được thiết lập trên sản phẩm (theo tuyến Mua hoặc Sản xuất).\\" help=\\"Cho phép Sản xuất theo đơn đặt hàng hoặc tự động tạo PO khi sản phẩm được bán và thiết lập liên kết trực tiếp giữa các tài liệu.\\" documentation=\\"/applications/inventory_and_mrp/inventory/warehouses_storage/replenishment/mto.html\\">\\n                                <field name=\\"replenish_on_order\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                    <app data-string="Inventory" string="Inventory" name="stock" groups="stock.group_stock_manager">\n                        <block title="Operations" name="operations_setting_container">\n                            <setting id="product_packs_tracking" documentation="/applications/inventory_and_mrp/inventory/product_management/product_tracking/package.html" title="Put your products in packs (e.g. parcels, boxes) and track them" help="Put your products in packs (e.g. parcels, boxes) and track them">\n                                <field name="group_stock_tracking_lot"/>\n                            </setting>\n                            <setting id="process_transfers" help="Optimize your transfers by grouping operations together and assigning jobs to workers" documentation="/applications/inventory_and_mrp/inventory/management/misc/batch_transfers.html">\n                                <field name="module_stock_picking_batch"/>\n                            </setting>\n                            <setting id="warning_info" string="Partner-Specific Instructions" help="Display instructions tailored to the customer or vendor on stock operations.">\n                                <field name="group_warning_stock"/>\n                            </setting>\n                            <setting id="quality_control" help="Add quality checks to your transfer operations" documentation="/applications/inventory_and_mrp/manufacturing/management/quality_control.html">\n                                <field name="module_quality_control" widget="upgrade_boolean"/>\n                                <div class="row mt-2" invisible="not module_quality_control">\n                                    <field name="module_quality_control_worksheet" widget="upgrade_boolean" class="col flex-grow-0 ml16 mr0 pe-2"/>\n                                    <div class="col ps-0">\n                                        <label for="module_quality_control_worksheet"/>\n                                        <div class="text-muted">\n                                            Create customizable worksheets for your quality checks\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="annual_inventory_date" groups="stock.group_stock_manager" string="Annual Inventory Day and Month" help="Day and month that annual inventory counts should occur.">\n                                <div class="content-group">\n                                    <field name="annual_inventory_day" class="o_light_label" style="width: 30px;"/>\n                                    <field name="annual_inventory_month" class="o_light_label"/>\n                                </div>\n                            </setting>\n                            <setting id="reception_report" help="View and allocate received quantities.">\n                                <field name="group_stock_reception_report"/>\n                            </setting>\n                        </block>\n                        <block title="Barcode" name="barcode_setting_container">\n                            <setting id="process_operations_barcodes" help="Process operations faster with barcodes" company_dependent="1" documentation="/applications/inventory_and_mrp/inventory/barcode/setup/software.html">\n                                <field name="module_stock_barcode" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="process_stock_barcodelookup" string="Stock Barcode Database" help="" documentation="https://www.barcodelookup.com/api-documentation">\n                                <field name="module_stock_barcode_barcodelookup" placeholder="e.g. d7vctmiv2rwgenebha8bxq7irooudn"/>\n                                <span class="text-muted">\n                                    Create products easily by scanning using <a href="https://www.barcodelookup.com" target="_blank">barcodelookup.com</a> in barcode.\n                                </span>\n                            </setting>\n                        </block>\n                        <block title="Shipping" name="shipping_setting_container">\n                            <setting id="delivery" help="Compute shipping costs" title="Shipping connectors allow to compute accurate shipping costs, print shipping labels and request carrier picking at your warehouse to ship to the customer. Apply shipping connector from delivery methods.">\n                                <field name="module_delivery"/>\n                            </setting>\n                            <setting id="stock_fleet" help="Transport management: organize packs in your fleet, or carriers.">\n                                <field name="module_stock_fleet"/>\n                            </setting>\n                            <setting id="stock_move_email" company_dependent="1" string="Email Confirmation" help="Send an automatic confirmation email when Delivery Orders are done">\n                                <field name="stock_move_email_validation"/>\n                            </setting>\n                            <setting id="stock_text_confirmation" company_dependent="1" help="Send an automatic confirmation Text Message when Delivery Orders are done" string="Text Confirmation">\n                                <field name="stock_text_confirmation"/>\n         