ide\\">\\n                    <div class=\\"o_we_bg_filter bg-black-25\\"/>\\n                    <div class=\\"container oe_unremovable\\">\\n                        <div class=\\"row\\">\\n                            <div class=\\"carousel-content col-lg-6\\">\\n                                <h2 class=\\"display-3-fs\\">Tiêu đề slide</h2>\\n                                <p class=\\"lead\\">Sử dụng đoạn mã này để trình bày nội dung của bạn ở định dạng giống như trình chiếu. Đừng viết về sản phẩm hoặc dịch vụ ở đây, hãy viết về giải pháp.</p>\\n                                <p>\\n                                    <a href=\\"/contactus\\" class=\\"btn btn-primary o_translate_inline\\">Liên hệ chúng tôi</a>\\n                                </p>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- #02 -->\\n                <div class=\\"carousel-item oe_img_bg o_bg_img_center pt96 pb96\\" style=\\"background-image: url('/web/image/website.s_carousel_default_image_2');\\" data-name=\\"Slide\\">\\n                    <div class=\\"container oe_unremovable\\">\\n                        <div class=\\"row\\">\\n                            <div class=\\"carousel-content col-lg-8 offset-lg-2 text-center pt48 pb40\\">\\n                                <h2 class=\\"display-3-fs\\">Slogan thông minh</h2>\\n                                <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                    <hr class=\\"w-25 mx-auto\\"/>\\n                                </div>\\n                                <p class=\\"lead\\">Việc kể chuyện rất mạnh mẽ. <br/> Nó thu hút độc giả.</p>\\n                                <p><a href=\\"/\\" class=\\"btn btn-primary o_translate_inline\\">Bắt đầu hành trình của bạn</a></p>\\n                            </div>\\n                        </div>\\n                    </div>\\n          