1343	16	\N	1	1	Pricelist	\N	website.s_product_catalog	qweb	website/views/snippets/s_product_catalog.xml	primary	{"en_US": "<t name=\\"Pricelist\\" t-name=\\"website.s_product_catalog\\">\\n    <section class=\\"s_product_catalog oe_img_bg o_bg_img_center oe_custom_bg pt64 pb64\\" style=\\"background-image: url('/web/image/website.s_product_catalog_default_image');\\" data-vcss=\\"002\\">\\n        <div class=\\"o_we_bg_filter bg-white-85\\"/>\\n        <div class=\\"container\\">\\n            <h2 class=\\"h3-fs\\" style=\\"text-align: center;\\">Our Menu</h2>\\n            <p class=\\"lead\\" style=\\"text-align: center;\\">Handcrafted Delights: Everything Homemade, Just for You.</p>\\n            <p><br/></p>\\n            <div class=\\"row\\">\\n                <div class=\\"col-lg-6 pt16 pb16\\">\\n                    <h3 class=\\"h4-fs\\">Pastries</h3>\\n                    <ul class=\\"list-unstyled my-3\\">\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Croissant</t>\\n                            <t t-set=\\"price\\">$1.50</t>\\n                            <t t-set=\\"description\\">A buttery, flaky pastry with a golden-brown crust, perfect for breakfast or a light snack.</t>\\n                        </t>\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Cinnamon Roll</t>\\n                            <t t-set=\\"price\\">$3.00</t>\\n                            <t t-set=\\"description\\">Soft, sweet dough rolled with cinnamon and sugar, topped with a rich cream cheese frosting.</t>\\n                        </t>\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Sourdough Bread</t>\\n                            <t t-set=\\"price\\">$5.00</t>\\n                            <t t-set=\\"description\\">A crusty loaf with a chewy interior, made with a naturally fermented sourdough starter for a tangy flavor.</t>\\n                        </t>\\n                    </ul>\\n                </div>\\n                <div class=\\"col-lg-6 pt16 pb16\\">\\n                    <h3 class=\\"h4-fs\\">Cakes</h3>\\n                    <ul class=\\"list-unstyled my-3\\">\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Classic Cheesecake</t>\\n                            <t t-set=\\"price\\">$25.00</t>\\n                            <t t-set=\\"description\\">A creamy, smooth cheesecake with a graham cracker crust, topped with a layer of fresh fruit or chocolate ganache.</t>\\n                        </t>\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Red Velvet Cake</t>\\n                            <t t-set=\\"price\\">$28.00</t>\\n                            <t t-set=\\"description\\">A moist, red-hued cake with layers of cream cheese frosting, perfect for any special occasion.</t>\\n                        </t>\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Carrot Cake</t>\\n                            <t t-set=\\"price\\">$26.00</t>\\n                            <t t-set=\\"description\\">A spiced cake loaded with grated carrots, nuts, and a hint of cinnamon, topped with a tangy cream cheese frosting.</t>\\n                        </t>\\n                    </ul>\\n                </div>\\n            </div>\\n        </div>\\n    </section>\\n</t>", "vi_VN": "<t name=\\"Pricelist\\" t-name=\\"website.s_product_catalog\\">\\n    <section class=\\"s_product_catalog oe_img_bg o_bg_img_center oe_custom_bg pt64 pb64\\" style=\\"background-image: url('/web/image/website.s_product_catalog_default_image');\\" data-vcss=\\"002\\">\\n        <div class=\\"o_we_bg_filter bg-white-85\\"/>\\n        <div class=\\"container\\">\\n            <h2 class=\\"h3-fs\\" style=\\"text-align: center;\\">Menu của chúng tôi</h2>\\n            <p class=\\"lead\\" style=\\"text-align: center;\\">Đồ thủ công: Mọi thứ được tự làm, chỉ dành cho bạn.</p>\\n            <p><br/></p>\\n            <div class=\\"row\\">\\n                <div class=\\"col-lg-6 pt16 pb16\\">\\n                    <h3 class=\\"h4-fs\\">Bánh ngọt</h3>\\n                    <ul class=\\"list-unstyled my-3\\">\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Bánh sừng bò</t>\\n                            <t t-set=\\"price\\">$1.50</t>\\n                            <t t-set=\\"description\\">Một loại bánh ngọt mềm mịn với lớp vỏ vàng nâu, thích hợp cho bữa sáng hoặc bữa ăn nhẹ.</t>\\n                        </t>\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Bánh quế vòng</t>\\n                            <t t-set=\\"price\\">$3.00</t>\\n                            <t t-set=\\"description\\">Bột mềm, ngọt được cán với quế và đường, phủ một lớp kem phô mai béo ngậy.</t>\\n                        </t>\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Bánh mì chua</t>\\n                            <t t-set=\\"price\\">$5.00</t>\\n                            <t t-set=\\"description\\">Một ổ bánh mì giòn với phần lõi dai, được làm bằng bột chua lên men tự nhiên để mang vị chua.</t>\\n                        </t>\\n                    </ul>\\n                </div>\\n                <div class=\\"col-lg-6 pt16 pb16\\">\\n                    <h3 class=\\"h4-fs\\">Bánh</h3>\\n                    <ul class=\\"list-unstyled my-3\\">\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Bánh phô mai cổ điển</t>\\n                            <t t-set=\\"price\\">$25.00</t>\\n                            <t t-set=\\"description\\">Một chiếc bánh phô mai mịn, béo ngậy với lớp vỏ bánh quy graham, phủ một lớp trái cây tươi hoặc ganache sô cô la.</t>\\n                        </t>\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Bánh red velvet</t>\\n                            <t t-set=\\"price\\">$28.00</t>\\n                            <t t-set=\\"description\\">Một chiếc bánh mềm mại, màu đỏ với nhiều lớp kem phô mai phủ bên trên, hoàn hảo cho mọi dịp đặc biệt.</t>\\n                        </t>\\n                        <t t-call=\\"website.s_product_catalog_dish\\">\\n                            <t t-set=\\"name\\">Bánh cà rốt</t>\\n                            <t t-set=\\"price\\">$26.00</t>\\n                            <t t-set=\\"description\\">Một chiếc bánh đậm vị với cà rốt nạo, các loại hạt và một chút quế, phủ trên cùng là lớp kem phô mai chua ngọt.</t>\\n                        </t>\\n                    </ul>\\n                </div>\\n            </div>\\n        </div>\\n    </section>\\n</t>"}	<?xml version="1.0"?>\n<t name="Pricelist" t-name="website.s_product_catalog">\n    <section class="s_product_catalog oe_img_bg o_bg_img_center oe_custom_bg pt64 pb64" style="background-image: url('/web/image/website.s_product_catalog_default_image');" data-vcss="002">\n        <div class="o_we_bg_filter bg-white-85"/>\n        <div class="container">\n            <h2 class="h3-fs" style="text-align: center;">Our Menu</h2>\n            <p class="lead" style="text-align: center;">Handcrafted Delights: Everything Homemade, Just for You.</p>\n            <p><br/></p>\n            <div class="row">\n                <div class="col-lg-6 pt16 pb16">\n                    <h3 class="h4-fs">Pastries</h3>\n                    <ul class="list-unstyled my-3">\n                        <t t-call="website.s_product_catalog_dish">\n                            <t t-set="name">Croissant</t>\n                            <t t-set="price">$1.50</t>\n                            <t t-set="description">A buttery, flaky pastry with a golden-brown crust, perfect for breakfast or a light snack.</t>\n                        </t>\n                        <t t-call="website.s_product_catalog_dish">\n                            <t t-set="name">Cinnamon Roll</t>\n                            <t t-set="price">$3.00</t>\n                            <t t-set="description">Soft, sweet dough rolled with cinnamon and sugar, topped with a rich cream cheese frosting.</t>\n                        </t>\n                        <t t-call="website.s_product_catalog_dish">\n                            <t t-set="name">Sourdough Bread</t>\n                            <t t-set="price">$5.00</t>\n                            <t t-set="description">A crusty loaf with a chewy interior, made with a naturally fermented sourdough starter for a tangy flavor.</t>\n                        </t>\n                    </ul>\n                </div>\n                <div class="col-lg-6 pt16 pb16">\n                    <h3 class="h4-fs">Cakes</h3>\n                    <ul class="list-unstyled my-3">\n                        <t t-call="website.s_product_catalog_dish">\n                            <t t-set="name">Classic Cheesecake</t>\n                            <t t-set="price">$25.00</t>\n                            <t t-set="description">A creamy, smooth cheesecake with a graham cracker crust, topped with a layer of fresh fruit or chocolate ganache.</t>\n                        </t>\n                        <t t-call="website.s_product_catalog_dish">\n                            <t t-set="name">Red Velvet Cake</t>\n                            <t t-set="price">$28.00</t>\n                            <t t-set="description">A moist, red-hued cake with layers of cream cheese frosting, perfect for any special occasion.</t>\n              