              <div class="container s_allow_columns">\n                                    <img src="/web/image/website.s_tabs_images_default_image_3" class="img img-fluid rounded" alt="" style="width: 100% !important;"/>\n                                </div>\n                            </section>\n                        </div>\n                    </div>\n                    <div class="tab-pane fade" id="nav_tabs_images_content_4" role="tabpanel" aria-labelledby="nav_tabs_images_link_4">\n                        <div class="oe_structure oe_empty">\n                            <section class="s_text_block" data-snippet="s_text_block" data-name="Tab">\n                                <div class="container s_allow_columns">\n                                    <img src="/web/image/website.s_tabs_images_default_image_4" class="img img-fluid rounded" alt="" style="width: 100% !important;"/>\n                                </div>\n                            </section>\n                        </div>\n                    </div>\n                    <div class="tab-pane fade" id="nav_tabs_images_content_5" role="tabpanel" aria-labelledby="nav_tabs_images_link_5">\n                        <div class="oe_structure oe_empty">\n                            <section class="s_text_block" data-snippet="s_text_block" data-name="Tab">\n                                <div class="container s_allow_columns">\n                                    <img src="/web/image/website.s_tabs_images_default_image_5" class="img img-fluid rounded" alt="" style="width: 100% !important;"/>\n                                </div>\n                            </section>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n</t>\n\n	f	t	2026-10-13 14:41:44.098182	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
1365	16	\N	1	1	Table of Content	\N	website.s_table_of_content	qweb	website/views/snippets/s_table_of_content.xml	primary	{"en_US": "<t name=\\"Table of Content\\" t-name=\\"website.s_table_of_content\\">\\n    <section class=\\"s_table_of_content pt24 pb24 o_cc o_cc1\\">\\n        <div class=\\"container\\">\\n            <div class=\\"row s_nb_column_fixed\\">\\n                <div class=\\"col-lg-3 s_table_of_content_navbar_wrap s_table_of_content_navbar_sticky s_table_of_content_vertical_navbar d-print-none d-none d-lg-block o_not_editable o_cc o_cc1\\" data-name=\\"Navbar\\">\\n                    <div class=\\"s_table_of_content_navbar list-group o_no_link_popover\\" style=\\"top: 76px; max-height: calc(100vh - 96px);\\">\\n                        <a href=\\"#table_of_content_heading_1_1\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0 active\\">Intuitive system</a>\\n                        <a href=\\"#table_of_content_heading_1_2\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0\\">Design features</a>\\n                    </div>\\n                </div>\\n                <div class=\\"col-lg-9 s_table_of_content_main oe_structure oe_empty\\" data-name=\\"Content\\">\\n                    <section class=\\"s_text_block pt0 pb64\\" data-snippet=\\"s_text_block\\" data-name=\\"Section\\">\\n                        <div class=\\"container s_allow_columns\\">\\n                            <h2 id=\\"table_of_content_heading_1_1\\" class=\\"h3-fs\\" data-anchor=\\"true\\">Intuitive system</h2>\\n                            <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                <hr class=\\"w-100 mx-auto\\"/>\\n                            </div>\\n                            <p class=\\"lead\\">\\n                                Our intuitive system ensures effortless navigation for users of all skill levels. Its clean interface and logical organization make tasks easy to complete. With tooltips and contextual help, users quickly become productive, enjoying a smooth and efficient experience.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">What you see is what you get</h3>\\n                            <p>\\n                                Insert text styles like headers, bold, italic, lists, and fonts with a simple WYSIWYG editor. Flexible and easy to use, it lets you design and format documents in real time. No coding knowledge is needed, making content creation straightforward and enjoyable for everyone.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Customization tool</h3>\\n                            <p>\\n                                Click and change content directly from the front-end, avoiding complex backend processes. This tool allows quick updates to text, images, and elements right on the page, streamlining your workflow and maintaining control over your content.\\n                            </p>\\n                        </div>\\n                    </section>\\n                    <section class=\\"s_text_block pt0 pb64\\" data-snippet=\\"s_text_block\\" data-name=\\"Section\\">\\n                        <div class=\\"container s_allow_columns\\">\\n                            <h2 id=\\"table_of_content_heading_1_2\\" class=\\"h3-fs\\" data-anchor=\\"true\\">Design features</h2>\\n                            <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                <hr class=\\"w-100 mx-auto\\"/>\\n                            </div>\\n                            <p class=\\"lead\\">\\n                                Our design features offer a range of tools to create visually stunning websites. Utilize WYSIWYG editors, drag-and-drop building blocks, and Bootstrap-based templates for effortless customization. With professional themes and an intuitive system, you can design with ease and precision, ensuring a polished, responsive result.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Building blocks system</h3>\\n                            <p>\\n                                Create pages from scratch by dragging and dropping customizable building blocks. This system simplifies web design, making it accessible to all skill levels. Combine headers, images, and text sections to build cohesive layouts quickly and efficiently.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Bootstrap-Based Templates</h3>\\n                            <p>\\n                                Design Odoo templates easily with clean HTML and Bootstrap CSS. These templates offer a responsive, mobile-first design, making them simple to customize and perfect for any web project, from corporate sites to personal blogs.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                        </div>\\n                    </section>\\n                </div>\\n            </div>\\n        </div>\\n    </section>\\n</t>", "vi_VN": "<t name=\\"Table of Content\\" t-name=\\"website.s_table_of_content\\">\\n    <section class=\\"s_table_of_content pt24 pb24 o_cc o_cc1\\">\\n        <div class=\\"container\\">\\n            <div class=\\"row s_nb_column_fixed\\">\\n                <div class=\\"col-lg-3 s_table_of_content_navbar_wrap s_table_of_content_navbar_sticky s_table_of_content_vertical_navbar d-print-none d-none d-lg-block o_not_editable o_cc o_cc1\\" data-name=\\"Navbar\\">\\n                    <div class=\\"s_table_of_content_navbar list-group o_no_link_popover\\" style=\\"top: 76px; max-height: calc(100vh - 96px);\\">\\n                        <a href=\\"#table_of_content_heading_1_1\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0 active\\">Hệ thống trực quan</a>\\n                        <a href=\\"#table_of_content_heading_1_2\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0\\">Tính năng thiết kế</a>\\n                    </div>\\n                </div>\\n                <div class=\\"col-lg-9 s_table_of_content_main oe_structure oe_empty\\" data-name=\\"Content\\">\\n                    <section class=\\"s_text_block pt0 pb64\\" data-snippet=\\"s_text_block\\" data-name=\\"Section\\">\\n                        <div class=\\"container s_allow_columns\\">\\n                            <h2 id=\\"table_of_content_heading_1_1\\" class=\\"h3-fs\\" data-anchor=\\"true\\">Hệ thống trực quan</h2>\\n                            <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                <hr class=\\"w-100 mx-auto\\"/>\\n                            </div>\\n                            <p class=\\"lead\\">\\n                                Hệ thống trực quan của chúng tôi đảm bảo điều hướng dễ dàng cho người dùng ở mọi cấp độ kỹ năng. Giao diện gọn gàng và tổ chức hợp lý giúp hoàn thành nhiệm vụ một cách đơn giản. Với các chú thích và trợ giúp theo ngữ cảnh, người dùng có thể nhanh chóng làm việc năng suất, tận hưởng trải nghiệm mượt mà và hiệu quả.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Những gì bạn thấy là những gì bạn nhận được</h3>\\n                            <p>\\n                                Chèn các kiểu văn bản như header, in đậm, in nghiêng, danh sách và phông chữ bằng trình soạn thảo WYSIWYG đơn giản. Trình soạn thảo linh hoạt và dễ sử dụng này cho phép bạn thiết kế và định dạng tài liệu theo thời gian thực. Không cần kiến thức về mã hóa, giúp việc tạo nội dung trở nên đơn giản và thú vị cho mọi người.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Công cụ tùy chỉnh</h3>\\n                            <p>\\n                                Nhấp và thay đổi nội dung ngay từ front-end, tránh các quy trình backend phức tạp. Công cụ này cho phép nhanh chóng cập nhật văn bản, hình ảnh và các thành phần ngay trên trang, hợp lý hóa quy trình làm việc và duy trì quyền kiểm soát nội dung của bạn.\\n                            </p>\\n                        </div>\\n                    </section>\\n                    <section class=\\"s_text_block pt0 pb64\\" data-snippet=\\"s_text_block\\" data-name=\\"Section\\">\\n                        <div class=\\"container s_allow_columns\\">\\n                            <h2 id=\\"table_of_content_heading_1_2\\" class=\\"h3-fs\\" data-anchor=\\"true\\">Tính năng thiết kế</h2>\\n                            <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                <hr class=\\"w-100 mx-auto\\"/>\\n                            </div>\\n                            <p class=\\"lead\\">\\n                                Các tính năng thiết kế của chúng tôi cung cấp nhiều công cụ để tạo ra những trang web trực quan tuyệt đẹp. Sử dụng trình soạn thảo WYSIWYG, các khối dựng kéo-thả và các mẫu Bootstrap để tùy chỉnh dễ dàng. Với nhiều giao diện chuyên nghiệp và hệ thống trực quan, bạn có thể thiết kế dễ dàng và chính xác, đảm bảo kết quả được trau chuốt và mang tính phản hồi.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Hệ thống khối dựng</h3>\\n                            <p>\\n                                Tạo trang từ đầu bằng cách kéo và thả các khối dựng có thể tùy chỉnh. Hệ thống này đơn giản hóa thiết kế web để mọi người ở mọi cấp độ kỹ năng đều có thể sử dụng. Kết hợp các header, hình ảnh và phần văn bản để xây dựng bố cục gắn kết nhanh chóng và hiệu quả.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Mẫu dạng Bootstrap</h3>\\n                            <p>\\n                                Thiết kế mẫu Odoo dễ dàng với HTML và Bootstrap CSS sạch. Các mẫu này cung cấp thiết kế đáp ứng, ưu tiên thiết bị di động, giúp tùy chỉnh dễ dàng và hoàn hảo cho mọi dự án web, từ trang web của công ty đến blog cá nhân.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                        </div>\\n                    </section>\\n                </div>\\n            </div>\\n        </div>\\n    </section>\\n</t>"}	<?xml version="1.0"?>\n<t name="Table of Content" t-name="website.s_table_of_content">\n    <section class="s_table_of_content pt24 pb24 o_cc o_cc1">\n        <div class="container">\n            <div class="row s_nb_column_fixed">\n                <div class="col-lg-3 s_table_of_content_navbar_wrap s_table_of_content_navbar_sticky s_table_of_content_vertical_navbar d-print-none d-none d-lg-block o_not_editable o_cc o_cc1" data-name="Navbar">\n                    <div class="s_table_of_content_navbar list-group o_no_link_popover" style="top: 76px; max-height: calc(100vh - 96px);">\n                        <a href="#table_of_content_heading_1_1" class="table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0 active">Intuitive system</a>\n                        <a href="#table_of_content_heading_1_2" class="table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0">De