 <attribute name="class" add="o_colored_level pt48 pb56" remove="pt80 pb80" separator=" "/>\n    </xpath>\n    <xpath expr="//h2" position="replace">\n        <h2>Our Story</h2>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p>Embark on a journey through time as we share the story of our humble beginnings. What started as a simple idea in a garage has evolved into an innovative force in the industry.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_about_full_s_image_text</attribute></xpath></data>\n\n	f	t	2026-10-13 14:41:44.098182	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
1566	16	1565	1	1	new_page_template_landing_2_s_three_columns	\N	website.new_page_template_landing_2_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_landing_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Personalized Workouts</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Nutritional Guidance</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Progress Tracking</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our experienced fitness coaches design workouts that align with your goals, fitness level, and preferences.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Achieve holistic health with personalized nutritional advice that complements your workouts, promoting overall well-being.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">We monitor your progress meticulously, adjusting your plan as needed to ensure continuous improvement and results.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_landing_2_s_three_columns</attribute></xpath></data>", "vi_VN": "<data inherit_id=\\"website.new_page_template_landing_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Bài tập luyện cá nhân</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Hướng dẫn dinh dưỡng</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Theo dõi tiến độ</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Các huấn luyện viên thể dục thẩm mỹ giàu kinh nghiệm của chúng tôi thiết kế những bài tập phù hợp với mục tiêu, mức độ thể lực và sở thích của bạn.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Khoẻ mạnh về mọi mặt với lời khuyên dinh dưỡng cá nhân giúp bổ sung cho quá trình tập luyện của bạn, từ đó thúc đẩy sức khỏe tổng thể.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Chúng tôi theo dõi tiến độ của bạn một cách tỉ mỉ, điều chỉnh kế hoạch khi cần thiết để đảm bảo kết quả và cải thiện liên tục.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_landing_2_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_landing_s_three_columns" primary="True">\n    <xpath expr="//h2|//h3|//h4|//h5" position="replace">\n        <h2 class="card-title h5-fs">Personalized Workouts</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[2]" position="replace">\n        <h2 class="card-title h5-fs">Nutritional Guidance</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[3]" position="replace">\n        <h2 class="card-title h5-fs">Progress Tracking</h2>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Our experienced fitness coaches design workouts that align with your goals, fitness level, and preferences.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">Achieve holistic health with personalized nutritional advice that complements your workouts, promoting overall well-being.</p>\n    </xpath>\n    <xpath expr="