1564	16	1563	1	1	new_page_template_about_s_three_columns	\N	website.new_page_template_about_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Our Story</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Our Mission</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Our Values</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Step into our past and witness the transformation of a simple idea into an innovative force. Our journey, born in a garage, reflects the power of passion and hard work.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our mission is to create transformative experiences and foster growth, driven by a relentless pursuit of innovation and a commitment to exceeding expectations.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our values shape our culture, influence our decisions, and guide us in providing exceptional service. They reflect our dedication to integrity, collaboration, and client satisfaction.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_s_three_columns</attribute></xpath></data>", "vi_VN": "<data inherit_id=\\"website.new_page_template_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Câu chuyện của chúng tôi</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Sứ mệnh của chúng tôi</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Giá trị của chúng tôi</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Bước vào quá khứ của chúng tôi và chứng kiến sự biến đổi từ một ý tưởng giản đơn thành sức mạnh đổi mới. Hành trình của chúng tôi, bắt nguồn từ một gara, phản ánh sức mạnh của niềm đam mê và sự chăm chỉ.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Sứ mệnh của chúng tôi là tạo ra những trải nghiệm mang tính thay đổi và thúc đẩy tăng trưởng, xuất phát từ việc không ngừng theo đuổi sự đổi mới và cam kết đạt được những điều trên cả mong đợi.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Các giá trị định hình văn hóa của chúng tôi, ảnh hưởng đến việc ra quyết định và là định hướng để chúng tôi cung cấp dịch vụ vượt trội. Chúng phản ánh sự chuyên tâm của chúng tôi vào tính toàn vẹn, hợp tác và sự hài lòng của khách hàng.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_s_three_columns" primary="True">\n    <xpath expr="//h2|//h3|//h4|//h5" position="replace">\n        <h2 class="card-title h5-fs">Our Story</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[2]" position="replace">\n        <h2 class="card-title h5-fs">Our Mission</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[3]" position="replace">\n        <h2 class="card-title h5-fs">Our Values</h2>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Step into our past and witness the transformation of a simple idea into an innovative force. Our journey, born in a garage, reflects the power of passion and hard work.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">Our mission is to create transformative experiences and foster growth, driven by a relentless pursuit of innovation and a commitment to exceeding expectations.</p>\n    </xpath>\n    <xpath expr="(//p)[3]" position="replace">\n        <p class="card-text">Our values shape our culture, influence our decisions, and guide us in providing exceptional service. They reflect our dedication to integrity, collaboration, and client satisfaction.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_about_s_three_columns</attribute></xpath></data>\n\n	f	t	2026-10-13 14:41:44.098182	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
