/h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Rèn luyện sức mạnh: </h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Chuyển đổi quá trình giảm cân</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Chương trình huấn luyện của chúng tôi kết hợp các kế hoạch thể dục thẩm mỹ được cá nhân hóa với những phương pháp thực hành chánh niệm, đảm bảo bạn đạt được cả sự hài hòa trong cơ thể và sự bình yên trong tâm trí.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Chương trình huấn luyện này cung cấp các bài tập chuyên biệt tập trung vào sức mạnh, hướng dẫn dinh dưỡng và huấn luyện chuyên môn. Hãy nâng cao trình độ thể lực của bạn và đạt những thành tích mà bạn chưa bao giờ nghĩ là có thể.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Với kế hoạch thể dục thẩm mỹ được cá nhân hóa, hướng dẫn dinh dưỡng riêng và hỗ trợ nhất quán, bạn sẽ đánh tan số cân dư thừa đồng thời xây dựng thói quen lành mạnh lâu dài.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_services_0_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_services_s_three_columns" primary="True">\n    <xpath expr="//h2|//h3|//h4|//h5" position="replace">\n        <h2 class="card-title h5-fs">Wellness Coaching</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[2]" position="replace">\n        <h2 class="card-title h5-fs">Strength Training: </h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[3]" position="replace">\n        <h2 class="card-title h5-fs">Weight Loss Transformation</h2>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Our Coaching combines personalized fitness plans with mindfulness practices, ensuring you achieve harmony in your body and peace in your mind.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">This coaching program offers specialized strength-focused workouts, nutrition guidance, and expert coaching. Elevate your fitness level and achieve feats you never thought possible.</p>\n    </xpath>\n    <xpath expr="(//p)[3]" position="replace">\n        <p class="card-text">With personalized fitness plans, tailored nutrition guidance, and consistent support, you'll shed unwanted pounds while building healthy habits that last.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_services_0_s_three_columns</attribute></xpath></data>\n\n	f	t	2026-10-13 14:41:44.098182	2026-10-13 14:41:44.098182	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
1571	16	1570	1	1	new_page_template_team_0_s_three_columns	\N	website.new_page_template_team_0_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_team_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Tony Fred, CEO</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Mich Stark, COO</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Aline Turner, CTO</h2>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Founder and chief visionary, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the software, marketing, and customer experience strategies.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Mich loves taking on challenges. With his multi-year experience as Commercial Director in the software industry, Mich has helped the company to get where it is today. Mich is among the best minds.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[3]//p|(//div[hasclass('card-wrapper')])[3]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Aline is one of the iconic people in life who can say they love what they do. She mentors 100+ in-house developers and looks after the community of thousands of developers.</p>\\n    </xpath>\\n    <xpath expr=\\"//img\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_1\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[2]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_2\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[3]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_3\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_team_0_s_three_columns</attribute></xpath></data>", "vi_VN": "<data inherit_id=\\"website.new_page_template_team_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h2|//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Tony Fred, CEO</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Mich Stark, COO</h2>\\n    </xpath>\\n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Aline Turner, CTO</h2>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Là nhà sáng lập và có tầm nhìn xa trông rộng, Tony là động lực phát triển của công ty. Anh thích tạo sự bận rộn cho bản thân bằng cách tham gia phát triển phần mềm, marketing, và các chiến lược về trải nghiệm khách hàng.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Mich rất thích thử thách. Với kinh nghiệm nhiều năm làm Giám đốc Thương mại trong ngành phần mềm, Mich đã giúp công ty có được vị trí như ngày hôm nay. Mich là một trong số những người tài giỏi nhất.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[3]//p|(//div[hasclass('card-wrapper')])[3]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Aline là một trong những hình mẫu yêu mến công việc tiêu biểu trong cuộc sống. Cô ấy cố vấn cho hơn 100 nhà phát triển nội bộ và hỗ trợ cộng đồng hàng nghìn nhà phát triển.</p>\\n    </xpath>\\n    <xpath expr=\\"//img\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_1\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[2]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_2\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[3]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_3\\" class=\\"o_card_img card-img-top\\"/>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_team_0_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_team_s_three_columns" primary="True">\n    <xpath expr="//h2|//h3|//h4|//h5" position="replace">\n        <h2 class="card-title h5-fs">Tony Fred, CEO</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[2]" position="replace">\n        <h2 class="card-title h5-fs">Mich Stark, COO</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[3]" position="replace">\n        <h2 class="card-title h5-fs">Aline Turner, CTO</h2>\n    </xpath>\n    <xpath expr="//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p" position="replace">\n        <p class="card-text">Founder and chief visionary, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the software, marketing, and customer experience strategies.</p>\n    </xpath>\n    <xpath expr="(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p" position="replace">\n        <p class="card-text">Mich loves taking on challenges. With his multi-year experience as Commercial Dire